CREATE OR REPLACE FUNCTION giro_authority.capture_giro_intent_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
  v_in            jsonb := NEW.pending_giro_intent;
  v_code          text;
  v_kind          text;
  v_ref           text;
  v_actor         text;
  v_sv            bigint;
  v_giro_id       text;
  v_anchor_uid    uuid;
  v_business_date date;
  v_fingerprint   text;
  v_delivery_type text;
  v_context       jsonb;
  v_sqlstate      text;
BEGIN
  NEW.pending_giro_intent := NULL;
  IF v_in IS NULL THEN
    RETURN NEW;
  END IF;

  BEGIN
    -- language-guard: allow-legacy tipo_consegna is the existing ordenes column name, read-only here
    v_delivery_type := upper(COALESCE(NEW.tipo_consegna, ''));
    v_context := jsonb_build_object('zona', NEW.zona, 'hora', NEW.hora, 'delivery_type', v_delivery_type,
                                    'service_session_id', NEW.service_session_id);
    SELECT ss.business_date INTO v_business_date
      FROM public.service_sessions ss WHERE ss.id = NEW.service_session_id;

    IF jsonb_typeof(v_in) IS DISTINCT FROM 'object'
       OR jsonb_typeof(v_in->'v') IS DISTINCT FROM 'number' OR (v_in->>'v') IS DISTINCT FROM '1'
       OR jsonb_typeof(v_in->'target_kind') IS DISTINCT FROM 'string'
       OR (v_in->>'target_kind') NOT IN ('GIRO', 'ANCHOR')
       OR jsonb_typeof(v_in->'target_ref') IS DISTINCT FROM 'string'
       OR length(btrim(v_in->>'target_ref')) NOT BETWEEN 1 AND 64 THEN
      v_code := 'CAPTURE_MALFORMED';
    ELSE
      v_kind := v_in->>'target_kind';
      v_ref := btrim(v_in->>'target_ref');
      IF (v_in->>'source') IS DISTINCT FROM 'operator_http'
         OR jsonb_typeof(v_in->'source') IS DISTINCT FROM 'string'
         OR jsonb_typeof(v_in->'actor') IS DISTINCT FROM 'string'
         OR NOT giro_authority.actor_valid_v1(v_in->>'actor')
         OR jsonb_typeof(v_in->'sv') IS DISTINCT FROM 'number'
         OR (v_in->>'sv') !~ '^[0-9]{1,18}$' THEN
        v_code := 'CAPTURE_UNTRUSTED_SOURCE';
      ELSE
        v_actor := btrim(v_in->>'actor');
        v_sv := (v_in->>'sv')::bigint;
        IF v_delivery_type <> 'DOMICILIO' OR NEW.table_session_id IS NOT NULL
           OR NEW.service_session_id IS NULL OR v_business_date IS NULL THEN
          v_code := 'CAPTURE_NOT_ELIGIBLE';
        ELSIF v_kind = 'GIRO' THEN
          SELECT mg.id INTO v_giro_id
            FROM public.manual_giros mg
           WHERE mg.id = v_ref AND mg.business_date = v_business_date;
          IF v_giro_id IS NULL THEN v_code := 'CAPTURE_TARGET_NOT_FOUND'; END IF;
        ELSE
          SELECT o.order_uid INTO v_anchor_uid
            FROM public.ordenes o
           WHERE o.id = v_ref AND o.id <> NEW.id
             AND o.service_session_id = NEW.service_session_id AND o.order_uid IS NOT NULL;
          IF v_anchor_uid IS NULL THEN v_code := 'CAPTURE_TARGET_NOT_FOUND'; END IF;
        END IF;
      END IF;
    END IF;

    IF v_code IS NULL THEN
      v_fingerprint := giro_authority.target_fingerprint_v1(v_kind, v_giro_id, v_anchor_uid);
      INSERT INTO giro_authority.giro_intents
        (order_uid, target_kind, target_ref, target_giro_id, target_order_uid, target_fingerprint,
         order_context, business_date, actor, sv, status, phase)
      VALUES (NEW.order_uid, v_kind, v_ref, v_giro_id, v_anchor_uid, v_fingerprint,
              v_context, v_business_date, v_actor, v_sv, 'PENDING', 'CAPTURE');
    ELSE
      INSERT INTO giro_authority.giro_intents
        (order_uid, target_kind, target_ref, order_context, business_date, actor, sv,
         status, phase, resolved_at, resolution_code)
      VALUES (NEW.order_uid, v_kind, v_ref, v_context, v_business_date, v_actor, v_sv,
              'REJECTED', 'CAPTURE', now(), v_code);
    END IF;
  EXCEPTION WHEN others THEN
    GET STACKED DIAGNOSTICS v_sqlstate = RETURNED_SQLSTATE;
    BEGIN
      INSERT INTO giro_authority.giro_intents (order_uid, status, phase, resolved_at, resolution_code, resolution_detail)
      VALUES (NEW.order_uid, 'REJECTED', 'CAPTURE', now(), 'CAPTURE_INTERNAL', jsonb_build_object('sqlstate', v_sqlstate));
    EXCEPTION WHEN others THEN
      RAISE WARNING 'GIRO_INTENT_CAPTURE_DIAGNOSTIC_LOST order_id=% sqlstate=%', NEW.id, v_sqlstate;
    END;
  END;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION giro_authority.hhmm_norm(p_value text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
  v text;
  h integer;
  m integer;
BEGIN
  IF p_value IS NULL THEN RETURN NULL; END IF;
  v := btrim(p_value);
  IF v !~ '^[0-9]{1,2}:[0-9]{2}$' THEN RETURN NULL; END IF;
  h := split_part(v, ':', 1)::integer;
  m := split_part(v, ':', 2)::integer;
  IF h > 23 OR m > 59 THEN RETURN NULL; END IF;
  RETURN lpad(h::text, 2, '0') || ':' || lpad(m::text, 2, '0');
END $function$

CREATE OR REPLACE FUNCTION giro_authority.insert_giro_v1(p_business_date date, p_hora_ref text, p_anchor uuid, p_actor text)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
  v_seq     integer;
  v_id      text;
  v_attempt integer := 0;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtext('giro_authority.seq'), hashtext(p_business_date::text));
  SELECT COALESCE(max(mg.seq), 0) INTO v_seq FROM public.manual_giros mg WHERE mg.giro_day = p_business_date;
  LOOP
    v_attempt := v_attempt + 1;
    v_seq := v_seq + 1;
    v_id := 'mg_' || to_char(p_business_date, 'YYMMDD') || '_' || v_seq::text;
    INSERT INTO public.manual_giros (id, seq, giro_day, business_date, created_by, hora_ref, anchor_order_uid)
    VALUES (v_id, v_seq, p_business_date, p_business_date, btrim(p_actor), p_hora_ref, p_anchor)
    ON CONFLICT DO NOTHING;
    IF FOUND THEN RETURN v_id; END IF;
    IF v_attempt >= 5 THEN
      RAISE EXCEPTION 'GIRO_SEQ_ALLOCATION_FAILED' USING ERRCODE = 'P0001';
    END IF;
  END LOOP;
END $function$

CREATE OR REPLACE FUNCTION giro_authority.service_day_minutes(p_value text)
 RETURNS integer
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
  v text := giro_authority.hhmm_norm(p_value);
  h integer;
BEGIN
  IF v IS NULL THEN RETURN NULL; END IF;
  h := split_part(v, ':', 1)::integer;
  RETURN h * 60 + split_part(v, ':', 2)::integer + CASE WHEN h < 4 THEN 1440 ELSE 0 END;
END $function$

CREATE OR REPLACE FUNCTION giro_authority.trip_facts_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
  v_raw    text;
  v_ds     jsonb;
  v_active jsonb;
  v_giros  jsonb;
  v_canon  jsonb;
BEGIN
  -- W6.2 compatibility fallback (D-1): canonical trip_authority data wins whenever a
  -- canonical trip exists; this is temporary, not a second authority. Empty on
  -- staging today (nothing writes to trip_authority.trips yet), so this branch is
  -- provably a no-op for every current read -- proven by the harness's equivalence
  -- group, not merely asserted here.
  v_canon := trip_authority.trip_facts_canonical_v1();
  IF (v_canon->>'canonical_trip_exists')::boolean IS TRUE THEN
    RETURN v_canon - 'canonical_trip_exists';
  END IF;

  SELECT c.valore INTO v_raw FROM public.config c WHERE c.chiave = 'DRIVER_STATO';
  IF NOT FOUND OR v_raw IS NULL OR btrim(v_raw) = '' THEN
    RETURN jsonb_build_object('available', true, 'active', false, 'order_ids', '[]'::jsonb, 'giro_ids', '[]'::jsonb);
  END IF;
  BEGIN
    v_ds := v_raw::jsonb;
  EXCEPTION WHEN others THEN
    RETURN jsonb_build_object('available', false, 'reason', 'DRIVER_STATO_UNPARSEABLE');
  END;
  IF jsonb_typeof(v_ds) IS DISTINCT FROM 'object' THEN
    RETURN jsonb_build_object('available', false, 'reason', 'DRIVER_STATO_NOT_OBJECT');
  END IF;
  v_active := NULLIF(v_ds->'active_trip', 'null'::jsonb);
  IF v_active IS NULL THEN
    RETURN jsonb_build_object('available', true, 'active', false, 'order_ids', '[]'::jsonb, 'giro_ids', '[]'::jsonb);
  END IF;
  IF jsonb_typeof(v_active) <> 'object' THEN
    RETURN jsonb_build_object('available', false, 'reason', 'ACTIVE_TRIP_MALFORMED');
  END IF;
  IF (v_active->>'status') IS DISTINCT FROM 'ACTIVE' THEN
    RETURN jsonb_build_object('available', true, 'active', false, 'order_ids', '[]'::jsonb, 'giro_ids', '[]'::jsonb);
  END IF;
  IF jsonb_typeof(v_active->'order_ids') IS DISTINCT FROM 'array' THEN
    RETURN jsonb_build_object('available', false, 'reason', 'ACTIVE_TRIP_MALFORMED');
  END IF;
  v_giros := COALESCE(NULLIF(v_active->'manual_giro_ids', 'null'::jsonb), '[]'::jsonb);
  IF jsonb_typeof(v_giros) <> 'array' THEN
    RETURN jsonb_build_object('available', false, 'reason', 'ACTIVE_TRIP_MALFORMED');
  END IF;
  RETURN jsonb_build_object('available', true, 'active', true, 'trip_id', v_active->>'trip_id',
                            'order_ids', v_active->'order_ids', 'giro_ids', v_giros);
END $function$

CREATE OR REPLACE FUNCTION public._ledger_write_payment(p_order_id text, p_payment_method text, p_reason text, p_by_actor text, p_by_role text, p_ip_hash text, p_meta jsonb, p_idem_scope_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_ord public.ordenes%ROWTYPE;
  v_existing public.order_financial_events%ROWTYPE;
  v_existing_basis public.order_financial_events%ROWTYPE;
  v_new public.order_financial_events%ROWTYPE;
  v_role text := p_by_role; v_method text; v_reason text; v_amount numeric(10,2);
  v_meta jsonb := COALESCE(p_meta, '{}'::jsonb);
  v_canon jsonb; v_digest text; v_replay_digest text;
BEGIN
  IF jsonb_typeof(v_meta) <> 'object' THEN RAISE EXCEPTION 'AUTH_META_INVALID' USING ERRCODE='22023'; END IF;
  IF length(v_meta::text) > 2048 THEN RAISE EXCEPTION 'AUTH_META_TOO_LARGE' USING ERRCODE='22023'; END IF;
  IF EXISTS (SELECT 1 FROM jsonb_object_keys(v_meta) k WHERE lower(k) = ANY (ARRAY[
       'pin','pin_hash','password','token','access_token','refresh_token','jwt','secret',
       'recovery_secret','authorization','api_key','apikey','bearer','cookie','raw_ip','confirmation']))
  THEN RAISE EXCEPTION 'AUTH_META_SENSITIVE_KEY' USING ERRCODE='22023'; END IF;
  IF p_ip_hash IS NULL OR btrim(p_ip_hash) = '' THEN RAISE EXCEPTION 'AUTH_IP_HASH_REQUIRED' USING ERRCODE='22023'; END IF;
  IF length(p_ip_hash) > 64 THEN RAISE EXCEPTION 'AUTH_IP_HASH_TOO_LONG' USING ERRCODE='22023'; END IF;
  IF p_idem_scope_key IS NULL OR char_length(p_idem_scope_key) < 8 OR char_length(p_idem_scope_key) > 128
     OR p_idem_scope_key !~ '^[A-Za-z0-9_-]+$'
  THEN RAISE EXCEPTION 'AUTH_IDEM_KEY_INVALID' USING ERRCODE='22023'; END IF;

  v_method := lower(btrim(COALESCE(p_payment_method, '')));
  IF v_method NOT IN ('efectivo','tarjeta','bizum') THEN RAISE EXCEPTION 'AUTH_METHOD_INVALID' USING ERRCODE='22023'; END IF;

  IF p_reason IS NOT NULL AND btrim(p_reason) = '' THEN RAISE EXCEPTION 'AUTH_REASON_BLANK' USING ERRCODE='22023'; END IF;
  v_reason := CASE WHEN p_reason IS NULL THEN NULL ELSE btrim(p_reason) END;

  IF p_by_actor IS NULL OR btrim(p_by_actor) = '' THEN RAISE EXCEPTION 'AUTH_ACTOR_NOT_FOUND' USING ERRCODE='P0002'; END IF;
  IF v_role IS NULL OR btrim(v_role) = '' THEN RAISE EXCEPTION 'AUTH_FORBIDDEN_ROLE' USING ERRCODE='22023'; END IF;

  SELECT * INTO v_ord FROM public.ordenes WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'AUTH_ORDER_NOT_FOUND' USING ERRCODE='P0002'; END IF;

  -- E-2 (Economic Writer Hardening V1, migration 126). This legacy family is the only
  -- payment authority that incasses ordenes.totale instead of the canonical obligation
  -- (F-1/F-2 of the audit). Refuse BEFORE the idempotency replay lookup or anything else:
  --   (a) Mesa orders have their own canonical, per-line writer (mesa_post_payment_v1) and
  --       must never be reachable by an unfenced legacy path (N-5 blocker L-1);
  --   (b) any order whose canonical obligation has diverged from totale (a commercial
  --       adjustment or a cancellation happened) would be over- or under-charged by a
  --       totale-based collection.
  -- The normal, still-required rider path (non-Mesa, obligation == totale, no adjustment)
  -- is completely unaffected: both conditions below are false for it.
  IF v_ord.table_session_id IS NOT NULL THEN
    RAISE EXCEPTION 'LEGACY_COLLECTION_NOT_ALLOWED' USING ERRCODE='22023',
      DETAIL = format('order_id=%s is Mesa-owned (table_session_id=%s) -- legacy OFE-only collection is not permitted on table orders', p_order_id, v_ord.table_session_id);
  END IF;
  IF round(public.order_canonical_obligation_v1(v_ord.order_uid), 2) IS DISTINCT FROM round(v_ord.totale, 2) THEN
    RAISE EXCEPTION 'LEGACY_COLLECTION_NOT_ALLOWED' USING ERRCODE='22023',
      DETAIL = format('order_id=%s canonical_obligation=%s totale=%s -- legacy collection refused: the canonical obligation has diverged from the order total',
                       p_order_id, round(public.order_canonical_obligation_v1(v_ord.order_uid), 2), round(v_ord.totale, 2));
  END IF;

  -- Same-scope replay is based on immutable event snapshots, not mutable order fields.
  -- Scoped by service_session_id (IS NOT DISTINCT FROM handles the legacy NULL-session
  -- case) to match the partitioned unique indexes from 2026-07-26_two_service_identity.sql
  -- (order_financial_events_one_payment_session_uq / _legacy_uq): an order id/number
  -- recycled into a LATER service session must never match an EARLIER session's event.
  SELECT * INTO v_existing FROM public.order_financial_events
    WHERE order_id = p_order_id AND type = 'payment' AND idem_scope_key = p_idem_scope_key
      AND service_session_id IS NOT DISTINCT FROM v_ord.service_session_id;
  IF FOUND THEN
    IF v_existing.type <> 'payment'
       OR v_existing.amount IS NULL OR v_existing.amount <= 0
       OR v_existing.payment_method NOT IN ('efectivo','tarjeta','bizum')
       OR v_existing.legacy IS DISTINCT FROM false
       OR v_existing.prev_pay_state <> 'unpaid' OR v_existing.new_pay_state <> 'paid'
       OR v_existing.prev_estado IS DISTINCT FROM v_existing.new_estado
       OR v_existing.original_giro_id IS NOT NULL
    THEN RAISE EXCEPTION 'AUTH_IDEMPOTENCY_CONFLICT' USING ERRCODE='22023'; END IF;

    v_replay_digest := lower(encode(sha256(convert_to((jsonb_build_object(
      'order_id', p_order_id, 'type', 'payment', 'idem_scope_key', p_idem_scope_key,
      'by_actor', p_by_actor, 'by_role', v_role, 'reason', v_reason,
      'prev_estado', v_existing.prev_estado, 'new_estado', v_existing.new_estado,
      'prev_pay_state', v_existing.prev_pay_state, 'new_pay_state', v_existing.new_pay_state,
      'amount', v_existing.amount, 'payment_method', v_method, 'legacy', false))::text, 'UTF8')), 'hex'));
    IF v_existing.payload_digest = v_replay_digest THEN
      RETURN jsonb_build_object('event_id', v_existing.id, 'order_id', v_existing.order_id,
        'type', v_existing.type, 'amount', v_existing.amount, 'payment_method', v_existing.payment_method,
        'prev_estado', v_existing.prev_estado, 'new_estado', v_existing.new_estado,
        'prev_pay_state', v_existing.prev_pay_state, 'new_pay_state', v_existing.new_pay_state,
        'legacy', v_existing.legacy, 'idempotent', true, 'created_at', v_existing.created_at);
    END IF;
    -- A different actor/role/amount under the same key is a genuine conflict, never a
    -- silent second charge. This is what refuses a rider collection followed by an
    -- operator one on the same order.
    RAISE EXCEPTION 'AUTH_IDEMPOTENCY_CONFLICT' USING ERRCODE='22023';
  END IF;

  -- SERVER-DERIVED amount. No caller — Node, rider or operator — can supply or override it.
  v_amount := round(v_ord.totale, 2);
  IF v_amount IS NULL OR v_amount <= 0 THEN RAISE EXCEPTION 'AUTH_AMOUNT_INVALID' USING ERRCODE='22023'; END IF;

  -- Key order and value types are byte-significant: the digest is sha256 over the jsonb
  -- text. Reproduced EXACTLY as in 2026-07-19_b7_payment_basis_historical_replay_fix.sql.
  v_canon := jsonb_build_object(
    'order_id', p_order_id, 'type', 'payment', 'idem_scope_key', p_idem_scope_key,
    'by_actor', p_by_actor, 'by_role', v_role, 'reason', v_reason,
    'prev_estado', v_ord.estado, 'new_estado', v_ord.estado,
    'prev_pay_state', 'unpaid', 'new_pay_state', 'paid',
    'amount', v_amount, 'payment_method', v_method, 'legacy', false);
  v_digest := lower(encode(sha256(convert_to(v_canon::text, 'UTF8')), 'hex'));

  -- Same session-scoping as the replay check above: one basis per order PER SESSION, so a
  -- recycled order id/number starts a fresh basis in a later session instead of colliding
  -- with a since-archived one.
  SELECT * INTO v_existing_basis FROM public.order_financial_events
    WHERE order_id = p_order_id AND type IN ('payment','payment_imported')
      AND service_session_id IS NOT DISTINCT FROM v_ord.service_session_id
    ORDER BY created_at ASC LIMIT 1;
  IF FOUND THEN
    RAISE EXCEPTION 'AUTH_BASIS_EXISTS' USING ERRCODE='22023';
  END IF;

  IF v_ord.ya_pagado IS TRUE OR v_ord.cobrado IS TRUE THEN
    RAISE EXCEPTION 'AUTH_LEGACY_IMPORT_REQUIRED' USING ERRCODE='22023';
  END IF;

  INSERT INTO public.order_financial_events(
    order_id, type, amount, payment_method, reason, legacy, by_actor, by_role,
    prev_estado, new_estado, prev_pay_state, new_pay_state, original_giro_id,
    ip_hash, meta, idem_scope_key, payload_digest)
  VALUES (p_order_id, 'payment', v_amount, v_method, v_reason, false, p_by_actor, v_role,
    v_ord.estado, v_ord.estado, 'unpaid', 'paid', NULL,
    p_ip_hash, v_meta, p_idem_scope_key, v_digest)
  RETURNING * INTO v_new;

  UPDATE public.ordenes SET ya_pagado = true, cobrado = true, metodo_pago = v_method
   WHERE id = p_order_id;

  RETURN jsonb_build_object('event_id', v_new.id, 'order_id', v_new.order_id,
    'type', v_new.type, 'amount', v_new.amount, 'payment_method', v_new.payment_method,
    'prev_estado', v_new.prev_estado, 'new_estado', v_new.new_estado,
    'prev_pay_state', v_new.prev_pay_state, 'new_pay_state', v_new.new_pay_state,
    'legacy', v_new.legacy, 'idempotent', false, 'created_at', v_new.created_at);
END;
$function$

CREATE OR REPLACE FUNCTION public.acquire_closeout_attempt(p_service_session_id uuid, p_actor text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_row public.service_closeout_attempts%ROWTYPE;
BEGIN
  IF p_service_session_id IS NULL THEN
    RETURN jsonb_build_object('ok',false,'code','INVALID_ARGUMENTS');
  END IF;
  IF p_actor IS NULL OR btrim(p_actor) = '' THEN
    RETURN jsonb_build_object('ok',false,'code','INVALID_ACTOR');
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.service_sessions WHERE id = p_service_session_id) THEN
    RETURN jsonb_build_object('ok',false,'code','SERVICE_SESSION_NOT_FOUND');
  END IF;

  INSERT INTO public.service_closeout_attempts(service_session_id, status, created_by)
  VALUES (p_service_session_id, 'active', p_actor)
  ON CONFLICT (service_session_id) WHERE status = 'active' DO NOTHING
  RETURNING * INTO v_row;

  IF FOUND THEN
    RETURN jsonb_build_object('ok',true,'code','ACQUIRED','created',true,'attempt',to_jsonb(v_row));
  END IF;

  SELECT * INTO v_row FROM public.service_closeout_attempts
   WHERE service_session_id = p_service_session_id AND status = 'active';
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok',false,'code','ACQUIRE_RACE_UNRESOLVED');
  END IF;
  RETURN jsonb_build_object('ok',true,'code','ALREADY_ACTIVE','created',false,'attempt',to_jsonb(v_row));
END;
$function$

CREATE OR REPLACE FUNCTION public.auth_account_claim_workspace(p_user_id uuid, p_slug text, p_display_name text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_ws public.workspaces%ROWTYPE;
        v_mem public.workspace_memberships%ROWTYPE;
        v_existing_owner uuid;
        v_created boolean := false;
        v_completed boolean := false;
BEGIN
  IF p_user_id IS NULL THEN RAISE EXCEPTION 'ACCOUNT_USER_REQUIRED' USING ERRCODE='22023'; END IF;
  IF p_slug IS NULL OR btrim(p_slug) = '' THEN RAISE EXCEPTION 'WORKSPACE_SLUG_REQUIRED' USING ERRCODE='22023'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.user_profiles WHERE id = p_user_id) THEN
    RAISE EXCEPTION 'ACCOUNT_PROFILE_MISSING' USING ERRCODE='P0002';
  END IF;

  -- Serialize concurrent claims on the same slug.
  PERFORM pg_advisory_xact_lock(hashtextextended('s2_7d_claim:' || lower(p_slug), 0));

  SELECT * INTO v_ws FROM public.workspaces WHERE slug = lower(p_slug);

  IF NOT FOUND THEN
    -- provisioning → owner membership → activate (deferred activation trigger allows this
    -- ordering in one transaction).
    INSERT INTO public.workspaces (slug, display_name, lifecycle_status, commercial_status)
    VALUES (lower(p_slug), COALESCE(NULLIF(btrim(p_display_name),''), p_slug), 'provisioning', 'trial')
    RETURNING * INTO v_ws;
    v_created := true;

    INSERT INTO public.workspace_memberships (workspace_id, user_id, role, status)
    VALUES (v_ws.id, p_user_id, 'workspace_owner', 'active')
    RETURNING * INTO v_mem;

    UPDATE public.workspaces SET lifecycle_status = 'active', updated_at = now()
     WHERE id = v_ws.id RETURNING * INTO v_ws;

    INSERT INTO public.workspace_account_audit (workspace_id, event, actor_user_id, target_user_id, meta)
    VALUES (v_ws.id, 'workspace_created', p_user_id, p_user_id, jsonb_build_object('source','account_bootstrap'));
    INSERT INTO public.workspace_account_audit (workspace_id, event, actor_user_id, target_user_id, meta)
    VALUES (v_ws.id, 'owner_claimed', p_user_id, p_user_id, jsonb_build_object('source','account_bootstrap'));
  ELSE
    -- single-owner enforcement: a DIFFERENT active owner → refuse; same account → no-op.
    SELECT user_id INTO v_existing_owner
      FROM public.workspace_memberships
     WHERE workspace_id = v_ws.id AND role = 'workspace_owner' AND status = 'active'
     LIMIT 1;

    IF v_existing_owner IS NOT NULL AND v_existing_owner <> p_user_id THEN
      RAISE EXCEPTION 'WORKSPACE_ALREADY_OWNED' USING ERRCODE='P0001';
    END IF;

    IF v_existing_owner IS NULL THEN
      INSERT INTO public.workspace_memberships (workspace_id, user_id, role, status)
      VALUES (v_ws.id, p_user_id, 'workspace_owner', 'active')
      ON CONFLICT (workspace_id, user_id)
        DO UPDATE SET role = 'workspace_owner', status = 'active', updated_at = now()
      RETURNING * INTO v_mem;

      IF v_ws.lifecycle_status = 'provisioning' THEN
        UPDATE public.workspaces SET lifecycle_status = 'active', updated_at = now()
         WHERE id = v_ws.id RETURNING * INTO v_ws;
      END IF;

      INSERT INTO public.workspace_account_audit (workspace_id, event, actor_user_id, target_user_id, meta)
      VALUES (v_ws.id, 'owner_claimed', p_user_id, p_user_id, jsonb_build_object('source','account_bootstrap'));
    ELSE
      SELECT * INTO v_mem FROM public.workspace_memberships
       WHERE workspace_id = v_ws.id AND user_id = p_user_id;
    END IF;
  END IF;

  -- Associate EXACTLY the existing actors with this workspace. Fail closed if any actor is
  -- already bound to a different workspace (no cross-workspace reassignment here). Only
  -- unassigned actors are touched → PIN hashes / roles / active / lock / session_version
  -- are all preserved (workspace_id is the sole column written).
  IF EXISTS (SELECT 1 FROM public.auth_actors
              WHERE workspace_id IS NOT NULL AND workspace_id <> v_ws.id) THEN
    RAISE EXCEPTION 'ACTOR_WORKSPACE_CONFLICT' USING ERRCODE='P0001';
  END IF;
  UPDATE public.auth_actors SET workspace_id = v_ws.id WHERE workspace_id IS NULL;

  SELECT (owner_pin_onboarding_completed_at IS NOT NULL) INTO v_completed
    FROM public.workspaces WHERE id = v_ws.id;

  RETURN jsonb_build_object(
    'workspace_id', v_ws.id,
    'membership_id', v_mem.id,
    'created', v_created,
    'owner_pin_onboarding_completed', COALESCE(v_completed, false)
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.auth_admin_revoke_actor_sessions(p_by_actor text, p_target_actor text, p_expected_role text, p_ip_hash text, p_meta jsonb DEFAULT '{}'::jsonb, p_confirm text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_by public.auth_actors%ROWTYPE; v_tgt public.auth_actors%ROWTYPE;
        r public.auth_actors%ROWTYPE; v_now timestamptz := now();
        v_meta jsonb := COALESCE(p_meta, '{}'::jsonb);
BEGIN
  IF jsonb_typeof(v_meta) <> 'object' THEN RAISE EXCEPTION 'AUTH_META_INVALID' USING ERRCODE='22023'; END IF;
  IF length(v_meta::text) > 2048 THEN RAISE EXCEPTION 'AUTH_META_TOO_LARGE' USING ERRCODE='22023'; END IF;
  IF EXISTS (SELECT 1 FROM jsonb_object_keys(v_meta) k WHERE lower(k) = ANY (ARRAY[
       'pin','pin_hash','password','token','access_token','refresh_token','jwt','secret',
       'recovery_secret','authorization','api_key','apikey','bearer','cookie','raw_ip','confirmation']))
  THEN RAISE EXCEPTION 'AUTH_META_SENSITIVE_KEY' USING ERRCODE='22023'; END IF;
  IF p_ip_hash IS NULL OR btrim(p_ip_hash) = '' THEN RAISE EXCEPTION 'AUTH_IP_HASH_REQUIRED' USING ERRCODE='22023'; END IF;
  IF length(p_ip_hash) > 64 THEN RAISE EXCEPTION 'AUTH_IP_HASH_TOO_LONG' USING ERRCODE='22023'; END IF;
  IF p_expected_role NOT IN ('admin','operator','rider') THEN RAISE EXCEPTION 'AUTH_ROLE_INVALID' USING ERRCODE='22023'; END IF;

  PERFORM 1 FROM public.auth_actors WHERE actor IN (p_by_actor, p_target_actor) ORDER BY actor FOR UPDATE;
  SELECT * INTO v_by  FROM public.auth_actors WHERE actor = p_by_actor;
  IF NOT FOUND THEN RAISE EXCEPTION 'AUTH_INITIATOR_NOT_FOUND' USING ERRCODE='P0002'; END IF;
  IF v_by.role <> 'admin' THEN RAISE EXCEPTION 'AUTH_NOT_ADMIN' USING ERRCODE='22023'; END IF;
  IF v_by.active <> true THEN RAISE EXCEPTION 'AUTH_INITIATOR_INACTIVE' USING ERRCODE='22023'; END IF;
  SELECT * INTO v_tgt FROM public.auth_actors WHERE actor = p_target_actor;
  IF NOT FOUND THEN RAISE EXCEPTION 'AUTH_ACTOR_NOT_FOUND' USING ERRCODE='P0002'; END IF;
  IF v_tgt.role <> p_expected_role THEN RAISE EXCEPTION 'AUTH_TARGET_ROLE_MISMATCH' USING ERRCODE='22023'; END IF;

  -- owner self-revoke requires the exact confirmation phrase (no normalization).
  IF p_by_actor = 'owner' AND p_target_actor = 'owner'
     AND p_confirm IS DISTINCT FROM 'REVOKE_OWNER_SESSIONS'
  THEN RAISE EXCEPTION 'AUTH_CONFIRMATION_REQUIRED' USING ERRCODE='22023'; END IF;

  UPDATE public.auth_actors
     SET session_version = session_version + 1, updated_at = v_now, updated_by = p_by_actor
   WHERE actor = p_target_actor RETURNING * INTO r;   -- pin/active/failed/lock preserved

  INSERT INTO public.auth_audit(event, target_actor, by_actor, ip_hash, meta)
  VALUES ('revoke', p_target_actor, p_by_actor, p_ip_hash, v_meta);

  RETURN jsonb_build_object('actor', r.actor, 'role', r.role, 'active', r.active,
    'session_version', r.session_version, 'failed_count', r.failed_count,
    'locked_until', r.locked_until, 'updated_at', r.updated_at, 'updated_by', r.updated_by,
    'changed', true, 'event', 'revoke');
END;
$function$

CREATE OR REPLACE FUNCTION public.auth_admin_unlock_actor(p_by_actor text, p_target_actor text, p_expected_role text, p_ip_hash text, p_meta jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_by public.auth_actors%ROWTYPE; v_tgt public.auth_actors%ROWTYPE;
        r public.auth_actors%ROWTYPE; v_now timestamptz := now();
        v_meta jsonb := COALESCE(p_meta, '{}'::jsonb);
BEGIN
  IF jsonb_typeof(v_meta) <> 'object' THEN RAISE EXCEPTION 'AUTH_META_INVALID' USING ERRCODE='22023'; END IF;
  IF length(v_meta::text) > 2048 THEN RAISE EXCEPTION 'AUTH_META_TOO_LARGE' USING ERRCODE='22023'; END IF;
  IF EXISTS (SELECT 1 FROM jsonb_object_keys(v_meta) k WHERE lower(k) = ANY (ARRAY[
       'pin','pin_hash','password','token','access_token','refresh_token','jwt','secret',
       'recovery_secret','authorization','api_key','apikey','bearer','cookie','raw_ip','confirmation']))
  THEN RAISE EXCEPTION 'AUTH_META_SENSITIVE_KEY' USING ERRCODE='22023'; END IF;
  IF p_ip_hash IS NULL OR btrim(p_ip_hash) = '' THEN RAISE EXCEPTION 'AUTH_IP_HASH_REQUIRED' USING ERRCODE='22023'; END IF;
  IF length(p_ip_hash) > 64 THEN RAISE EXCEPTION 'AUTH_IP_HASH_TOO_LONG' USING ERRCODE='22023'; END IF;
  IF p_expected_role NOT IN ('admin','operator','rider') THEN RAISE EXCEPTION 'AUTH_ROLE_INVALID' USING ERRCODE='22023'; END IF;

  PERFORM 1 FROM public.auth_actors WHERE actor IN (p_by_actor, p_target_actor) ORDER BY actor FOR UPDATE;
  SELECT * INTO v_by  FROM public.auth_actors WHERE actor = p_by_actor;
  IF NOT FOUND THEN RAISE EXCEPTION 'AUTH_INITIATOR_NOT_FOUND' USING ERRCODE='P0002'; END IF;
  IF v_by.role <> 'admin' THEN RAISE EXCEPTION 'AUTH_NOT_ADMIN' USING ERRCODE='22023'; END IF;
  IF v_by.active <> true THEN RAISE EXCEPTION 'AUTH_INITIATOR_INACTIVE' USING ERRCODE='22023'; END IF;
  SELECT * INTO v_tgt FROM public.auth_actors WHERE actor = p_target_actor;
  IF NOT FOUND THEN RAISE EXCEPTION 'AUTH_ACTOR_NOT_FOUND' USING ERRCODE='P0002'; END IF;
  IF v_tgt.role <> p_expected_role THEN RAISE EXCEPTION 'AUTH_TARGET_ROLE_MISMATCH' USING ERRCODE='22023'; END IF;

  -- already unlocked → no-op (no audit, no sv change, no timestamp churn)
  IF v_tgt.failed_count = 0 AND v_tgt.locked_until IS NULL THEN
    RETURN jsonb_build_object('actor', v_tgt.actor, 'role', v_tgt.role, 'active', v_tgt.active,
      'session_version', v_tgt.session_version, 'failed_count', v_tgt.failed_count,
      'locked_until', v_tgt.locked_until, 'updated_at', v_tgt.updated_at, 'updated_by', v_tgt.updated_by,
      'changed', false, 'event', NULL);
  END IF;

  UPDATE public.auth_actors
     SET failed_count = 0, locked_until = NULL, updated_at = v_now, updated_by = p_by_actor
   WHERE actor = p_target_actor RETURNING * INTO r;   -- pin/active/session_version preserved

  INSERT INTO public.auth_audit(event, target_actor, by_actor, ip_hash, meta)
  VALUES ('actor_unlocked', p_target_actor, p_by_actor, p_ip_hash, v_meta);

  RETURN jsonb_build_object('actor', r.actor, 'role', r.role, 'active', r.active,
    'session_version', r.session_version, 'failed_count', r.failed_count,
    'locked_until', r.locked_until, 'updated_at', r.updated_at, 'updated_by', r.updated_by,
    'changed', true, 'event', 'actor_unlocked');
END;
$function$

CREATE OR REPLACE FUNCTION public.auth_assign_table_session_waiter_v3(p_workspace_id uuid, p_by_actor text, p_table_session_id uuid, p_expected_assigned_waiter_actor text, p_requested_waiter_actor text, p_by_sid_hash text, p_client_request_id text, p_request_hash text, p_meta jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_ws public.workspaces%ROWTYPE;
  v_by public.auth_actors%ROWTYPE;
  v_prev public.auth_actors%ROWTYPE;
  v_req public.auth_actors%ROWTYPE;
  v_sess public.table_sessions%ROWTYPE;
  v_idem public.access_management_idempotency%ROWTYPE;
  v_meta jsonb := COALESCE(p_meta, '{}'::jsonb);
  v_now timestamptz := now();
  v_actor_set text[];
  v_action text;
  v_changed boolean;
  r public.table_sessions%ROWTYPE;
  v_result jsonb;
BEGIN
  -- ── input guards ──────────────────────────────────────────────────────────
  IF p_workspace_id IS NULL THEN RAISE EXCEPTION 'AUTH_WORKSPACE_REQUIRED' USING ERRCODE='22023'; END IF;
  IF p_by_actor IS NULL OR btrim(p_by_actor) = '' THEN RAISE EXCEPTION 'AUTH_INITIATOR_REQUIRED' USING ERRCODE='22023'; END IF;
  IF p_table_session_id IS NULL THEN RAISE EXCEPTION 'AUTH_TABLE_SESSION_REQUIRED' USING ERRCODE='22023'; END IF;
  IF p_requested_waiter_actor IS NOT NULL AND btrim(p_requested_waiter_actor) = ''
  THEN RAISE EXCEPTION 'AUTH_ACTOR_INVALID' USING ERRCODE='22023'; END IF;
  IF p_by_sid_hash IS NULL OR btrim(p_by_sid_hash) = '' OR length(p_by_sid_hash) > 64
  THEN RAISE EXCEPTION 'AUTH_SID_HASH_INVALID' USING ERRCODE='22023'; END IF;
  IF p_client_request_id IS NULL OR btrim(p_client_request_id) = '' OR length(p_client_request_id) > 128
  THEN RAISE EXCEPTION 'AUTH_CLIENT_REQUEST_ID_INVALID' USING ERRCODE='22023'; END IF;
  IF p_request_hash IS NULL OR p_request_hash !~ '^[0-9a-f]{64}$'
  THEN RAISE EXCEPTION 'AUTH_REQUEST_HASH_INVALID' USING ERRCODE='22023'; END IF;
  IF jsonb_typeof(v_meta) <> 'object' THEN RAISE EXCEPTION 'AUTH_META_INVALID' USING ERRCODE='22023'; END IF;
  IF length(v_meta::text) > 2048 THEN RAISE EXCEPTION 'AUTH_META_TOO_LARGE' USING ERRCODE='22023'; END IF;
  IF EXISTS (SELECT 1 FROM jsonb_object_keys(v_meta) k WHERE lower(k) = ANY (ARRAY[
       'pin','pin_hash','password','token','access_token','refresh_token','jwt','secret',
       'recovery_secret','authorization','api_key','apikey','bearer','cookie','raw_ip',
       'confirmation','fingerprint','pin_fingerprint','fingerprint_key','hmac_key',
       'proof','step_up_proof','sid','display_name']))
  THEN RAISE EXCEPTION 'AUTH_META_SENSITIVE_KEY' USING ERRCODE='22023'; END IF;

  v_action := 'assign_table_session_waiter_v3';

  -- ── workspace row lock — the serialisation point ──────────────────────────
  SELECT * INTO v_ws FROM public.workspaces WHERE id = p_workspace_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'WORKSPACE_NOT_FOUND' USING ERRCODE='P0002'; END IF;
  IF v_ws.lifecycle_status <> 'active' THEN RAISE EXCEPTION 'WORKSPACE_NOT_ACTIVE' USING ERRCODE='22023'; END IF;

  -- ── deterministic actor-id locking — EVERY involved actor, ONE statement ──────
  -- Involved = acting owner, the session's CURRENT assigned waiter (if any -- losing an
  -- assignment is still a state change for that actor), and the REQUESTED waiter (if
  -- any -- clearing an assignment passes NULL here). Deduplicated, sorted, locked in one
  -- deterministic ORDER BY actor statement -- never a loop, never touched before the
  -- table session below.
  SELECT * INTO v_sess FROM public.table_sessions WHERE id = p_table_session_id; -- pre-lock peek only, to learn the CURRENT assignee for the actor set; re-read under lock below
  v_actor_set := ARRAY(
    SELECT DISTINCT a FROM unnest(ARRAY[p_by_actor, v_sess.assigned_waiter_actor, p_requested_waiter_actor]) a
    WHERE a IS NOT NULL
  );
  PERFORM 1 FROM public.auth_actors WHERE actor = ANY (v_actor_set) ORDER BY actor FOR UPDATE;

  SELECT * INTO v_by FROM public.auth_actors WHERE actor = p_by_actor;
  IF NOT FOUND THEN RAISE EXCEPTION 'AUTH_INITIATOR_NOT_FOUND' USING ERRCODE='P0002'; END IF;

  -- ── acting actor — owner semantics decided by ROLE, never the actor id ────
  IF v_by.workspace_id IS DISTINCT FROM p_workspace_id THEN
    RAISE EXCEPTION 'AUTH_INITIATOR_OTHER_WORKSPACE' USING ERRCODE='P0001'; END IF;
  IF v_by.active <> true THEN RAISE EXCEPTION 'AUTH_INITIATOR_INACTIVE' USING ERRCODE='22023'; END IF;
  IF v_by.role NOT IN ('admin', 'owner') THEN RAISE EXCEPTION 'AUTH_NOT_OWNER' USING ERRCODE='P0001'; END IF;

  -- ── requested waiter (NULL = explicit clear; skip eligibility check) ──────
  IF p_requested_waiter_actor IS NOT NULL THEN
    SELECT * INTO v_req FROM public.auth_actors WHERE actor = p_requested_waiter_actor;
    IF NOT FOUND THEN RAISE EXCEPTION 'AUTH_ACTOR_NOT_FOUND' USING ERRCODE='P0002'; END IF;
    IF v_req.workspace_id IS DISTINCT FROM p_workspace_id THEN
      RAISE EXCEPTION 'AUTH_TARGET_OTHER_WORKSPACE' USING ERRCODE='P0001'; END IF;
    IF v_req.active <> true THEN RAISE EXCEPTION 'AUTH_TARGET_INACTIVE' USING ERRCODE='22023'; END IF;
    -- Exact single-role eligibility (not a broader allowlist -- this RPC assigns ONLY
    -- waiters, unlike V3-E's multi-role lifecycle allowlist).
    IF v_req.role IS DISTINCT FROM 'waiter' THEN
      RAISE EXCEPTION 'AUTH_TARGET_ROLE_INELIGIBLE' USING ERRCODE='P0001'; END IF;
  END IF;

  -- ── table session — locked AFTER every actor, re-read fresh under lock ────
  SELECT * INTO v_sess FROM public.table_sessions WHERE id = p_table_session_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'TABLE_SESSION_NOT_FOUND' USING ERRCODE='P0002'; END IF;
  IF v_sess.workspace_id IS DISTINCT FROM p_workspace_id THEN
    RAISE EXCEPTION 'TABLE_SESSION_OTHER_WORKSPACE' USING ERRCODE='P0001'; END IF;
  IF v_sess.status <> 'open' THEN RAISE EXCEPTION 'TABLE_SESSION_NOT_OPEN' USING ERRCODE='22023'; END IF;

  -- ── idempotency lookup — ONLY now, after acting-owner, target-eligibility AND
  --    session validation are all proved against the CURRENT authoritative rows ──
  SELECT * INTO v_idem FROM public.access_management_idempotency
   WHERE workspace_id = p_workspace_id AND by_actor = p_by_actor AND by_sid_hash = p_by_sid_hash
     AND action = v_action AND client_request_id = p_client_request_id;
  IF FOUND THEN
    IF v_idem.request_hash = p_request_hash THEN
      RETURN v_idem.response_body; -- safe replay: no mutation, no new history row
    ELSE
      RAISE EXCEPTION 'AUTH_IDEMPOTENCY_CONFLICT' USING ERRCODE='23505';
    END IF;
  END IF;

  -- ── stale-snapshot check against the locked, authoritative session row ────
  IF v_sess.assigned_waiter_actor IS DISTINCT FROM p_expected_assigned_waiter_actor THEN
    RAISE EXCEPTION 'TABLE_SESSION_ASSIGNMENT_STALE' USING ERRCODE='40001'; END IF;

  v_changed := (v_sess.assigned_waiter_actor IS DISTINCT FROM p_requested_waiter_actor);

  IF NOT v_changed THEN
    -- identical current/requested assignment — deterministic no-op, no history row.
    v_result := jsonb_build_object(
      'table_session_id', v_sess.id, 'assigned_waiter_actor', v_sess.assigned_waiter_actor,
      'status', v_sess.status, 'updated_at', v_sess.updated_at, 'updated_by', v_sess.updated_by
    );
  ELSE
    -- real assignment change — ONLY assigned_waiter_actor + attribution/timestamps on
    -- the session row. table_ref, status, opened_at, closed_at, workspace_id,
    -- created_at, created_by: untouched.
    v_action := CASE
      WHEN v_sess.assigned_waiter_actor IS NULL THEN 'assigned'
      WHEN p_requested_waiter_actor IS NULL THEN 'cleared'
      ELSE 'reassigned'
    END;

    UPDATE public.table_sessions
       SET assigned_waiter_actor = p_requested_waiter_actor, updated_at = v_now, updated_by = p_by_actor
     WHERE id = p_table_session_id
     RETURNING * INTO r;

    INSERT INTO public.table_session_assignment_history
      (workspace_id, table_session_id, previous_waiter_actor, new_waiter_actor, by_actor, action, client_request_id)
    VALUES (p_workspace_id, p_table_session_id, v_sess.assigned_waiter_actor, p_requested_waiter_actor,
            p_by_actor, v_action, p_client_request_id);

    v_result := jsonb_build_object(
      'table_session_id', r.id, 'assigned_waiter_actor', r.assigned_waiter_actor,
      'status', r.status, 'updated_at', r.updated_at, 'updated_by', r.updated_by
    );
  END IF;

  INSERT INTO public.access_management_idempotency
    (workspace_id, by_actor, by_sid_hash, action, client_request_id, request_hash, response_status, response_body)
  VALUES (p_workspace_id, p_by_actor, p_by_sid_hash, 'assign_table_session_waiter_v3', p_client_request_id, p_request_hash, 200, v_result);

  RETURN v_result;
END;
$function$

CREATE OR REPLACE FUNCTION public.auth_bump_session_version(p_actor text, p_by text, p_meta jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_sv int; v_meta jsonb := COALESCE(p_meta, '{}'::jsonb);
BEGIN
  IF jsonb_typeof(v_meta) <> 'object' THEN RAISE EXCEPTION 'AUTH_META_INVALID' USING ERRCODE='22023'; END IF;
  IF length(v_meta::text) > 2048 THEN RAISE EXCEPTION 'AUTH_META_TOO_LARGE' USING ERRCODE='22023'; END IF;
  IF EXISTS (SELECT 1 FROM jsonb_object_keys(v_meta) k WHERE lower(k) = ANY (ARRAY['pin','password','token','access_token','refresh_token','jwt','secret','recovery_secret','authorization','api_key','apikey','bearer','cookie']))
  THEN RAISE EXCEPTION 'AUTH_META_SENSITIVE_KEY' USING ERRCODE='22023'; END IF;
  UPDATE public.auth_actors SET session_version = session_version + 1 WHERE actor = p_actor RETURNING session_version INTO v_sv;
  IF NOT FOUND THEN RAISE EXCEPTION 'AUTH_ACTOR_NOT_FOUND' USING ERRCODE='P0002'; END IF;
  INSERT INTO public.auth_audit(event, target_actor, by_actor, meta) VALUES ('revoke', p_actor, p_by, v_meta);
  RETURN jsonb_build_object('actor', p_actor, 'session_version', v_sv, 'event', 'revoke');
END; $function$

CREATE OR REPLACE FUNCTION public.auth_change_actor_role_v3(p_workspace_id uuid, p_by_actor text, p_target_actor text, p_expected_role text, p_requested_role text, p_by_sid_hash text, p_client_request_id text, p_request_hash text, p_meta jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_ws public.workspaces%ROWTYPE;
  v_by public.auth_actors%ROWTYPE;
  v_tgt public.auth_actors%ROWTYPE;
  r public.auth_actors%ROWTYPE;
  v_idem public.access_management_idempotency%ROWTYPE;
  v_idem_found boolean;
  v_meta jsonb := COALESCE(p_meta, '{}'::jsonb);
  v_now timestamptz := now();
  v_old_role text;
  v_changed boolean;
  v_open_tables int;
  v_result jsonb;
BEGIN
  -- ── input guards (byte-identical to V3-C) ─────────────────────────────────
  IF p_workspace_id IS NULL THEN RAISE EXCEPTION 'AUTH_WORKSPACE_REQUIRED' USING ERRCODE='22023'; END IF;
  IF p_by_actor IS NULL OR btrim(p_by_actor) = '' THEN RAISE EXCEPTION 'AUTH_INITIATOR_REQUIRED' USING ERRCODE='22023'; END IF;
  IF p_target_actor IS NULL OR btrim(p_target_actor) = '' THEN RAISE EXCEPTION 'AUTH_ACTOR_INVALID' USING ERRCODE='22023'; END IF;
  IF p_expected_role IS NULL OR btrim(p_expected_role) = '' THEN RAISE EXCEPTION 'AUTH_ROLE_INVALID' USING ERRCODE='22023'; END IF;
  IF p_requested_role IS NULL OR p_requested_role NOT IN ('cashier', 'waiter', 'kitchen', 'rider', 'shift_manager')
  THEN RAISE EXCEPTION 'AUTH_REQUESTED_ROLE_INVALID' USING ERRCODE='22023'; END IF;
  IF p_by_sid_hash IS NULL OR btrim(p_by_sid_hash) = '' OR length(p_by_sid_hash) > 64
  THEN RAISE EXCEPTION 'AUTH_SID_HASH_INVALID' USING ERRCODE='22023'; END IF;
  IF p_client_request_id IS NULL OR btrim(p_client_request_id) = '' OR length(p_client_request_id) > 128
  THEN RAISE EXCEPTION 'AUTH_CLIENT_REQUEST_ID_INVALID' USING ERRCODE='22023'; END IF;
  IF p_request_hash IS NULL OR p_request_hash !~ '^[0-9a-f]{64}$'
  THEN RAISE EXCEPTION 'AUTH_REQUEST_HASH_INVALID' USING ERRCODE='22023'; END IF;
  IF jsonb_typeof(v_meta) <> 'object' THEN RAISE EXCEPTION 'AUTH_META_INVALID' USING ERRCODE='22023'; END IF;
  IF length(v_meta::text) > 2048 THEN RAISE EXCEPTION 'AUTH_META_TOO_LARGE' USING ERRCODE='22023'; END IF;
  IF EXISTS (SELECT 1 FROM jsonb_object_keys(v_meta) k WHERE lower(k) = ANY (ARRAY[
       'pin','pin_hash','password','token','access_token','refresh_token','jwt','secret',
       'recovery_secret','authorization','api_key','apikey','bearer','cookie','raw_ip',
       'confirmation','fingerprint','pin_fingerprint','fingerprint_key','hmac_key',
       'proof','step_up_proof','sid']))
  THEN RAISE EXCEPTION 'AUTH_META_SENSITIVE_KEY' USING ERRCODE='22023'; END IF;

  -- ── 1) workspace row lock — the serialisation point (unchanged discipline) ──
  SELECT * INTO v_ws FROM public.workspaces WHERE id = p_workspace_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'WORKSPACE_NOT_FOUND' USING ERRCODE='P0002'; END IF;
  IF v_ws.lifecycle_status <> 'active' THEN RAISE EXCEPTION 'WORKSPACE_NOT_ACTIVE' USING ERRCODE='22023'; END IF;

  -- ── 2) deterministic actor-id locking — acting + target, ordered ─────────────
  -- V3-G.1 REORDER: moved BEFORE idempotency lookup (was after, in the committed V3-C
  -- body) -- authorization must be proved BEFORE any idempotency lookup/replay, exactly
  -- like V3-E's own corrected pattern: a revoked, deactivated, or demoted acting actor
  -- must never receive a stored success response merely because a matching idempotency
  -- record exists from when they WERE authorized.
  PERFORM 1 FROM public.auth_actors WHERE actor IN (p_by_actor, p_target_actor) ORDER BY actor FOR UPDATE;

  -- ── 3) re-read both actors under lock ─────────────────────────────────────
  SELECT * INTO v_by FROM public.auth_actors WHERE actor = p_by_actor;
  IF NOT FOUND THEN RAISE EXCEPTION 'AUTH_INITIATOR_NOT_FOUND' USING ERRCODE='P0002'; END IF;
  SELECT * INTO v_tgt FROM public.auth_actors WHERE actor = p_target_actor;
  IF NOT FOUND THEN RAISE EXCEPTION 'AUTH_ACTOR_NOT_FOUND' USING ERRCODE='P0002'; END IF;

  -- ── 4) acting actor — owner semantics decided by ROLE, never the actor id ────
  IF v_by.workspace_id IS DISTINCT FROM p_workspace_id THEN
    RAISE EXCEPTION 'AUTH_INITIATOR_OTHER_WORKSPACE' USING ERRCODE='P0001'; END IF;
  IF v_by.active <> true THEN RAISE EXCEPTION 'AUTH_INITIATOR_INACTIVE' USING ERRCODE='22023'; END IF;
  IF v_by.role NOT IN ('admin', 'owner') THEN RAISE EXCEPTION 'AUTH_NOT_OWNER' USING ERRCODE='P0001'; END IF;

  -- ── 5) target — same workspace, not the owner (by ROLE, never the actor id) ──
  IF v_tgt.workspace_id IS DISTINCT FROM p_workspace_id THEN
    RAISE EXCEPTION 'AUTH_TARGET_OTHER_WORKSPACE' USING ERRCODE='P0001'; END IF;
  IF v_tgt.role IN ('admin', 'owner') THEN RAISE EXCEPTION 'AUTH_TARGET_IS_OWNER' USING ERRCODE='P0001'; END IF;

  -- ── 6) idempotency KEY lookup — ONLY now, after acting-owner AND target identity
  --    are both proved against the CURRENT authoritative rows under lock (V3-G.1
  --    REORDER, preserved). V3-G.2 FIX: this fetches the stored row but does NOT yet
  --    return it — a changed-payload reuse of the same key conflicts IMMEDIATELY,
  --    unconditionally, exactly as before and BEFORE anything else runs (payload-
  --    conflict detection must never be preempted by the guard below). ─────────────
  SELECT * INTO v_idem FROM public.access_management_idempotency
   WHERE workspace_id = p_workspace_id AND by_actor = p_by_actor AND by_sid_hash = p_by_sid_hash
     AND action = 'change_actor_role' AND client_request_id = p_client_request_id;
  -- Captured into a dedicated variable IMMEDIATELY: the guard block below (step 8)
  -- runs its own SELECT/PERFORM statements, which would silently overwrite the
  -- ambient FOUND variable if it were relied on any later than this line.
  v_idem_found := FOUND;
  IF v_idem_found AND v_idem.request_hash <> p_request_hash THEN
    RAISE EXCEPTION 'AUTH_IDEMPOTENCY_CONFLICT' USING ERRCODE='23505';
  END IF;

  -- ── 7) identify the CURRENT operation from the locked, authoritative target row —
  --    computed unconditionally, for BOTH a genuine replay and a brand-new request
  --    (the guard in step 8 needs it either way). This is NOT the expected-role
  --    staleness check (that stays gated to the brand-new-request path in step 9,
  --    below the replay short-circuit — checking it here would reintroduce the
  --    exact bug V3-G.1 already fixed: replaying an already-decided request would
  --    incorrectly fail AUTH_TARGET_ROLE_MISMATCH against the target's now-different
  --    CURRENT role instead of returning the stored response). ─────────────────────
  v_old_role := v_tgt.role;
  v_changed := (v_old_role <> p_requested_role);

  -- ── 8) V3-G.2 FIX — waiter-open-tables role-change guard: ALWAYS evaluated against
  --    CURRENT authoritative state, for BOTH a genuine replay and a brand-new
  --    request. V3-G.1 placed this guard AFTER the idempotency short-circuit, so a
  --    STORED historical success could be replayed after intervening state changes
  --    (the target reassigned back to waiter and given an open table session) and
  --    still return the old success — a real bypass, reproduced against real
  --    PostgreSQL and closed here. Moving the guard here — after the changed-payload
  --    conflict check (step 6) but before the replay-return (step 9) — means a
  --    genuine replay is re-validated against CURRENT truth every time, while a
  --    changed-payload reuse still conflicts first, and an immediate replay of an
  --    already-successful change is unaffected (its CURRENT role already differs
  --    from p_requested_role in the OTHER direction, so v_changed there is false and
  --    the guard never applies). Only for a genuinely changed role (v_changed) AWAY
  --    from a locked, authoritative role='waiter' target — locks every open table
  --    session currently assigned to this waiter, deterministically (ORDER BY id).
  --    Raises BEFORE any mutation, audit, replay-return, or idempotency INSERT below
  --    — a rejected attempt (replay or new) writes nothing and returns nothing stale.
  IF v_changed AND v_old_role = 'waiter' THEN
    PERFORM 1 FROM public.table_sessions
     WHERE workspace_id = p_workspace_id AND assigned_waiter_actor = p_target_actor AND status = 'open'
     ORDER BY id FOR UPDATE;
    SELECT count(*) INTO v_open_tables FROM public.table_sessions
     WHERE workspace_id = p_workspace_id AND assigned_waiter_actor = p_target_actor AND status = 'open';
    IF v_open_tables > 0 THEN
      RAISE EXCEPTION 'AUTH_WAITER_HAS_OPEN_TABLES' USING ERRCODE='P0001';
    END IF;
  END IF;

  -- ── 9) genuine replay (same key, same payload) — survived the guard above, so it
  --    is safe to return the stored response: no mutation, no new audit, no re-check
  --    of expected-role staleness. Uses v_idem_found (captured at step 6), NEVER the
  --    ambient FOUND — the guard's own SELECT/PERFORM statements overwrite FOUND. ──
  IF v_idem_found THEN
    RETURN v_idem.response_body;
  END IF;

  -- ── 10) brand-new request (no stored idempotency row): expected current role must
  --     match the locked, authoritative target row (unchanged V3-C behavior/order —
  --     this stays AFTER the guard so a brand-new attempt against an open-assigned
  --     waiter reports the same AUTH_WAITER_HAS_OPEN_TABLES conflict a replay would,
  --     rather than a less specific staleness error). ────────────────────────────────
  IF v_tgt.role <> p_expected_role THEN RAISE EXCEPTION 'AUTH_TARGET_ROLE_MISMATCH' USING ERRCODE='22023'; END IF;

  IF NOT v_changed THEN
    -- ── identical current/requested role — deterministic no-op, no session_version
    --    bump, no audit row. Still recorded below so a literal replay of this exact
    --    no-op request is itself idempotent. ──────────────────────────────────────
    v_result := jsonb_build_object(
      'actor', v_tgt.actor, 'old_role', v_old_role, 'role', v_tgt.role,
      'session_version', v_tgt.session_version, 'changed', false,
      'updated_at', v_tgt.updated_at, 'updated_by', v_tgt.updated_by
    );
  ELSE
    -- ── real change — ONLY role + session_version on the TARGET row; pin_hash,
    --    fingerprint rows, active, display_name, failed_count, locked_until are
    --    never touched (the UPDATE below does not name them, and nothing else in
    --    this function writes to any other actor or to auth_actor_pin_fingerprints)
    UPDATE public.auth_actors
       SET role = p_requested_role, session_version = session_version + 1,
           updated_at = v_now, updated_by = p_by_actor
     WHERE actor = p_target_actor
     RETURNING * INTO r;

    INSERT INTO public.auth_audit(event, target_actor, by_actor, ip_hash, meta)
    VALUES ('role_changed', p_target_actor, p_by_actor, NULL,
            v_meta || jsonb_build_object(
              'old_role', v_old_role, 'new_role', p_requested_role,
              'workspace_id', p_workspace_id, 'client_request_id', p_client_request_id
            ));

    -- No global session invalidation: only the TARGET's session_version moved, so only
    -- the target's own live sessions stop verifying — everyone else is untouched.
    INSERT INTO public.auth_audit(event, target_actor, by_actor, ip_hash, meta)
    VALUES ('session_invalidated', p_target_actor, p_by_actor, NULL,
            jsonb_build_object('workspace_id', p_workspace_id, 'session_version', r.session_version));

    v_result := jsonb_build_object(
      'actor', r.actor, 'old_role', v_old_role, 'role', r.role,
      'session_version', r.session_version, 'changed', true,
      'updated_at', r.updated_at, 'updated_by', r.updated_by
    );
  END IF;

  -- ── idempotency record, same transaction as the mutation (or the no-op) above ──
  INSERT INTO public.access_management_idempotency
    (workspace_id, by_actor, by_sid_hash, action, client_request_id, request_hash, response_status, response_body)
  VALUES (p_workspace_id, p_by_actor, p_by_sid_hash, 'change_actor_role', p_client_request_id, p_request_hash, 200, v_result);

  RETURN v_result;
END;
$function$

CREATE OR REPLACE FUNCTION public.auth_clear_access_user_credential_v3(p_workspace_id uuid, p_by_actor text, p_target_actor text, p_expected_session_version integer, p_by_sid_hash text, p_client_request_id text, p_request_hash text, p_meta jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_ws public.workspaces%ROWTYPE;
  v_by public.auth_actors%ROWTYPE;
  v_tgt public.auth_actors%ROWTYPE;
  v_idem public.access_management_idempotency%ROWTYPE;
  v_meta jsonb := COALESCE(p_meta, '{}'::jsonb);
  v_now timestamptz := now();
  v_has_credential boolean;
  r public.auth_actors%ROWTYPE;
  v_result jsonb;
BEGIN
  -- ── input guards ──────────────────────────────────────────────────────────
  IF p_workspace_id IS NULL THEN RAISE EXCEPTION 'AUTH_WORKSPACE_REQUIRED' USING ERRCODE='22023'; END IF;
  IF p_by_actor IS NULL OR btrim(p_by_actor) = '' THEN RAISE EXCEPTION 'AUTH_INITIATOR_REQUIRED' USING ERRCODE='22023'; END IF;
  IF p_target_actor IS NULL OR btrim(p_target_actor) = '' THEN RAISE EXCEPTION 'AUTH_ACTOR_INVALID' USING ERRCODE='22023'; END IF;
  IF p_expected_session_version IS NULL OR p_expected_session_version < 1
  THEN RAISE EXCEPTION 'AUTH_EXPECTED_SESSION_VERSION_INVALID' USING ERRCODE='22023'; END IF;
  IF p_by_sid_hash IS NULL OR btrim(p_by_sid_hash) = '' OR length(p_by_sid_hash) > 64
  THEN RAISE EXCEPTION 'AUTH_SID_HASH_INVALID' USING ERRCODE='22023'; END IF;
  IF p_client_request_id IS NULL OR btrim(p_client_request_id) = '' OR length(p_client_request_id) > 128
  THEN RAISE EXCEPTION 'AUTH_CLIENT_REQUEST_ID_INVALID' USING ERRCODE='22023'; END IF;
  IF p_request_hash IS NULL OR p_request_hash !~ '^[0-9a-f]{64}$'
  THEN RAISE EXCEPTION 'AUTH_REQUEST_HASH_INVALID' USING ERRCODE='22023'; END IF;
  IF jsonb_typeof(v_meta) <> 'object' THEN RAISE EXCEPTION 'AUTH_META_INVALID' USING ERRCODE='22023'; END IF;
  IF length(v_meta::text) > 2048 THEN RAISE EXCEPTION 'AUTH_META_TOO_LARGE' USING ERRCODE='22023'; END IF;
  -- No plaintext PIN parameter exists on this function at all (see signature above);
  -- the meta blocklist below is additional defense-in-depth against a caller trying to
  -- smuggle credential material through the free-form audit metadata.
  IF EXISTS (SELECT 1 FROM jsonb_object_keys(v_meta) k WHERE lower(k) = ANY (ARRAY[
       'pin','pin_hash','password','token','access_token','refresh_token','jwt','secret',
       'recovery_secret','authorization','api_key','apikey','bearer','cookie','raw_ip',
       'confirmation','fingerprint','pin_fingerprint','fingerprint_key','hmac_key',
       'proof','step_up_proof','sid','display_name']))
  THEN RAISE EXCEPTION 'AUTH_META_SENSITIVE_KEY' USING ERRCODE='22023'; END IF;

  -- ── workspace row lock — the serialisation point ──────────────────────────
  SELECT * INTO v_ws FROM public.workspaces WHERE id = p_workspace_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'WORKSPACE_NOT_FOUND' USING ERRCODE='P0002'; END IF;
  IF v_ws.lifecycle_status <> 'active' THEN RAISE EXCEPTION 'WORKSPACE_NOT_ACTIVE' USING ERRCODE='22023'; END IF;

  -- ── deterministic actor-id locking — acting + target, ordered ─────────────
  -- Authorization is proved BEFORE any idempotency lookup/replay below — a revoked,
  -- deactivated, or demoted acting actor must never receive a stored success response
  -- merely because a matching idempotency record exists from when they WERE authorized.
  PERFORM 1 FROM public.auth_actors WHERE actor IN (p_by_actor, p_target_actor) ORDER BY actor FOR UPDATE;

  SELECT * INTO v_by FROM public.auth_actors WHERE actor = p_by_actor;
  IF NOT FOUND THEN RAISE EXCEPTION 'AUTH_INITIATOR_NOT_FOUND' USING ERRCODE='P0002'; END IF;
  SELECT * INTO v_tgt FROM public.auth_actors WHERE actor = p_target_actor;
  IF NOT FOUND THEN RAISE EXCEPTION 'AUTH_ACTOR_NOT_FOUND' USING ERRCODE='P0002'; END IF;

  -- ── acting actor — owner semantics decided by ROLE, never the actor id ────
  IF v_by.workspace_id IS DISTINCT FROM p_workspace_id THEN
    RAISE EXCEPTION 'AUTH_INITIATOR_OTHER_WORKSPACE' USING ERRCODE='P0001'; END IF;
  IF v_by.active <> true THEN RAISE EXCEPTION 'AUTH_INITIATOR_INACTIVE' USING ERRCODE='22023'; END IF;
  IF v_by.role NOT IN ('admin', 'owner') THEN RAISE EXCEPTION 'AUTH_NOT_OWNER' USING ERRCODE='P0001'; END IF;

  -- ── target — same workspace; owner rejected by ROLE; everything else must be on
  --    the explicit POSITIVE allowlist (never a denylist). Works on an ACTIVE or
  --    INACTIVE target -- no active check here, deliberately. ───────────────────
  IF v_tgt.workspace_id IS DISTINCT FROM p_workspace_id THEN
    RAISE EXCEPTION 'AUTH_TARGET_OTHER_WORKSPACE' USING ERRCODE='P0001'; END IF;
  IF v_tgt.role IN ('admin', 'owner') THEN RAISE EXCEPTION 'AUTH_TARGET_IS_OWNER' USING ERRCODE='P0001'; END IF;
  IF v_tgt.role IS NULL OR v_tgt.role NOT IN
     ('operator', 'legacy_operator', 'cashier', 'waiter', 'kitchen', 'rider', 'shift_manager')
  THEN RAISE EXCEPTION 'AUTH_TARGET_ROLE_INELIGIBLE' USING ERRCODE='P0001'; END IF;

  -- ── idempotency lookup — ONLY now, after acting-owner AND target-eligibility are
  --    both proved against the CURRENT authoritative rows under lock ───────────
  SELECT * INTO v_idem FROM public.access_management_idempotency
   WHERE workspace_id = p_workspace_id AND by_actor = p_by_actor AND by_sid_hash = p_by_sid_hash
     AND action = 'clear_access_user_credential_v3' AND client_request_id = p_client_request_id;
  IF FOUND THEN
    IF v_idem.request_hash = p_request_hash THEN
      RETURN v_idem.response_body; -- safe replay: no mutation, no new audit
    ELSE
      RAISE EXCEPTION 'AUTH_IDEMPOTENCY_CONFLICT' USING ERRCODE='23505';
    END IF;
  END IF;

  -- ── stale-snapshot check against the locked, authoritative target row ─────
  IF v_tgt.session_version <> p_expected_session_version THEN
    RAISE EXCEPTION 'AUTH_TARGET_STALE' USING ERRCODE='40001'; END IF;

  v_has_credential := (v_tgt.pin_hash IS NOT NULL)
    OR EXISTS (SELECT 1 FROM public.auth_actor_pin_fingerprints WHERE actor = p_target_actor);

  IF NOT v_has_credential THEN
    -- no credential exists — deterministic no-op, no session_version bump, no audit.
    v_result := jsonb_build_object(
      'actor', v_tgt.actor, 'role', v_tgt.role, 'active', v_tgt.active,
      'session_version', v_tgt.session_version, 'failed_count', v_tgt.failed_count,
      'locked_until', v_tgt.locked_until, 'updated_at', v_tgt.updated_at, 'updated_by', v_tgt.updated_by
    );
  ELSE
    -- real clear — pin_hash/failed_count/locked_until/session_version on the TARGET
    -- row, plus every fingerprint row for the target, across all key ids. role,
    -- active, display_name, actor, workspace_id, created_at, created_by: untouched.
    UPDATE public.auth_actors
       SET pin_hash = NULL, failed_count = 0, locked_until = NULL,
           session_version = session_version + 1, updated_at = v_now, updated_by = p_by_actor
     WHERE actor = p_target_actor
     RETURNING * INTO r;

    DELETE FROM public.auth_actor_pin_fingerprints WHERE actor = p_target_actor;

    INSERT INTO public.auth_audit(event, target_actor, by_actor, ip_hash, meta)
    VALUES ('credential_cleared', p_target_actor, p_by_actor, NULL,
            v_meta || jsonb_build_object(
              'workspace_id', p_workspace_id, 'client_request_id', p_client_request_id
            ));

    INSERT INTO public.auth_audit(event, target_actor, by_actor, ip_hash, meta)
    VALUES ('session_invalidated', p_target_actor, p_by_actor, NULL,
            jsonb_build_object('workspace_id', p_workspace_id, 'session_version', r.session_version));

    v_result := jsonb_build_object(
      'actor', r.actor, 'role', r.role, 'active', r.active,
      'session_version', r.session_version, 'failed_count', r.failed_count,
      'locked_until', r.locked_until, 'updated_at', r.updated_at, 'updated_by', r.updated_by
    );
  END IF;

  INSERT INTO public.access_management_idempotency
    (workspace_id, by_actor, by_sid_hash, action, client_request_id, request_hash, response_status, response_body)
  VALUES (p_workspace_id, p_by_actor, p_by_sid_hash, 'clear_access_user_credential_v3', p_client_request_id, p_request_hash, 200, v_result);

  RETURN v_result;
END;
$function$

CREATE OR REPLACE FUNCTION public.auth_create_access_user_v3(p_workspace_id uuid, p_by_actor text, p_display_name text, p_requested_role text, p_by_sid_hash text, p_client_request_id text, p_request_hash text, p_meta jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_ws public.workspaces%ROWTYPE;
  v_by public.auth_actors%ROWTYPE;
  v_idem public.access_management_idempotency%ROWTYPE;
  v_meta jsonb := COALESCE(p_meta, '{}'::jsonb);
  v_now timestamptz := now();
  v_display_name text;
  v_new_actor text;
  r public.auth_actors%ROWTYPE;
  v_result jsonb;
BEGIN
  -- ── input guards ──────────────────────────────────────────────────────────
  IF p_workspace_id IS NULL THEN RAISE EXCEPTION 'AUTH_WORKSPACE_REQUIRED' USING ERRCODE='22023'; END IF;
  IF p_by_actor IS NULL OR btrim(p_by_actor) = '' THEN RAISE EXCEPTION 'AUTH_INITIATOR_REQUIRED' USING ERRCODE='22023'; END IF;
  IF p_display_name IS NULL THEN RAISE EXCEPTION 'AUTH_DISPLAY_NAME_INVALID' USING ERRCODE='22023'; END IF;
  v_display_name := btrim(p_display_name);
  IF length(v_display_name) = 0 OR length(v_display_name) > 120 OR v_display_name ~ '[\x00-\x1F\x7F]'
  THEN RAISE EXCEPTION 'AUTH_DISPLAY_NAME_INVALID' USING ERRCODE='22023'; END IF;
  IF p_requested_role IS NULL OR p_requested_role NOT IN ('cashier', 'waiter', 'kitchen', 'rider', 'shift_manager')
  THEN RAISE EXCEPTION 'AUTH_REQUESTED_ROLE_INVALID' USING ERRCODE='22023'; END IF;
  IF p_by_sid_hash IS NULL OR btrim(p_by_sid_hash) = '' OR length(p_by_sid_hash) > 64
  THEN RAISE EXCEPTION 'AUTH_SID_HASH_INVALID' USING ERRCODE='22023'; END IF;
  IF p_client_request_id IS NULL OR btrim(p_client_request_id) = '' OR length(p_client_request_id) > 128
  THEN RAISE EXCEPTION 'AUTH_CLIENT_REQUEST_ID_INVALID' USING ERRCODE='22023'; END IF;
  IF p_request_hash IS NULL OR p_request_hash !~ '^[0-9a-f]{64}$'
  THEN RAISE EXCEPTION 'AUTH_REQUEST_HASH_INVALID' USING ERRCODE='22023'; END IF;
  IF jsonb_typeof(v_meta) <> 'object' THEN RAISE EXCEPTION 'AUTH_META_INVALID' USING ERRCODE='22023'; END IF;
  IF length(v_meta::text) > 2048 THEN RAISE EXCEPTION 'AUTH_META_TOO_LARGE' USING ERRCODE='22023'; END IF;
  IF EXISTS (SELECT 1 FROM jsonb_object_keys(v_meta) k WHERE lower(k) = ANY (ARRAY[
       'pin','pin_hash','password','token','access_token','refresh_token','jwt','secret',
       'recovery_secret','authorization','api_key','apikey','bearer','cookie','raw_ip',
       'confirmation','fingerprint','pin_fingerprint','fingerprint_key','hmac_key',
       'proof','step_up_proof','sid','actor','user_id','created_by','updated_by']))
  THEN RAISE EXCEPTION 'AUTH_META_SENSITIVE_KEY' USING ERRCODE='22023'; END IF;

  -- ── workspace row lock — the serialisation point ──────────────────────────
  SELECT * INTO v_ws FROM public.workspaces WHERE id = p_workspace_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'WORKSPACE_NOT_FOUND' USING ERRCODE='P0002'; END IF;
  IF v_ws.lifecycle_status <> 'active' THEN RAISE EXCEPTION 'WORKSPACE_NOT_ACTIVE' USING ERRCODE='22023'; END IF;

  -- ── idempotency lookup, already serialised by the workspace lock above ────
  SELECT * INTO v_idem FROM public.access_management_idempotency
   WHERE workspace_id = p_workspace_id AND by_actor = p_by_actor AND by_sid_hash = p_by_sid_hash
     AND action = 'create_access_user_v3' AND client_request_id = p_client_request_id;
  IF FOUND THEN
    IF v_idem.request_hash = p_request_hash THEN
      RETURN v_idem.response_body; -- safe replay: same originally-created actor, no new row
    ELSE
      RAISE EXCEPTION 'AUTH_IDEMPOTENCY_CONFLICT' USING ERRCODE='23505';
    END IF;
  END IF;

  -- ── lock and re-read the acting owner actor ───────────────────────────────
  SELECT * INTO v_by FROM public.auth_actors WHERE actor = p_by_actor FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'AUTH_INITIATOR_NOT_FOUND' USING ERRCODE='P0002'; END IF;
  IF v_by.workspace_id IS DISTINCT FROM p_workspace_id THEN
    RAISE EXCEPTION 'AUTH_INITIATOR_OTHER_WORKSPACE' USING ERRCODE='P0001'; END IF;
  IF v_by.active <> true THEN RAISE EXCEPTION 'AUTH_INITIATOR_INACTIVE' USING ERRCODE='22023'; END IF;
  IF v_by.role NOT IN ('admin', 'owner') THEN RAISE EXCEPTION 'AUTH_NOT_OWNER' USING ERRCODE='P0001'; END IF;

  -- ── generate the new actor id server-side — the client never supplies one ─
  v_new_actor := gen_random_uuid()::text;

  INSERT INTO public.auth_actors (
    actor, role, workspace_id, pin_hash, session_version, active, failed_count,
    locked_until, display_name, created_at, created_by, updated_at, updated_by
  ) VALUES (
    v_new_actor, p_requested_role, p_workspace_id, NULL, 1, true, 0,
    NULL, v_display_name, v_now, p_by_actor, v_now, NULL
  ) RETURNING * INTO r;

  INSERT INTO public.auth_audit(event, target_actor, by_actor, ip_hash, meta)
  VALUES ('user_created', v_new_actor, p_by_actor, NULL,
          v_meta || jsonb_build_object(
            'requested_role', p_requested_role, 'workspace_id', p_workspace_id,
            'client_request_id', p_client_request_id
          ));

  v_result := jsonb_build_object(
    'actor', r.actor, 'display_name', r.display_name, 'role', r.role,
    'active', r.active, 'session_version', r.session_version,
    'created_at', r.created_at, 'updated_at', r.updated_at
  );

  INSERT INTO public.access_management_idempotency
    (workspace_id, by_actor, by_sid_hash, action, client_request_id, request_hash, response_status, response_body)
  VALUES (p_workspace_id, p_by_actor, p_by_sid_hash, 'create_access_user_v3', p_client_request_id, p_request_hash, 200, v_result);

  RETURN v_result;
END;
$function$

CREATE OR REPLACE FUNCTION public.auth_record_failed_attempt(p_actor text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE r public.auth_actors%ROWTYPE; nfc int; lock_min int; new_lock timestamptz;
BEGIN
  SELECT * INTO r FROM public.auth_actors WHERE actor = p_actor FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'AUTH_ACTOR_NOT_FOUND' USING ERRCODE='P0002'; END IF;
  IF r.locked_until IS NOT NULL AND r.locked_until > now() THEN
    RETURN jsonb_build_object('failed_count', r.failed_count, 'locked_until', r.locked_until,
      'locked', true, 'retry_after_sec', ceil(extract(epoch FROM (r.locked_until - now())))::int);
  END IF;
  nfc := r.failed_count + 1;
  lock_min := CASE WHEN nfc < 5 THEN 0 WHEN nfc = 5 THEN 1 WHEN nfc = 6 THEN 5 WHEN nfc = 7 THEN 15 ELSE 60 END;
  new_lock := CASE WHEN lock_min = 0 THEN NULL ELSE now() + make_interval(mins => lock_min) END;
  UPDATE public.auth_actors SET failed_count = nfc, locked_until = new_lock WHERE actor = p_actor;
  RETURN jsonb_build_object('failed_count', nfc, 'locked_until', new_lock, 'locked', new_lock IS NOT NULL,
    'retry_after_sec', CASE WHEN new_lock IS NULL THEN 0 ELSE ceil(extract(epoch FROM (new_lock - now())))::int END);
END; $function$

CREATE OR REPLACE FUNCTION public.auth_register_recovery_window(p_window_id text, p_purpose text, p_actor text, p_secret_digest text, p_expires_at timestamp with time zone, p_meta jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_meta jsonb := COALESCE(p_meta,'{}'::jsonb); e public.auth_recovery_windows%ROWTYPE; v_now timestamptz := now();
BEGIN
  IF p_purpose NOT IN ('bootstrap','recovery') THEN RAISE EXCEPTION 'AUTH_WINDOW_PURPOSE_INVALID' USING ERRCODE='22023'; END IF;
  IF jsonb_typeof(v_meta) <> 'object' THEN RAISE EXCEPTION 'AUTH_META_INVALID' USING ERRCODE='22023'; END IF;
  IF length(v_meta::text) > 2048 THEN RAISE EXCEPTION 'AUTH_META_TOO_LARGE' USING ERRCODE='22023'; END IF;
  IF EXISTS (SELECT 1 FROM jsonb_object_keys(v_meta) k WHERE lower(k) = ANY (ARRAY[
       'pin','password','token','access_token','refresh_token','jwt','secret',
       'recovery_secret','authorization','api_key','apikey','bearer','cookie']))
  THEN RAISE EXCEPTION 'AUTH_META_SENSITIVE_KEY' USING ERRCODE='22023'; END IF;
  -- server/db time is authoritative for the lifetime bounds
  IF p_expires_at <= v_now THEN RAISE EXCEPTION 'AUTH_WINDOW_EXPIRED' USING ERRCODE='22023'; END IF;
  IF p_expires_at > v_now + interval '15 minutes' THEN RAISE EXCEPTION 'AUTH_WINDOW_LIFETIME_EXCEEDED' USING ERRCODE='22023'; END IF;

  INSERT INTO public.auth_recovery_windows(window_id, purpose, actor, secret_digest, created_at, expires_at, metadata)
  VALUES (p_window_id, p_purpose, p_actor, p_secret_digest, v_now, p_expires_at, v_meta)
  ON CONFLICT (window_id) DO NOTHING;

  IF FOUND THEN
    RETURN jsonb_build_object('window_id', p_window_id, 'registered', true, 'existed', false, 'consumed', false);
  END IF;

  -- Conflict: the descriptor is immutable. Verify an EXACT match; never reset
  -- consumed_at; never reopen. A restart/second instance re-registering the same
  -- descriptor is a safe no-op; an altered descriptor fails closed.
  SELECT * INTO e FROM public.auth_recovery_windows WHERE window_id = p_window_id;
  IF e.purpose <> p_purpose OR e.actor <> p_actor
     OR e.secret_digest <> p_secret_digest OR e.expires_at <> p_expires_at THEN
    RAISE EXCEPTION 'AUTH_WINDOW_DESCRIPTOR_MISMATCH' USING ERRCODE='22023';
  END IF;
  RETURN jsonb_build_object('window_id', p_window_id, 'registered', true, 'existed', true,
                            'consumed', e.consumed_at IS NOT NULL);
END;
$function$

CREATE OR REPLACE FUNCTION public.auth_rename_access_user_v3(p_workspace_id uuid, p_by_actor text, p_target_actor text, p_new_display_name text, p_by_sid_hash text, p_client_request_id text, p_request_hash text, p_meta jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_ws public.workspaces%ROWTYPE;
  v_by public.auth_actors%ROWTYPE;
  v_tgt public.auth_actors%ROWTYPE;
  v_idem public.access_management_idempotency%ROWTYPE;
  v_meta jsonb := COALESCE(p_meta, '{}'::jsonb);
  v_now timestamptz := now();
  v_new_name text;
  v_old_name text;
  v_changed boolean;
  r public.auth_actors%ROWTYPE;
  v_result jsonb;
BEGIN
  -- ── input guards ──────────────────────────────────────────────────────────
  IF p_workspace_id IS NULL THEN RAISE EXCEPTION 'AUTH_WORKSPACE_REQUIRED' USING ERRCODE='22023'; END IF;
  IF p_by_actor IS NULL OR btrim(p_by_actor) = '' THEN RAISE EXCEPTION 'AUTH_INITIATOR_REQUIRED' USING ERRCODE='22023'; END IF;
  IF p_target_actor IS NULL OR btrim(p_target_actor) = '' THEN RAISE EXCEPTION 'AUTH_ACTOR_INVALID' USING ERRCODE='22023'; END IF;
  IF p_new_display_name IS NULL THEN RAISE EXCEPTION 'AUTH_DISPLAY_NAME_INVALID' USING ERRCODE='22023'; END IF;
  v_new_name := btrim(p_new_display_name);
  IF length(v_new_name) = 0 OR length(v_new_name) > 120 OR v_new_name ~ '[\x00-\x1F\x7F]'
  THEN RAISE EXCEPTION 'AUTH_DISPLAY_NAME_INVALID' USING ERRCODE='22023'; END IF;
  IF p_by_sid_hash IS NULL OR btrim(p_by_sid_hash) = '' OR length(p_by_sid_hash) > 64
  THEN RAISE EXCEPTION 'AUTH_SID_HASH_INVALID' USING ERRCODE='22023'; END IF;
  IF p_client_request_id IS NULL OR btrim(p_client_request_id) = '' OR length(p_client_request_id) > 128
  THEN RAISE EXCEPTION 'AUTH_CLIENT_REQUEST_ID_INVALID' USING ERRCODE='22023'; END IF;
  IF p_request_hash IS NULL OR p_request_hash !~ '^[0-9a-f]{64}$'
  THEN RAISE EXCEPTION 'AUTH_REQUEST_HASH_INVALID' USING ERRCODE='22023'; END IF;
  IF jsonb_typeof(v_meta) <> 'object' THEN RAISE EXCEPTION 'AUTH_META_INVALID' USING ERRCODE='22023'; END IF;
  IF length(v_meta::text) > 2048 THEN RAISE EXCEPTION 'AUTH_META_TOO_LARGE' USING ERRCODE='22023'; END IF;
  IF EXISTS (SELECT 1 FROM jsonb_object_keys(v_meta) k WHERE lower(k) = ANY (ARRAY[
       'pin','pin_hash','password','token','access_token','refresh_token','jwt','secret',
       'recovery_secret','authorization','api_key','apikey','bearer','cookie','raw_ip',
       'confirmation','fingerprint','pin_fingerprint','fingerprint_key','hmac_key',
       'proof','step_up_proof','sid','display_name','new_display_name']))
  THEN RAISE EXCEPTION 'AUTH_META_SENSITIVE_KEY' USING ERRCODE='22023'; END IF;

  -- ── workspace row lock — the serialisation point ──────────────────────────
  SELECT * INTO v_ws FROM public.workspaces WHERE id = p_workspace_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'WORKSPACE_NOT_FOUND' USING ERRCODE='P0002'; END IF;
  IF v_ws.lifecycle_status <> 'active' THEN RAISE EXCEPTION 'WORKSPACE_NOT_ACTIVE' USING ERRCODE='22023'; END IF;

  -- ── idempotency lookup, already serialised by the workspace lock above ────
  SELECT * INTO v_idem FROM public.access_management_idempotency
   WHERE workspace_id = p_workspace_id AND by_actor = p_by_actor AND by_sid_hash = p_by_sid_hash
     AND action = 'rename_access_user_v3' AND client_request_id = p_client_request_id;
  IF FOUND THEN
    IF v_idem.request_hash = p_request_hash THEN
      RETURN v_idem.response_body; -- safe replay: no mutation, no new audit
    ELSE
      RAISE EXCEPTION 'AUTH_IDEMPOTENCY_CONFLICT' USING ERRCODE='23505';
    END IF;
  END IF;

  -- ── deterministic actor-id locking — acting + target, ordered; self-rename
  --    (p_by_actor = p_target_actor, e.g. the owner renaming themselves) is explicitly
  --    allowed and dedupes naturally to one row in the IN-list ──────────────────
  PERFORM 1 FROM public.auth_actors WHERE actor IN (p_by_actor, p_target_actor) ORDER BY actor FOR UPDATE;

  SELECT * INTO v_by FROM public.auth_actors WHERE actor = p_by_actor;
  IF NOT FOUND THEN RAISE EXCEPTION 'AUTH_INITIATOR_NOT_FOUND' USING ERRCODE='P0002'; END IF;
  SELECT * INTO v_tgt FROM public.auth_actors WHERE actor = p_target_actor;
  IF NOT FOUND THEN RAISE EXCEPTION 'AUTH_ACTOR_NOT_FOUND' USING ERRCODE='P0002'; END IF;

  -- ── acting actor — owner semantics decided by ROLE, never the actor id ────
  IF v_by.workspace_id IS DISTINCT FROM p_workspace_id THEN
    RAISE EXCEPTION 'AUTH_INITIATOR_OTHER_WORKSPACE' USING ERRCODE='P0001'; END IF;
  IF v_by.active <> true THEN RAISE EXCEPTION 'AUTH_INITIATOR_INACTIVE' USING ERRCODE='22023'; END IF;
  IF v_by.role NOT IN ('admin', 'owner') THEN RAISE EXCEPTION 'AUTH_NOT_OWNER' USING ERRCODE='P0001'; END IF;

  -- ── target — same workspace. NO owner exclusion: the owner may rename themselves ──
  IF v_tgt.workspace_id IS DISTINCT FROM p_workspace_id THEN
    RAISE EXCEPTION 'AUTH_TARGET_OTHER_WORKSPACE' USING ERRCODE='P0001'; END IF;

  v_old_name := v_tgt.display_name;
  v_changed := (v_old_name IS DISTINCT FROM v_new_name);

  IF NOT v_changed THEN
    -- identical normalized name — deterministic no-op, no audit, no updated_at bump.
    v_result := jsonb_build_object(
      'actor', v_tgt.actor, 'display_name', v_tgt.display_name, 'role', v_tgt.role,
      'active', v_tgt.active, 'session_version', v_tgt.session_version,
      'updated_at', v_tgt.updated_at, 'updated_by', v_tgt.updated_by
    );
  ELSE
    -- real rename — ONLY display_name (+ updated_at/updated_by). role, active,
    -- session_version, pin_hash, fingerprint rows, failed_count, locked_until: untouched.
    UPDATE public.auth_actors
       SET display_name = v_new_name, updated_at = v_now, updated_by = p_by_actor
     WHERE actor = p_target_actor
     RETURNING * INTO r;

    INSERT INTO public.auth_audit(event, target_actor, by_actor, ip_hash, meta)
    VALUES ('user_renamed', p_target_actor, p_by_actor, NULL,
            v_meta || jsonb_build_object(
              'workspace_id', p_workspace_id, 'client_request_id', p_client_request_id,
              'old_name_len', length(COALESCE(v_old_name, '')), 'new_name_len', length(v_new_name)
            ));

    v_result := jsonb_build_object(
      'actor', r.actor, 'display_name', r.display_name, 'role', r.role,
      'active', r.active, 'session_version', r.session_version,
      'updated_at', r.updated_at, 'updated_by', r.updated_by
    );
  END IF;

  INSERT INTO public.access_management_idempotency
    (workspace_id, by_actor, by_sid_hash, action, client_request_id, request_hash, response_status, response_body)
  VALUES (p_workspace_id, p_by_actor, p_by_sid_hash, 'rename_access_user_v3', p_client_request_id, p_request_hash, 200, v_result);

  RETURN v_result;
END;
$function$

CREATE OR REPLACE FUNCTION public.auth_reset_failed_attempts(p_actor text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v public.auth_actors%ROWTYPE;
BEGIN
  UPDATE public.auth_actors SET failed_count = 0, locked_until = NULL WHERE actor = p_actor RETURNING * INTO v;
  IF NOT FOUND THEN RAISE EXCEPTION 'AUTH_ACTOR_NOT_FOUND' USING ERRCODE='P0002'; END IF;
  RETURN jsonb_build_object('actor', v.actor, 'session_version', v.session_version,
    'failed_count', v.failed_count, 'locked_until', v.locked_until, 'active', v.active);
END; $function$

CREATE OR REPLACE FUNCTION public.auth_set_access_user_active_v3(p_workspace_id uuid, p_by_actor text, p_target_actor text, p_expected_active boolean, p_requested_active boolean, p_by_sid_hash text, p_client_request_id text, p_request_hash text, p_meta jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_ws public.workspaces%ROWTYPE;
  v_by public.auth_actors%ROWTYPE;
  v_tgt public.auth_actors%ROWTYPE;
  v_idem public.access_management_idempotency%ROWTYPE;
  v_meta jsonb := COALESCE(p_meta, '{}'::jsonb);
  v_now timestamptz := now();
  v_action text;
  v_event text;
  v_changed boolean;
  v_open_tables int;
  r public.auth_actors%ROWTYPE;
  v_result jsonb;
BEGIN
  -- ── input guards ──────────────────────────────────────────────────────────
  IF p_workspace_id IS NULL THEN RAISE EXCEPTION 'AUTH_WORKSPACE_REQUIRED' USING ERRCODE='22023'; END IF;
  IF p_by_actor IS NULL OR btrim(p_by_actor) = '' THEN RAISE EXCEPTION 'AUTH_INITIATOR_REQUIRED' USING ERRCODE='22023'; END IF;
  IF p_target_actor IS NULL OR btrim(p_target_actor) = '' THEN RAISE EXCEPTION 'AUTH_ACTOR_INVALID' USING ERRCODE='22023'; END IF;
  IF p_expected_active IS NULL THEN RAISE EXCEPTION 'AUTH_EXPECTED_ACTIVE_REQUIRED' USING ERRCODE='22023'; END IF;
  IF p_requested_active IS NULL THEN RAISE EXCEPTION 'AUTH_REQUESTED_ACTIVE_REQUIRED' USING ERRCODE='22023'; END IF;
  IF p_by_sid_hash IS NULL OR btrim(p_by_sid_hash) = '' OR length(p_by_sid_hash) > 64
  THEN RAISE EXCEPTION 'AUTH_SID_HASH_INVALID' USING ERRCODE='22023'; END IF;
  IF p_client_request_id IS NULL OR btrim(p_client_request_id) = '' OR length(p_client_request_id) > 128
  THEN RAISE EXCEPTION 'AUTH_CLIENT_REQUEST_ID_INVALID' USING ERRCODE='22023'; END IF;
  IF p_request_hash IS NULL OR p_request_hash !~ '^[0-9a-f]{64}$'
  THEN RAISE EXCEPTION 'AUTH_REQUEST_HASH_INVALID' USING ERRCODE='22023'; END IF;
  IF jsonb_typeof(v_meta) <> 'object' THEN RAISE EXCEPTION 'AUTH_META_INVALID' USING ERRCODE='22023'; END IF;
  IF length(v_meta::text) > 2048 THEN RAISE EXCEPTION 'AUTH_META_TOO_LARGE' USING ERRCODE='22023'; END IF;
  IF EXISTS (SELECT 1 FROM jsonb_object_keys(v_meta) k WHERE lower(k) = ANY (ARRAY[
       'pin','pin_hash','password','token','access_token','refresh_token','jwt','secret',
       'recovery_secret','authorization','api_key','apikey','bearer','cookie','raw_ip',
       'confirmation','fingerprint','pin_fingerprint','fingerprint_key','hmac_key',
       'proof','step_up_proof','sid','display_name']))
  THEN RAISE EXCEPTION 'AUTH_META_SENSITIVE_KEY' USING ERRCODE='22023'; END IF;

  -- stable idempotency action identifier, decided by the REQUESTED direction
  v_action := CASE WHEN p_requested_active THEN 'reactivate_access_user_v3' ELSE 'deactivate_access_user_v3' END;

  -- ── workspace row lock — the serialisation point ──────────────────────────
  SELECT * INTO v_ws FROM public.workspaces WHERE id = p_workspace_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'WORKSPACE_NOT_FOUND' USING ERRCODE='P0002'; END IF;
  IF v_ws.lifecycle_status <> 'active' THEN RAISE EXCEPTION 'WORKSPACE_NOT_ACTIVE' USING ERRCODE='22023'; END IF;

  -- ── deterministic actor-id locking — acting + target, ordered ─────────────
  -- Authorization is proved BEFORE any idempotency lookup/replay below — a revoked,
  -- deactivated, or demoted acting actor must never receive a stored success response
  -- merely because a matching idempotency record exists from when they WERE authorized.
  PERFORM 1 FROM public.auth_actors WHERE actor IN (p_by_actor, p_target_actor) ORDER BY actor FOR UPDATE;

  SELECT * INTO v_by FROM public.auth_actors WHERE actor = p_by_actor;
  IF NOT FOUND THEN RAISE EXCEPTION 'AUTH_INITIATOR_NOT_FOUND' USING ERRCODE='P0002'; END IF;
  SELECT * INTO v_tgt FROM public.auth_actors WHERE actor = p_target_actor;
  IF NOT FOUND THEN RAISE EXCEPTION 'AUTH_ACTOR_NOT_FOUND' USING ERRCODE='P0002'; END IF;

  -- ── acting actor — owner semantics decided by ROLE, never the actor id ────
  IF v_by.workspace_id IS DISTINCT FROM p_workspace_id THEN
    RAISE EXCEPTION 'AUTH_INITIATOR_OTHER_WORKSPACE' USING ERRCODE='P0001'; END IF;
  IF v_by.active <> true THEN RAISE EXCEPTION 'AUTH_INITIATOR_INACTIVE' USING ERRCODE='22023'; END IF;
  IF v_by.role NOT IN ('admin', 'owner') THEN RAISE EXCEPTION 'AUTH_NOT_OWNER' USING ERRCODE='P0001'; END IF;

  -- ── target — same workspace; owner rejected by ROLE; everything else must be on
  --    the explicit POSITIVE allowlist (never a denylist — an unknown, malformed, or
  --    future role that has not been explicitly approved must fail closed, not pass
  --    through as "not admin/owner") ─────────────────────────────────────────
  IF v_tgt.workspace_id IS DISTINCT FROM p_workspace_id THEN
    RAISE EXCEPTION 'AUTH_TARGET_OTHER_WORKSPACE' USING ERRCODE='P0001'; END IF;
  IF v_tgt.role IN ('admin', 'owner') THEN RAISE EXCEPTION 'AUTH_TARGET_IS_OWNER' USING ERRCODE='P0001'; END IF;
  IF v_tgt.role IS NULL OR v_tgt.role NOT IN
     ('operator', 'legacy_operator', 'cashier', 'waiter', 'kitchen', 'rider', 'shift_manager')
  THEN RAISE EXCEPTION 'AUTH_TARGET_ROLE_INELIGIBLE' USING ERRCODE='P0001'; END IF;

  -- ── idempotency lookup — ONLY now, after acting-owner AND target-eligibility are
  --    both proved against the CURRENT authoritative rows under lock ───────────
  SELECT * INTO v_idem FROM public.access_management_idempotency
   WHERE workspace_id = p_workspace_id AND by_actor = p_by_actor AND by_sid_hash = p_by_sid_hash
     AND action = v_action AND client_request_id = p_client_request_id;
  IF FOUND THEN
    IF v_idem.request_hash = p_request_hash THEN
      RETURN v_idem.response_body; -- safe replay: no mutation, no new audit
    ELSE
      RAISE EXCEPTION 'AUTH_IDEMPOTENCY_CONFLICT' USING ERRCODE='23505';
    END IF;
  END IF;

  -- ── expected active state must match the locked, authoritative target row ─
  IF v_tgt.active <> p_expected_active THEN RAISE EXCEPTION 'AUTH_TARGET_STATE_MISMATCH' USING ERRCODE='22023'; END IF;

  v_changed := (v_tgt.active <> p_requested_active);

  -- ── V3-G ADDITION: waiter-open-tables deactivation guard ──────────────────
  -- Only for a genuinely NEW (v_changed), real DEACTIVATION (NOT p_requested_active) of
  -- a locked, authoritative role='waiter' target. Locks every open table session
  -- currently assigned to this waiter, deterministically (ORDER BY id), so a
  -- concurrent assignment RPC touching the SAME rows serializes behind this lock too —
  -- though the PRIMARY race defense is that both RPCs already lock the waiter's
  -- auth_actors row FIRST, before either ever touches table_sessions. Raises BEFORE
  -- any UPDATE/INSERT below: no actor mutation, no audit row, no idempotency row is
  -- ever written for a rejected attempt.
  IF v_changed AND NOT p_requested_active AND v_tgt.role = 'waiter' THEN
    PERFORM 1 FROM public.table_sessions
     WHERE workspace_id = p_workspace_id AND assigned_waiter_actor = p_target_actor AND status = 'open'
     ORDER BY id FOR UPDATE;
    SELECT count(*) INTO v_open_tables FROM public.table_sessions
     WHERE workspace_id = p_workspace_id AND assigned_waiter_actor = p_target_actor AND status = 'open';
    IF v_open_tables > 0 THEN
      RAISE EXCEPTION 'AUTH_WAITER_HAS_OPEN_TABLES' USING ERRCODE='P0001';
    END IF;
  END IF;
  -- ── END V3-G ADDITION ──────────────────────────────────────────────────────

  IF NOT v_changed THEN
    -- identical current/requested state — deterministic no-op, no session_version
    -- bump, no audit row.
    v_result := jsonb_build_object(
      'actor', v_tgt.actor, 'active', v_tgt.active, 'role', v_tgt.role,
      'session_version', v_tgt.session_version, 'failed_count', v_tgt.failed_count,
      'locked_until', v_tgt.locked_until, 'updated_at', v_tgt.updated_at, 'updated_by', v_tgt.updated_by
    );
  ELSE
    -- real state change — ONLY active + session_version on the TARGET row. role,
    -- display_name, pin_hash, fingerprint rows, failed_count, locked_until, actor,
    -- workspace_id, created_at, created_by: untouched.
    v_event := CASE WHEN p_requested_active THEN 'user_reactivated' ELSE 'user_deactivated' END;

    UPDATE public.auth_actors
       SET active = p_requested_active, session_version = session_version + 1,
           updated_at = v_now, updated_by = p_by_actor
     WHERE actor = p_target_actor
     RETURNING * INTO r;

    INSERT INTO public.auth_audit(event, target_actor, by_actor, ip_hash, meta)
    VALUES (v_event, p_target_actor, p_by_actor, NULL,
            v_meta || jsonb_build_object(
              'old_active', v_tgt.active, 'new_active', p_requested_active,
              'workspace_id', p_workspace_id, 'client_request_id', p_client_request_id
            ));

    -- No global session invalidation: only the TARGET's session_version moved.
    INSERT INTO public.auth_audit(event, target_actor, by_actor, ip_hash, meta)
    VALUES ('session_invalidated', p_target_actor, p_by_actor, NULL,
            jsonb_build_object('workspace_id', p_workspace_id, 'session_version', r.session_version));

    v_result := jsonb_build_object(
      'actor', r.actor, 'active', r.active, 'role', r.role,
      'session_version', r.session_version, 'failed_count', r.failed_count,
      'locked_until', r.locked_until, 'updated_at', r.updated_at, 'updated_by', r.updated_by
    );
  END IF;

  INSERT INTO public.access_management_idempotency
    (workspace_id, by_actor, by_sid_hash, action, client_request_id, request_hash, response_status, response_body)
  VALUES (p_workspace_id, p_by_actor, p_by_sid_hash, v_action, p_client_request_id, p_request_hash, 200, v_result);

  RETURN v_result;
END;
$function$

CREATE OR REPLACE FUNCTION public.auth_set_actor_pin_v2(p_target_actor text, p_expected_role text, p_hash text, p_ip_hash text, p_seen jsonb, p_caller_kind text, p_user_id uuid DEFAULT NULL::uuid, p_workspace_id uuid DEFAULT NULL::uuid, p_by_actor text DEFAULT NULL::text, p_confirm text DEFAULT NULL::text, p_meta jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_ws_id uuid; v_ws public.workspaces%ROWTYPE;
        v_by public.auth_actors%ROWTYPE; v_tgt public.auth_actors%ROWTYPE;
        r public.auth_actors%ROWTYPE;
        v_event text; v_now timestamptz := now();
        v_meta jsonb := COALESCE(p_meta, '{}'::jsonb);
        v_other record; v_seen jsonb; v_others int := 0; v_seen_count int;
        v_onboarding boolean := false;
BEGIN
  -- ── input guards (mirror the accepted B6A contract) ────────────────────────
  IF p_caller_kind NOT IN ('account_owner','operational_admin')
  THEN RAISE EXCEPTION 'AUTH_CALLER_KIND_INVALID' USING ERRCODE='22023'; END IF;
  IF p_target_actor IS NULL OR p_target_actor NOT IN ('owner','operator_primary','operator_backup','rider')
  THEN RAISE EXCEPTION 'AUTH_ACTOR_INVALID' USING ERRCODE='22023'; END IF;
  IF p_expected_role NOT IN ('admin','operator','rider')
  THEN RAISE EXCEPTION 'AUTH_ROLE_INVALID' USING ERRCODE='22023'; END IF;
  IF jsonb_typeof(v_meta) <> 'object' THEN RAISE EXCEPTION 'AUTH_META_INVALID' USING ERRCODE='22023'; END IF;
  IF length(v_meta::text) > 2048 THEN RAISE EXCEPTION 'AUTH_META_TOO_LARGE' USING ERRCODE='22023'; END IF;
  IF EXISTS (SELECT 1 FROM jsonb_object_keys(v_meta) k WHERE lower(k) = ANY (ARRAY[
       'pin','pin_hash','password','token','access_token','refresh_token','jwt','secret',
       'recovery_secret','authorization','api_key','apikey','bearer','cookie','raw_ip','confirmation']))
  THEN RAISE EXCEPTION 'AUTH_META_SENSITIVE_KEY' USING ERRCODE='22023'; END IF;
  IF p_ip_hash IS NULL OR btrim(p_ip_hash) = '' THEN RAISE EXCEPTION 'AUTH_IP_HASH_REQUIRED' USING ERRCODE='22023'; END IF;
  IF length(p_ip_hash) > 64 THEN RAISE EXCEPTION 'AUTH_IP_HASH_TOO_LONG' USING ERRCODE='22023'; END IF;
  IF p_hash IS NULL OR btrim(p_hash) = '' OR left(p_hash, 7) <> 'scrypt$'
  THEN RAISE EXCEPTION 'AUTH_HASH_INVALID' USING ERRCODE='22023'; END IF;
  IF p_seen IS NULL OR jsonb_typeof(p_seen) <> 'array'
  THEN RAISE EXCEPTION 'AUTH_SEEN_INVALID' USING ERRCODE='22023'; END IF;

  -- ── resolve the workspace from the TARGET, then serialise on it ────────────
  SELECT workspace_id INTO v_ws_id FROM public.auth_actors WHERE actor = p_target_actor;
  IF NOT FOUND THEN RAISE EXCEPTION 'AUTH_ACTOR_NOT_FOUND' USING ERRCODE='P0002'; END IF;
  IF v_ws_id IS NULL THEN RAISE EXCEPTION 'AUTH_ACTOR_WORKSPACE_UNASSIGNED' USING ERRCODE='22023'; END IF;

  -- The workspace row lock is taken by EVERY rotation in this workspace: it is the single
  -- serialisation point that makes the invariant hold across all targets and caller kinds.
  SELECT * INTO v_ws FROM public.workspaces WHERE id = v_ws_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'WORKSPACE_NOT_FOUND' USING ERRCODE='P0002'; END IF;
  IF v_ws.lifecycle_status <> 'active' THEN RAISE EXCEPTION 'WORKSPACE_NOT_ACTIVE' USING ERRCODE='22023'; END IF;

  -- deterministic actor locking (no deadlock between concurrent rotations)
  PERFORM 1 FROM public.auth_actors WHERE workspace_id = v_ws_id ORDER BY actor FOR UPDATE;

  SELECT * INTO v_tgt FROM public.auth_actors WHERE actor = p_target_actor;
  IF NOT FOUND THEN RAISE EXCEPTION 'AUTH_ACTOR_NOT_FOUND' USING ERRCODE='P0002'; END IF;
  IF v_tgt.workspace_id IS DISTINCT FROM v_ws_id THEN
    RAISE EXCEPTION 'AUTH_ROTATION_STALE' USING ERRCODE='40001';   -- re-homed while we waited
  END IF;
  IF v_tgt.role <> p_expected_role THEN RAISE EXCEPTION 'AUTH_TARGET_ROLE_MISMATCH' USING ERRCODE='22023'; END IF;

  -- ── authorization, per caller kind ─────────────────────────────────────────
  IF p_caller_kind = 'account_owner' THEN
    IF p_target_actor <> 'owner' THEN RAISE EXCEPTION 'AUTH_ACCOUNT_TARGET_FORBIDDEN' USING ERRCODE='P0001'; END IF;
    IF p_user_id IS NULL THEN RAISE EXCEPTION 'ACCOUNT_USER_REQUIRED' USING ERRCODE='22023'; END IF;
    IF p_workspace_id IS NULL OR p_workspace_id <> v_ws_id
    THEN RAISE EXCEPTION 'WORKSPACE_MISMATCH' USING ERRCODE='22023'; END IF;
    IF NOT EXISTS (
      SELECT 1 FROM public.workspace_memberships
       WHERE workspace_id = v_ws_id AND user_id = p_user_id
         AND role = 'workspace_owner' AND status = 'active'
    ) THEN RAISE EXCEPTION 'NOT_WORKSPACE_OWNER' USING ERRCODE='P0001'; END IF;
    v_onboarding := true;
  ELSE
    IF p_by_actor IS NULL THEN RAISE EXCEPTION 'AUTH_INITIATOR_REQUIRED' USING ERRCODE='22023'; END IF;
    SELECT * INTO v_by FROM public.auth_actors WHERE actor = p_by_actor;
    IF NOT FOUND THEN RAISE EXCEPTION 'AUTH_INITIATOR_NOT_FOUND' USING ERRCODE='P0002'; END IF;
    IF v_by.role <> 'admin' THEN RAISE EXCEPTION 'AUTH_NOT_ADMIN' USING ERRCODE='22023'; END IF;
    IF v_by.active <> true THEN RAISE EXCEPTION 'AUTH_INITIATOR_INACTIVE' USING ERRCODE='22023'; END IF;
    IF v_by.workspace_id IS DISTINCT FROM v_ws_id
    THEN RAISE EXCEPTION 'AUTH_INITIATOR_OTHER_WORKSPACE' USING ERRCODE='P0001'; END IF;
    -- accepted B6A rule: owner self-change requires the exact phrase (no normalization)
    IF p_by_actor = 'owner' AND p_target_actor = 'owner'
       AND p_confirm IS DISTINCT FROM 'CHANGE_OWNER_PIN'
    THEN RAISE EXCEPTION 'AUTH_CONFIRMATION_REQUIRED' USING ERRCODE='22023'; END IF;
  END IF;

  -- ── optimistic verification of Node's uniqueness check ─────────────────────
  FOR v_other IN
    SELECT actor, active, pin_hash FROM public.auth_actors
     WHERE workspace_id = v_ws_id AND actor <> p_target_actor ORDER BY actor
  LOOP
    v_others := v_others + 1;
    SELECT e INTO v_seen FROM jsonb_array_elements(p_seen) e
     WHERE e->>'actor' = v_other.actor LIMIT 1;
    IF v_seen IS NULL THEN
      RAISE EXCEPTION 'AUTH_ROTATION_STALE' USING ERRCODE='40001';
    END IF;
    IF ((v_seen->>'active')::boolean) IS DISTINCT FROM v_other.active
       OR (v_seen->>'pin_hash') IS DISTINCT FROM v_other.pin_hash THEN
      RAISE EXCEPTION 'AUTH_ROTATION_STALE' USING ERRCODE='40001';
    END IF;
  END LOOP;

  SELECT count(*) INTO v_seen_count FROM jsonb_array_elements(p_seen);
  IF v_seen_count <> v_others THEN
    RAISE EXCEPTION 'AUTH_ROTATION_STALE' USING ERRCODE='40001';
  END IF;

  -- ── rotate ONLY the requested, already-existing actor ──────────────────────
  v_event := CASE WHEN v_tgt.pin_hash IS NULL THEN 'pin_set' ELSE 'pin_change' END;

  UPDATE public.auth_actors
     SET pin_hash = p_hash, session_version = session_version + 1,
         failed_count = 0, locked_until = NULL, updated_at = v_now,
         updated_by = CASE WHEN p_caller_kind = 'operational_admin' THEN p_by_actor ELSE NULL END
   WHERE actor = p_target_actor
   RETURNING * INTO r;   -- active preserved; no actor is ever created here

  -- onboarding completes ONLY for owner via the account-owner path; first completion wins
  IF v_onboarding THEN
    UPDATE public.workspaces
       SET owner_pin_onboarding_completed_at = COALESCE(owner_pin_onboarding_completed_at, v_now),
           updated_at = v_now
     WHERE id = v_ws_id;
  END IF;

  INSERT INTO public.auth_audit(event, target_actor, by_actor, ip_hash, meta)
  VALUES (v_event, p_target_actor,
          CASE WHEN p_caller_kind = 'operational_admin' THEN p_by_actor ELSE NULL END,
          p_ip_hash,
          v_meta || jsonb_build_object('source', p_caller_kind, 'policy', 'six_digit'));

  RETURN jsonb_build_object('actor', r.actor, 'role', r.role, 'active', r.active,
    'session_version', r.session_version, 'failed_count', r.failed_count,
    'locked_until', r.locked_until, 'updated_at', r.updated_at, 'updated_by', r.updated_by,
    'changed', true, 'event', v_event, 'onboarding_completed', v_onboarding);
END;
$function$

CREATE OR REPLACE FUNCTION public.auth_set_actor_pin_v3(p_target_actor text, p_expected_role text, p_hash text, p_ip_hash text, p_seen jsonb, p_caller_kind text, p_key_id_current text, p_fingerprint_current text, p_key_id_previous text DEFAULT NULL::text, p_fingerprint_previous text DEFAULT NULL::text, p_user_id uuid DEFAULT NULL::uuid, p_workspace_id uuid DEFAULT NULL::uuid, p_by_actor text DEFAULT NULL::text, p_confirm text DEFAULT NULL::text, p_meta jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_ws_id uuid; v_ws public.workspaces%ROWTYPE;
        v_by public.auth_actors%ROWTYPE; v_tgt public.auth_actors%ROWTYPE;
        r public.auth_actors%ROWTYPE;
        v_event text; v_now timestamptz := now();
        v_meta jsonb := COALESCE(p_meta, '{}'::jsonb);
        v_other record; v_seen jsonb; v_others int := 0; v_seen_count int;
        v_onboarding boolean := false;
BEGIN
  -- ── input guards (mirror the accepted v2 contract; role check WIDENED, not removed) ──
  IF p_caller_kind NOT IN ('account_owner','operational_admin')
  THEN RAISE EXCEPTION 'AUTH_CALLER_KIND_INVALID' USING ERRCODE='22023'; END IF;
  IF p_target_actor IS NULL OR btrim(p_target_actor) = ''
  THEN RAISE EXCEPTION 'AUTH_ACTOR_INVALID' USING ERRCODE='22023'; END IF;
  -- No closed-list check here (see migration header) — p_expected_role need only be a
  -- non-empty string; the AUTHORITATIVE check is v_tgt.role <> p_expected_role below,
  -- against auth_actors' OWN CHECK-enforced vocabulary (whatever it currently accepts).
  IF p_expected_role IS NULL OR btrim(p_expected_role) = ''
  THEN RAISE EXCEPTION 'AUTH_ROLE_INVALID' USING ERRCODE='22023'; END IF;
  IF jsonb_typeof(v_meta) <> 'object' THEN RAISE EXCEPTION 'AUTH_META_INVALID' USING ERRCODE='22023'; END IF;
  IF length(v_meta::text) > 2048 THEN RAISE EXCEPTION 'AUTH_META_TOO_LARGE' USING ERRCODE='22023'; END IF;
  IF EXISTS (SELECT 1 FROM jsonb_object_keys(v_meta) k WHERE lower(k) = ANY (ARRAY[
       'pin','pin_hash','password','token','access_token','refresh_token','jwt','secret',
       'recovery_secret','authorization','api_key','apikey','bearer','cookie','raw_ip',
       'confirmation','fingerprint','pin_fingerprint','fingerprint_key','hmac_key']))
  THEN RAISE EXCEPTION 'AUTH_META_SENSITIVE_KEY' USING ERRCODE='22023'; END IF;
  IF p_ip_hash IS NULL OR btrim(p_ip_hash) = '' THEN RAISE EXCEPTION 'AUTH_IP_HASH_REQUIRED' USING ERRCODE='22023'; END IF;
  IF length(p_ip_hash) > 64 THEN RAISE EXCEPTION 'AUTH_IP_HASH_TOO_LONG' USING ERRCODE='22023'; END IF;
  IF p_hash IS NULL OR btrim(p_hash) = '' OR left(p_hash, 7) <> 'scrypt$'
  THEN RAISE EXCEPTION 'AUTH_HASH_INVALID' USING ERRCODE='22023'; END IF;
  IF p_seen IS NULL OR jsonb_typeof(p_seen) <> 'array'
  THEN RAISE EXCEPTION 'AUTH_SEEN_INVALID' USING ERRCODE='22023'; END IF;

  -- ── fingerprint parameter guards — NEW in v3 ────────────────────────────────
  IF p_key_id_current IS NULL OR p_key_id_current !~ '^k[0-9]+$'
  THEN RAISE EXCEPTION 'AUTH_FINGERPRINT_KEY_ID_INVALID' USING ERRCODE='22023'; END IF;
  IF p_fingerprint_current IS NULL OR btrim(p_fingerprint_current) = ''
  THEN RAISE EXCEPTION 'AUTH_FINGERPRINT_INVALID' USING ERRCODE='22023'; END IF;
  IF (p_key_id_previous IS NOT NULL) IS DISTINCT FROM (p_fingerprint_previous IS NOT NULL)
  THEN RAISE EXCEPTION 'AUTH_FINGERPRINT_PREVIOUS_INCOMPLETE' USING ERRCODE='22023'; END IF;
  IF p_key_id_previous IS NOT NULL THEN
    IF p_key_id_previous !~ '^k[0-9]+$' THEN RAISE EXCEPTION 'AUTH_FINGERPRINT_KEY_ID_INVALID' USING ERRCODE='22023'; END IF;
    IF btrim(p_fingerprint_previous) = '' THEN RAISE EXCEPTION 'AUTH_FINGERPRINT_INVALID' USING ERRCODE='22023'; END IF;
    IF p_key_id_previous = p_key_id_current THEN RAISE EXCEPTION 'AUTH_FINGERPRINT_KEY_IDS_MUST_DIFFER' USING ERRCODE='22023'; END IF;
  END IF;

  -- ── resolve the workspace from the TARGET, then serialise on it (unchanged from v2) ──
  SELECT workspace_id INTO v_ws_id FROM public.auth_actors WHERE actor = p_target_actor;
  IF NOT FOUND THEN RAISE EXCEPTION 'AUTH_ACTOR_NOT_FOUND' USING ERRCODE='P0002'; END IF;
  IF v_ws_id IS NULL THEN RAISE EXCEPTION 'AUTH_ACTOR_WORKSPACE_UNASSIGNED' USING ERRCODE='22023'; END IF;

  SELECT * INTO v_ws FROM public.workspaces WHERE id = v_ws_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'WORKSPACE_NOT_FOUND' USING ERRCODE='P0002'; END IF;
  IF v_ws.lifecycle_status <> 'active' THEN RAISE EXCEPTION 'WORKSPACE_NOT_ACTIVE' USING ERRCODE='22023'; END IF;

  -- deterministic actor locking (no deadlock between concurrent rotations)
  PERFORM 1 FROM public.auth_actors WHERE workspace_id = v_ws_id ORDER BY actor FOR UPDATE;

  SELECT * INTO v_tgt FROM public.auth_actors WHERE actor = p_target_actor;
  IF NOT FOUND THEN RAISE EXCEPTION 'AUTH_ACTOR_NOT_FOUND' USING ERRCODE='P0002'; END IF;
  IF v_tgt.workspace_id IS DISTINCT FROM v_ws_id THEN
    RAISE EXCEPTION 'AUTH_ROTATION_STALE' USING ERRCODE='40001';
  END IF;
  -- THE authoritative role check — against auth_actors' actual, current, CHECK-enforced
  -- role value, whatever vocabulary it currently accepts (legacy or V3).
  IF v_tgt.role <> p_expected_role THEN RAISE EXCEPTION 'AUTH_TARGET_ROLE_MISMATCH' USING ERRCODE='22023'; END IF;

  -- ── authorization, per caller kind (unchanged from v2) ─────────────────────
  IF p_caller_kind = 'account_owner' THEN
    IF p_target_actor <> 'owner' THEN RAISE EXCEPTION 'AUTH_ACCOUNT_TARGET_FORBIDDEN' USING ERRCODE='P0001'; END IF;
    IF p_user_id IS NULL THEN RAISE EXCEPTION 'ACCOUNT_USER_REQUIRED' USING ERRCODE='22023'; END IF;
    IF p_workspace_id IS NULL OR p_workspace_id <> v_ws_id
    THEN RAISE EXCEPTION 'WORKSPACE_MISMATCH' USING ERRCODE='22023'; END IF;
    IF NOT EXISTS (
      SELECT 1 FROM public.workspace_memberships
       WHERE workspace_id = v_ws_id AND user_id = p_user_id
         AND role = 'workspace_owner' AND status = 'active'
    ) THEN RAISE EXCEPTION 'NOT_WORKSPACE_OWNER' USING ERRCODE='P0001'; END IF;
    v_onboarding := true;
  ELSE
    IF p_by_actor IS NULL THEN RAISE EXCEPTION 'AUTH_INITIATOR_REQUIRED' USING ERRCODE='22023'; END IF;
    SELECT * INTO v_by FROM public.auth_actors WHERE actor = p_by_actor;
    IF NOT FOUND THEN RAISE EXCEPTION 'AUTH_INITIATOR_NOT_FOUND' USING ERRCODE='P0002'; END IF;
    IF v_by.role <> 'admin' THEN RAISE EXCEPTION 'AUTH_NOT_ADMIN' USING ERRCODE='22023'; END IF;
    IF v_by.active <> true THEN RAISE EXCEPTION 'AUTH_INITIATOR_INACTIVE' USING ERRCODE='22023'; END IF;
    IF v_by.workspace_id IS DISTINCT FROM v_ws_id
    THEN RAISE EXCEPTION 'AUTH_INITIATOR_OTHER_WORKSPACE' USING ERRCODE='P0001'; END IF;
    IF p_by_actor = 'owner' AND p_target_actor = 'owner'
       AND p_confirm IS DISTINCT FROM 'CHANGE_OWNER_PIN'
    THEN RAISE EXCEPTION 'AUTH_CONFIRMATION_REQUIRED' USING ERRCODE='22023'; END IF;
  END IF;

  -- ── optimistic verification of Node's uniqueness check (unchanged from v2) ──
  FOR v_other IN
    SELECT actor, active, pin_hash FROM public.auth_actors
     WHERE workspace_id = v_ws_id AND actor <> p_target_actor ORDER BY actor
  LOOP
    v_others := v_others + 1;
    SELECT e INTO v_seen FROM jsonb_array_elements(p_seen) e
     WHERE e->>'actor' = v_other.actor LIMIT 1;
    IF v_seen IS NULL THEN
      RAISE EXCEPTION 'AUTH_ROTATION_STALE' USING ERRCODE='40001';
    END IF;
    IF ((v_seen->>'active')::boolean) IS DISTINCT FROM v_other.active
       OR (v_seen->>'pin_hash') IS DISTINCT FROM v_other.pin_hash THEN
      RAISE EXCEPTION 'AUTH_ROTATION_STALE' USING ERRCODE='40001';
    END IF;
  END LOOP;

  SELECT count(*) INTO v_seen_count FROM jsonb_array_elements(p_seen);
  IF v_seen_count <> v_others THEN
    RAISE EXCEPTION 'AUTH_ROTATION_STALE' USING ERRCODE='40001';
  END IF;

  -- ── rotate ONLY the requested, already-existing actor (unchanged from v2) ──
  v_event := CASE WHEN v_tgt.pin_hash IS NULL THEN 'pin_set' ELSE 'pin_change' END;

  UPDATE public.auth_actors
     SET pin_hash = p_hash, session_version = session_version + 1,
         failed_count = 0, locked_until = NULL, updated_at = v_now,
         updated_by = CASE WHEN p_caller_kind = 'operational_admin' THEN p_by_actor ELSE NULL END
   WHERE actor = p_target_actor
   RETURNING * INTO r;   -- active preserved; no actor is ever created here

  -- ── NEW in v3: atomically write the fingerprint row(s), same transaction ───
  -- ON CONFLICT (actor, key_id) DO UPDATE: a re-rotation of the SAME actor under the
  -- SAME key_id updates in place (actor,key_id) is the fingerprint table's PK; a
  -- genuine cross-actor duplicate at (workspace_id,key_id,fingerprint) would violate
  -- that SEPARATE unique index and raise naturally — deliberately not caught here,
  -- since Node's slow-hash check above (via p_seen) already establishes uniqueness
  -- under the same workspace lock this function already holds.
  INSERT INTO public.auth_actor_pin_fingerprints (actor, key_id, workspace_id, fingerprint)
  VALUES (p_target_actor, p_key_id_current, v_ws_id, p_fingerprint_current)
  ON CONFLICT (actor, key_id) DO UPDATE SET fingerprint = EXCLUDED.fingerprint, created_at = v_now;

  IF p_key_id_previous IS NOT NULL THEN
    INSERT INTO public.auth_actor_pin_fingerprints (actor, key_id, workspace_id, fingerprint)
    VALUES (p_target_actor, p_key_id_previous, v_ws_id, p_fingerprint_previous)
    ON CONFLICT (actor, key_id) DO UPDATE SET fingerprint = EXCLUDED.fingerprint, created_at = v_now;
  END IF;

  IF v_onboarding THEN
    UPDATE public.workspaces
       SET owner_pin_onboarding_completed_at = COALESCE(owner_pin_onboarding_completed_at, v_now),
           updated_at = v_now
     WHERE id = v_ws_id;
  END IF;

  INSERT INTO public.auth_audit(event, target_actor, by_actor, ip_hash, meta)
  VALUES (v_event, p_target_actor,
          CASE WHEN p_caller_kind = 'operational_admin' THEN p_by_actor ELSE NULL END,
          p_ip_hash,
          v_meta || jsonb_build_object('source', p_caller_kind, 'policy', 'six_digit'));

  -- No PIN, hash, or fingerprint in the return value — matches v2 exactly.
  RETURN jsonb_build_object('actor', r.actor, 'role', r.role, 'active', r.active,
    'session_version', r.session_version, 'failed_count', r.failed_count,
    'locked_until', r.locked_until, 'updated_at', r.updated_at, 'updated_by', r.updated_by,
    'changed', true, 'event', v_event, 'onboarding_completed', v_onboarding);
END;
$function$

CREATE OR REPLACE FUNCTION public.begin_service_close_if_idle(p_service_date text DEFAULT NULL::text, p_source text DEFAULT 'backend'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_ds       jsonb;
  v_active   jsonb;
  v_marker   jsonb;
  v_close_id text;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtext('LA_DIECI_DRIVER_STATO'));

  INSERT INTO public.config(chiave, valore)
  VALUES ('DRIVER_STATO', '{}')
  ON CONFLICT (chiave) DO NOTHING;

  SELECT COALESCE(NULLIF(valore,'')::jsonb, '{}'::jsonb) INTO v_ds
  FROM public.config WHERE chiave = 'DRIVER_STATO' FOR UPDATE;
  v_active := v_ds->'active_trip';
  v_marker := v_ds->'service_closing';

  -- Crash/restart resume: the same in-progress close keeps its close_id and marker.
  IF v_marker IS NOT NULL AND v_marker <> 'null'::jsonb THEN
    RETURN jsonb_build_object('ok', true, 'code', 'OK', 'marker', v_marker,
                              'close_id', v_marker->>'close_id', 'resumed', true);
  END IF;

  -- Refuse to reset over an unclosed active trip (never destroy an active snapshot).
  IF v_active IS NOT NULL AND (v_active->>'status') = 'ACTIVE' THEN
    RETURN jsonb_build_object('ok', false, 'code', 'ACTIVE_TRIP_CONFLICT');
  END IF;

  v_close_id := gen_random_uuid()::text;
  v_marker := jsonb_build_object(
    'close_id',     v_close_id,
    'service_date', COALESCE(NULLIF(p_service_date, ''), CURRENT_DATE::text),
    'started_at',   to_jsonb(now()),
    'source',       COALESCE(NULLIF(p_source, ''), 'backend'),
    'phase',        'started'
  );

  -- Idle fields + service-closing marker; preserve schema / trip_seq / last_closed_trip.
  v_ds := v_ds || jsonb_build_object(
    'stato',              'LIBERO',
    'zona',               'null'::jsonb,
    'partito_alle',       'null'::jsonb,
    'n_ordini',           0,
    'rientro_stimato',    'null'::jsonb,
    'active_trip',        'null'::jsonb,
    'service_closing',    v_marker
  );
  IF NOT (v_ds ? 'schema')   THEN v_ds := v_ds || jsonb_build_object('schema', 2); END IF;
  IF NOT (v_ds ? 'trip_seq') THEN v_ds := v_ds || jsonb_build_object('trip_seq', 0); END IF;

  UPDATE public.config SET valore = v_ds::text WHERE chiave = 'DRIVER_STATO';
  RETURN jsonb_build_object('ok', true, 'code', 'OK', 'stato', 'LIBERO',
                            'marker', v_marker, 'close_id', v_close_id, 'resumed', false);
END;
$function$

CREATE OR REPLACE FUNCTION public.capture_closeout_snapshot(p_service_session_id uuid, p_closeout_correlation_id uuid, p_captured_by text, p_source text, p_payload jsonb, p_schema_version integer DEFAULT 1, p_payload_sha256 text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_session public.service_sessions%ROWTYPE;
  v_row     public.service_closeout_snapshots%ROWTYPE;
BEGIN
  IF p_service_session_id IS NULL OR p_closeout_correlation_id IS NULL THEN
    RETURN jsonb_build_object('ok',false,'code','INVALID_ARGUMENTS');
  END IF;
  IF p_captured_by IS NULL OR btrim(p_captured_by) = '' THEN
    RETURN jsonb_build_object('ok',false,'code','INVALID_ACTOR');
  END IF;
  IF p_source IS NULL OR btrim(p_source) = '' THEN
    RETURN jsonb_build_object('ok',false,'code','INVALID_SOURCE');
  END IF;
  IF p_payload IS NULL OR jsonb_typeof(p_payload) <> 'object' THEN
    RETURN jsonb_build_object('ok',false,'code','INVALID_SNAPSHOT_PAYLOAD');
  END IF;

  SELECT * INTO v_session FROM public.service_sessions WHERE id = p_service_session_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok',false,'code','SERVICE_SESSION_NOT_FOUND');
  END IF;
  IF v_session.lifecycle_semantics = 'economic_period_v1' AND v_session.service_kind IS NULL THEN
    RETURN jsonb_build_object('ok',false,'code','SERVICE_SESSION_MISSING_KIND');
  END IF;

  INSERT INTO public.service_closeout_snapshots(
    service_session_id, business_date, service_kind, lifecycle_semantics, closeout_correlation_id,
    schema_version, captured_by, source, payload, payload_sha256
  ) VALUES (
    v_session.id, v_session.business_date, v_session.service_kind, v_session.lifecycle_semantics, p_closeout_correlation_id,
    COALESCE(p_schema_version, 1), p_captured_by, p_source, p_payload, p_payload_sha256
  )
  ON CONFLICT (closeout_correlation_id) DO NOTHING
  RETURNING * INTO v_row;

  IF FOUND THEN
    RETURN jsonb_build_object('ok',true,'code','CAPTURED','created',true,'snapshot',to_jsonb(v_row));
  END IF;

  SELECT * INTO v_row FROM public.service_closeout_snapshots WHERE closeout_correlation_id = p_closeout_correlation_id;
  IF v_row.service_session_id IS DISTINCT FROM p_service_session_id THEN
    RETURN jsonb_build_object('ok',false,'code','CLOSEOUT_CORRELATION_ID_CONFLICT');
  END IF;
  RETURN jsonb_build_object('ok',true,'code','ALREADY_CAPTURED','created',false,'snapshot',to_jsonb(v_row));
END;
$function$

CREATE OR REPLACE FUNCTION public.classify_economic_period_v1(p_at timestamp with time zone DEFAULT clock_timestamp())
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_madrid timestamp;
  v_minutes_of_day integer;
BEGIN
  IF p_at IS NULL THEN
    RAISE EXCEPTION 'CLASSIFY_ECONOMIC_PERIOD_NULL_TIMESTAMP' USING ERRCODE='P0001';
  END IF;
  v_madrid := p_at AT TIME ZONE 'Europe/Madrid';
  v_minutes_of_day := extract(hour FROM v_madrid)::integer * 60 + extract(minute FROM v_madrid)::integer;
  RETURN CASE WHEN v_minutes_of_day >= 240 AND v_minutes_of_day < 1050
              THEN 'PRANZO' ELSE 'SERA' END;
END;
$function$

CREATE OR REPLACE FUNCTION public.close_rider_trip(p_trigger_order_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_ds        jsonb;
  v_active    jsonb;
  v_order_ids      text[];
  v_pending        int;
  v_raw_count      int;
  v_distinct_count int;
  v_snapshot_count int;
  v_found          int;
  v_now       timestamptz := now();
  v_closed    jsonb;
  v_canon     jsonb;
  v_base      jsonb;
  v_res       jsonb;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtext('LA_DIECI_DRIVER_STATO'));

  SELECT COALESCE(NULLIF(valore,'')::jsonb, '{}'::jsonb) INTO v_ds
  FROM public.config WHERE chiave = 'DRIVER_STATO' FOR UPDATE;
  v_active := NULLIF(v_ds->'active_trip', 'null'::jsonb);

  -- W6.3 CANONICAL CLOSE. Runs BEFORE any DRIVER_STATO shape validation on purpose: the
  -- canonical trip is the authority, and a malformed compatibility blob must not be able
  -- to strand a real trip ACTIVE. Membership is the COMPLETE frozen trip_members set.
  v_canon := public.trip_authority_active_trip_v1();
  IF COALESCE((v_canon->>'exists')::boolean, false) THEN
    IF p_trigger_order_id IS NOT NULL AND NOT (v_canon->'member_order_ids' ? p_trigger_order_id) THEN
      RETURN jsonb_build_object('ok', true, 'code', 'NON_MEMBER_NOOP');
    END IF;
    IF COALESCE((v_canon->>'missing_member_count')::int, 0) > 0 THEN
      RETURN jsonb_build_object('ok', false, 'code', 'MISSING_TRIP_MEMBER');
    END IF;
    IF COALESCE((v_canon->>'non_terminal_member_count')::int, 0) > 0 THEN
      RETURN jsonb_build_object('ok', false, 'code', 'EARLY_CLOSE');
    END IF;

    -- The transition itself re-validates completeness and terminality independently.
    v_res := public.trip_authority_close_active_trip_v1((v_canon->>'trip_id')::uuid);
    IF NOT COALESCE((v_res->>'ok')::boolean, false) THEN
      RETURN jsonb_build_object('ok', false, 'code', COALESCE(v_res->>'code', 'INTERNAL'));
    END IF;

    -- COMPATIBILITY OUTPUT ONLY, derived from the canonical facts just committed.
    v_base := CASE WHEN v_active IS NOT NULL AND jsonb_typeof(v_active) = 'object' THEN v_active ELSE '{}'::jsonb END;
    v_closed := v_base || jsonb_build_object(
      'trip_id',         v_canon->>'trip_id',
      'anchor_order_id', v_canon->'anchor_order_id',
      'order_ids',       v_canon->'member_order_ids',
      'manual_giro_ids', CASE WHEN v_canon->>'giro_id' IS NULL THEN '[]'::jsonb
                              ELSE jsonb_build_array(v_canon->>'giro_id') END,
      'zone_sequence',   v_canon->'zone_sequence',
      'n_orders',        COALESCE((v_canon->>'member_count')::int, 0),
      'started_at',      v_canon->'departed_at',
      'trip_version',    1,
      'status',          'CLOSED',
      'closed_at',       to_jsonb(v_now));

    v_ds := COALESCE(v_ds, '{}'::jsonb) || jsonb_build_object(
      'stato',            'LIBERO',
      'rientro_stimato',  to_jsonb(v_now),
      'active_trip',      'null'::jsonb,
      'last_closed_trip', v_closed
    );

    INSERT INTO public.config (chiave, valore) VALUES ('DRIVER_STATO', v_ds::text)
    ON CONFLICT (chiave) DO UPDATE SET valore = EXCLUDED.valore;

-- language-guard: allow-legacy n_ordini is the existing delivery_logs column name written verbatim by close_rider_trip, not new vocabulary
    INSERT INTO public.delivery_logs (zona, n_ordini, partito_alle, ultimo_entregado, rientro_stimato)
    VALUES (
      (v_canon->'zone_sequence'->>0),
      COALESCE(NULLIF((v_canon->>'member_count')::int, 0), 1),
      NULLIF(v_canon->>'departed_at', '')::timestamptz,
      v_now,
      v_now
    );

    RETURN jsonb_build_object('ok', true, 'code', 'OK', 'snapshot', v_closed);
  END IF;

  -- ── LEGACY (DRIVER_STATO-only) PATH, preserved verbatim from the pre-135 body ──
  IF v_active IS NOT NULL AND jsonb_typeof(v_active) <> 'object' THEN
    RETURN jsonb_build_object('ok', false, 'code', 'INVALID_TRIP_SNAPSHOT');
  END IF;

  IF v_active IS NULL OR (v_active->>'status') <> 'ACTIVE' THEN
    IF v_ds ? 'last_closed_trip' AND (v_ds->'last_closed_trip') <> 'null'::jsonb THEN
      RETURN jsonb_build_object('ok', true, 'code', 'IDEMPOTENT',
                                'snapshot', v_ds->'last_closed_trip');
    END IF;
    RETURN jsonb_build_object('ok', false, 'code', 'NO_ACTIVE_TRIP');
  END IF;

  IF p_trigger_order_id IS NOT NULL AND NOT (v_active->'order_ids' ? p_trigger_order_id) THEN
    RETURN jsonb_build_object('ok', true, 'code', 'NON_MEMBER_NOOP');
  END IF;

  IF jsonb_typeof(v_active->'order_ids') <> 'array' THEN
    RETURN jsonb_build_object('ok', false, 'code', 'INVALID_TRIP_SNAPSHOT');
  END IF;

  SELECT count(*), count(DISTINCT value::text)
    INTO v_raw_count, v_distinct_count
  FROM jsonb_array_elements_text(v_active->'order_ids') AS value;

  v_snapshot_count := CASE
    WHEN COALESCE(v_active->>'n_orders', '') ~ '^[0-9]+$' THEN (v_active->>'n_orders')::int
    ELSE -1
  END;

  IF v_raw_count <> v_distinct_count OR v_snapshot_count <> v_raw_count THEN
    RETURN jsonb_build_object('ok', false, 'code', 'INVALID_TRIP_SNAPSHOT');
  END IF;

  SELECT array_agg(DISTINCT value::text) INTO v_order_ids
  FROM jsonb_array_elements_text(v_active->'order_ids') AS value;

  SELECT count(*) INTO v_found FROM public.ordenes WHERE id = ANY(v_order_ids);
  IF v_found <> v_raw_count THEN
    RETURN jsonb_build_object('ok', false, 'code', 'MISSING_TRIP_MEMBER');
  END IF;

  SELECT count(*) INTO v_pending
  FROM public.ordenes
  WHERE id = ANY(v_order_ids)
-- language-guard: allow-legacy COMPLETATO is close_rider_trip's own pre-135 ordenes.estado terminal literal, reproduced verbatim, not new vocabulary
    AND estado NOT IN ('RETIRADO','COMPLETADO','COMPLETATO','CANCELADO','ANULADO');

  IF v_pending > 0 THEN
    RETURN jsonb_build_object('ok', false, 'code', 'EARLY_CLOSE');
  END IF;

  v_closed := (v_active
    || jsonb_build_object('status', 'CLOSED', 'closed_at', to_jsonb(v_now)));

  v_ds := v_ds || jsonb_build_object(
    'stato',            'LIBERO',
    'rientro_stimato',  to_jsonb(v_now),
    'active_trip',      'null'::jsonb,
    'last_closed_trip', v_closed
  );

  UPDATE public.config SET valore = v_ds::text WHERE chiave = 'DRIVER_STATO';

-- language-guard: allow-legacy n_ordini is the existing delivery_logs column name written verbatim by close_rider_trip, not new vocabulary
  INSERT INTO public.delivery_logs (zona, n_ordini, partito_alle, ultimo_entregado, rientro_stimato)
  VALUES (
    (v_active->'zone_sequence'->>0),
    COALESCE((v_active->>'n_orders')::int, 1),
    NULLIF(v_active->>'started_at', '')::timestamptz,
    v_now,
    v_now
  );

  RETURN jsonb_build_object('ok', true, 'code', 'OK', 'snapshot', v_closed);
END;
$function$

CREATE OR REPLACE FUNCTION public.close_service_session_v3(p_service_session_id uuid, p_closeout_correlation_id uuid, p_closed_by text, p_source text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_state   public.service_session_state%ROWTYPE;
  v_session public.service_sessions%ROWTYPE;
  v_bd_state public.business_day_lifecycle_state%ROWTYPE;
  v_trip    jsonb; -- 138:DECL
BEGIN
  IF p_service_session_id IS NULL OR p_closeout_correlation_id IS NULL THEN
    RETURN jsonb_build_object('ok',false,'code','INVALID_ARGUMENTS');
  END IF;
  IF p_closed_by IS NULL OR btrim(p_closed_by) = '' THEN
    RETURN jsonb_build_object('ok',false,'code','INVALID_ACTOR');
  END IF;
  IF p_source IS NULL OR btrim(p_source) = '' THEN
    RETURN jsonb_build_object('ok',false,'code','INVALID_SOURCE');
  END IF;

  PERFORM pg_advisory_xact_lock(hashtext('service_session_lifecycle'));

  -- 138:BEGIN close_l0
  -- ACTIVE_TRIP_SERVICE_CLOSE_EXCLUSION (migration 138) -- step 1 of 2: the dispatch lock (L0).
  -- Every trip writer (start_rider_trip_v2, close_rider_trip, rider_collect_and_complete_stop and
  -- the Giro Authority commands) already takes L0 as its FIRST statement. This close takes it
  -- here -- after the lifecycle lock and BEFORE the first row lock below -- so a close and a trip
  -- start are serialized by the SAME lock: whichever acquires L0 first decides, and the other one
  -- then judges the COMMITTED result of the first. Lock order of this function is now:
  -- lifecycle -> L0 -> service_session_state -> service_sessions -> business_day_lifecycle_state.
  -- No function takes L0 and then the lifecycle lock (checked against every live body), so no
  -- ABBA cycle exists. The intent sweep at the end of this function also reaches L0 (re-entrant in
  -- the same session, so a no-op from now on); were it to run, it would have taken L0 LATE, already
  -- holding the session row lock that the trip INSERT's foreign key needs -- the inverse order.
  PERFORM pg_advisory_xact_lock(hashtext('LA_DIECI_DRIVER_STATO'));
  -- 138:END close_l0

  SELECT * INTO v_state FROM public.service_session_state WHERE singleton = true FOR UPDATE;

  SELECT * INTO v_session FROM public.service_sessions
   WHERE id = p_service_session_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok',false,'code','SERVICE_SESSION_NOT_FOUND');
  END IF;

  IF v_session.status = 'closed' THEN
    IF v_state.recent_closed_session_id = v_session.id AND v_state.current_session_id IS NULL THEN
      RETURN jsonb_build_object('ok',true,'code','ALREADY_CLOSED','idempotent',true,'session',to_jsonb(v_session));
    END IF;
    RETURN jsonb_build_object('ok',false,'code','SESSION_CLOSE_IDENTITY_MISMATCH');
  END IF;

  IF v_session.status NOT IN ('open','closing') THEN
    RETURN jsonb_build_object('ok',false,'code','INVALID_SESSION_STATUS');
  END IF;

  IF v_state.current_session_id IS DISTINCT FROM v_session.id THEN
    RETURN jsonb_build_object('ok',false,'code','CURRENT_SESSION_MISMATCH');
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.service_closeouts
     WHERE service_session_id = p_service_session_id
       AND closeout_correlation_id = p_closeout_correlation_id
  ) THEN
    RETURN jsonb_build_object('ok',false,'code','CLOSEOUT_NOT_FOUND');
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.service_closeout_attempts
     WHERE closeout_correlation_id = p_closeout_correlation_id
       AND service_session_id = p_service_session_id
       AND status = 'active'
  ) THEN
    RETURN jsonb_build_object('ok',false,'code','ATTEMPT_NOT_ACTIVE');
  END IF;

  SELECT * INTO v_bd_state FROM public.business_day_lifecycle_state WHERE singleton = true FOR UPDATE;
  IF v_bd_state.current_period_id IS NOT NULL AND v_bd_state.current_period_id IS DISTINCT FROM v_session.id THEN
    RETURN jsonb_build_object('ok',false,'code','BUSINESS_DAY_POINTER_OWNERSHIP_MISMATCH');
  END IF;

  -- 138:BEGIN close_active_trip
  -- ACTIVE_TRIP_SERVICE_CLOSE_EXCLUSION (migration 138) -- step 2 of 2: the exclusion itself.
  -- A service must not become 'closed' while a canonical rider trip is ACTIVE for it. It is judged
  -- HERE, under L0, after every pre-existing check (so no earlier refusal and not the idempotent
  -- ALREADY_CLOSED answer change) and immediately before the terminal transition. The trip is read
  -- through public.trip_projection_v1 -- the SAME projection the backend preflight uses, and the
  -- only way in: this function is SECURITY INVOKER and trip_authority has no USAGE for
  -- service_role -- scoped to exactly this service (attribution is the trip's own
  -- service_session_id; rider_actor is never read, so an operator-dispatched trip blocks like a
  -- rider-dispatched one). Fail closed: anything other than a well-formed { ok:true, active:false }
  -- refuses the close. A refusal writes nothing and never touches the trip.
  SELECT public.trip_projection_v1(ARRAY[v_session.id]) INTO v_trip;
  IF v_trip IS NULL OR (v_trip->>'ok') IS DISTINCT FROM 'true'
     OR jsonb_typeof(v_trip->'active') IS DISTINCT FROM 'boolean' THEN
    RETURN jsonb_build_object('ok',false,'code','V3_CLOSE_RIDER_TRIP_UNVERIFIABLE','service_session_id',v_session.id);
  END IF;
  IF (v_trip->>'active')::boolean THEN
    RETURN jsonb_build_object('ok',false,'code','V3_CLOSE_ACTIVE_RIDER_TRIP',
      'service_session_id',v_session.id,'trip',v_trip - 'ok' - 'active');
  END IF;
  -- 138:END close_active_trip

  PERFORM set_config('ladieci.v3_close_authorized_session_id', v_session.id::text, true);

  UPDATE public.service_sessions
     SET status = 'closed', closed_at = now(), closed_by = p_closed_by,
         close_source = p_source, updated_at = now()
   WHERE id = v_session.id
  RETURNING * INTO v_session;

  UPDATE public.service_session_state
     SET current_session_id = NULL, recent_closed_session_id = v_session.id, updated_at = now()
   WHERE singleton = true;

  IF v_bd_state.current_period_id = v_session.id THEN
    PERFORM set_config('ladieci.business_day_pointer_authorized', 'true', true);
    UPDATE public.business_day_lifecycle_state SET current_period_id = NULL, updated_at = now() WHERE singleton = true;
  END IF;

  INSERT INTO public.service_session_audit(service_session_id, event_type, by_actor, source)
  VALUES (v_session.id, 'closed', p_closed_by, p_source);

  -- W5 INTENT ACTIVATION V1 -- giro intent close-sweep. Best-effort, own
  -- exception scope: a failure here must never roll back or block the close
  -- above, which has already fully committed its own writes by this point.
  -- The nil-UUID sentinel scope is deliberately never a real session id, so
  -- consume's own service_session_id membership check (unconditional, runs
  -- before any estado/eligibility branch) forces EXPIRED/SERVICE_CLOSED for
  -- every match -- never CONSUMED, never a Giro attachment.
  BEGIN
    PERFORM public.giro_authority_consume_intent_v1(
      gi.order_uid, 'giro_intent_service_close_sweep',
      ARRAY['00000000-0000-0000-0000-000000000000'::uuid])
    FROM giro_authority.giro_intents gi
    JOIN public.ordenes o ON o.order_uid = gi.order_uid
    WHERE gi.status = 'PENDING' AND o.service_session_id = v_session.id;
  EXCEPTION WHEN others THEN
    NULL;
  END;

  RETURN jsonb_build_object('ok',true,'code','V3_CLOSED','idempotent',false,'session',to_jsonb(v_session));
END;
$function$

CREATE OR REPLACE FUNCTION public.complete_closeout_attempt(p_closeout_correlation_id uuid, p_actor text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_row public.service_closeout_attempts%ROWTYPE;
BEGIN
  IF p_closeout_correlation_id IS NULL THEN
    RETURN jsonb_build_object('ok',false,'code','INVALID_ARGUMENTS');
  END IF;
  IF p_actor IS NULL OR btrim(p_actor) = '' THEN
    RETURN jsonb_build_object('ok',false,'code','INVALID_ACTOR');
  END IF;

  SELECT * INTO v_row FROM public.service_closeout_attempts
   WHERE closeout_correlation_id = p_closeout_correlation_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok',false,'code','ATTEMPT_NOT_FOUND');
  END IF;

  IF v_row.status = 'superseded' THEN
    RETURN jsonb_build_object('ok',false,'code','CANNOT_COMPLETE_SUPERSEDED_ATTEMPT');
  END IF;
  IF v_row.status = 'completed' THEN
    RETURN jsonb_build_object('ok',true,'code','ALREADY_COMPLETED','idempotent',true,'attempt',to_jsonb(v_row));
  END IF;

  UPDATE public.service_closeout_attempts
     SET status = 'completed', completed_at = now(), updated_at = now()
   WHERE closeout_correlation_id = p_closeout_correlation_id
  RETURNING * INTO v_row;

  RETURN jsonb_build_object('ok',true,'code','COMPLETED','idempotent',false,'attempt',to_jsonb(v_row));
END;
$function$

CREATE OR REPLACE FUNCTION public.consolidate_period_v1(p_workspace_id uuid, p_period_id uuid, p_by_actor text, p_by_role text, p_by_sid_hash text, p_reset_tickets boolean, p_client_request_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_existing     public.period_consolidations%ROWTYPE;
  v_period       public.service_sessions%ROWTYPE;
  v_day          public.business_days%ROWTYPE;
  v_cutoff       timestamptz;
  v_correlation  uuid;
  v_payload      jsonb;
  v_capture      jsonb;
  v_snapshot_id  uuid;
  v_new_epoch    integer;
  v_row          public.period_consolidations%ROWTYPE;
BEGIN
  IF p_period_id IS NULL THEN RETURN jsonb_build_object('ok',false,'code','INVALID_ARGUMENTS'); END IF;
  IF p_by_actor IS NULL OR btrim(p_by_actor) = '' THEN RETURN jsonb_build_object('ok',false,'code','INVALID_ACTOR'); END IF;
  IF p_by_role IS NULL OR btrim(p_by_role) = '' THEN RETURN jsonb_build_object('ok',false,'code','INVALID_ROLE'); END IF;
  IF p_client_request_id IS NULL OR btrim(p_client_request_id) = '' THEN RETURN jsonb_build_object('ok',false,'code','INVALID_CLIENT_REQUEST_ID'); END IF;
  IF p_reset_tickets IS NULL THEN RETURN jsonb_build_object('ok',false,'code','INVALID_RESET_FLAG'); END IF;

  IF p_workspace_id IS DISTINCT FROM public.mesa_singleton_workspace_v1() THEN
    RETURN jsonb_build_object('ok',false,'code','WORKSPACE_MISMATCH');
  END IF;

  PERFORM pg_advisory_xact_lock(hashtext('service_session_lifecycle'));

  SELECT * INTO v_existing FROM public.period_consolidations
   WHERE workspace_id = p_workspace_id AND client_request_id = p_client_request_id;
  IF FOUND THEN
    RETURN jsonb_build_object(
      'ok', true, 'code', 'ALREADY_CONSOLIDATED', 'idempotent', true,
      'consolidationId', v_existing.id, 'periodId', v_existing.period_id,
      'businessDayId', v_existing.business_day_id, 'cutoffAt', v_existing.cutoff_at,
      'resetTicketSequence', v_existing.reset_ticket_sequence,
      'newTicketEpoch', v_existing.new_ticket_epoch, 'snapshotId', v_existing.snapshot_id
    );
  END IF;

  SELECT * INTO v_period FROM public.service_sessions WHERE id = p_period_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok',false,'code','SERVICE_PERIOD_NOT_FOUND');
  END IF;
  IF v_period.business_day_id IS NULL THEN
    RETURN jsonb_build_object('ok',false,'code','SERVICE_PERIOD_LINEAGE_INVALID');
  END IF;
  SELECT * INTO v_day FROM public.business_days WHERE id = v_period.business_day_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok',false,'code','BUSINESS_DAY_LINEAGE_INVALID');
  END IF;

  v_cutoff := clock_timestamp();

  IF EXISTS (
    SELECT 1 FROM public.period_consolidations
     WHERE business_day_id = v_period.business_day_id AND cutoff_at > v_cutoff
  ) THEN
    RETURN jsonb_build_object('ok',false,'code','CONSOLIDATION_CUTOFF_NOT_MONOTONIC');
  END IF;

  v_correlation := gen_random_uuid();
  SELECT jsonb_build_object(
    'session', to_jsonb(v_period),
    'orders', COALESCE((SELECT jsonb_agg(to_jsonb(o)) FROM public.ordenes o WHERE o.service_session_id = p_period_id), '[]'::jsonb),
    'tableSessions', COALESCE((SELECT jsonb_agg(to_jsonb(t)) FROM public.table_sessions t WHERE t.service_session_id = p_period_id), '[]'::jsonb),
    'financialEvents', COALESCE((SELECT jsonb_agg(to_jsonb(f)) FROM public.order_financial_events f WHERE f.event_service_session_id = p_period_id), '[]'::jsonb)
  ) INTO v_payload;

  v_capture := public.capture_closeout_snapshot(
    p_period_id, v_correlation, p_by_actor, 'consolidate_period_v1', v_payload
  );
  IF (v_capture->>'ok')::boolean IS NOT TRUE THEN
    RETURN jsonb_build_object('ok',false,'code','CONSOLIDATION_SNAPSHOT_FAILED','detail',v_capture);
  END IF;
  v_snapshot_id := ((v_capture->'snapshot')->>'id')::uuid;
  IF v_snapshot_id IS NULL THEN
    RETURN jsonb_build_object('ok',false,'code','CONSOLIDATION_SNAPSHOT_ID_MISSING','detail',v_capture);
  END IF;

  v_new_epoch := NULL;
  IF p_reset_tickets THEN
    UPDATE public.business_days
       SET ticket_epoch = ticket_epoch + 1, next_ticket_number = 1
     WHERE id = v_period.business_day_id
     RETURNING ticket_epoch INTO v_new_epoch;

    PERFORM set_config('ladieci.business_day_pointer_authorized', 'true', true);
    UPDATE public.business_day_lifecycle_state
       SET current_ticket_epoch = v_new_epoch, updated_at = now()
     WHERE singleton = true AND current_business_day_id = v_period.business_day_id;
  END IF;

  INSERT INTO public.period_consolidations
    (workspace_id, business_day_id, period_id, cutoff_at, reset_ticket_sequence,
     new_ticket_epoch, snapshot_id, by_actor, by_role, by_sid_hash, client_request_id)
  VALUES
    (p_workspace_id, v_period.business_day_id, p_period_id, v_cutoff, p_reset_tickets,
     v_new_epoch, v_snapshot_id, p_by_actor, p_by_role, p_by_sid_hash, p_client_request_id)
  RETURNING * INTO v_row;

  RETURN jsonb_build_object(
    'ok', true, 'code', 'CONSOLIDATED', 'idempotent', false,
    'consolidationId', v_row.id, 'periodId', v_row.period_id,
    'businessDayId', v_row.business_day_id, 'cutoffAt', v_row.cutoff_at,
    'resetTicketSequence', v_row.reset_ticket_sequence,
    'newTicketEpoch', v_row.new_ticket_epoch, 'snapshotId', v_row.snapshot_id
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.create_archived_order_financial_resolution(p_service_session_id uuid, p_archived_order_id text, p_related_incident_id uuid, p_action_correlation_id uuid, p_resolution_type text, p_amount_cents integer, p_actor text, p_actor_role text, p_reason text, p_payment_method text DEFAULT NULL::text, p_reversed_event_id uuid DEFAULT NULL::uuid, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_session  public.service_sessions%ROWTYPE;
  v_incident public.service_incidents%ROWTYPE;
  v_prior    public.archived_order_financial_resolutions%ROWTYPE;
  v_reversed public.archived_order_financial_resolutions%ROWTYPE;
  v_row      public.archived_order_financial_resolutions%ROWTYPE;
  v_method   text;
  v_original integer;
  v_remaining integer;
  v_sequence integer;
BEGIN
  IF p_actor_role IS DISTINCT FROM 'admin' THEN
    RETURN jsonb_build_object('ok',false,'code','FINANCIAL_RESOLUTION_FORBIDDEN');
  END IF;
  IF p_service_session_id IS NULL OR p_archived_order_id IS NULL OR btrim(p_archived_order_id) = '' OR p_action_correlation_id IS NULL THEN
    RETURN jsonb_build_object('ok',false,'code','INVALID_ARGUMENTS');
  END IF;
  SELECT * INTO v_row FROM public.archived_order_financial_resolutions WHERE action_correlation_id = p_action_correlation_id;
  IF FOUND THEN
    IF v_row.service_session_id IS DISTINCT FROM p_service_session_id
       OR v_row.archived_order_id IS DISTINCT FROM p_archived_order_id
       OR v_row.related_incident_id IS DISTINCT FROM p_related_incident_id
       OR v_row.resolution_type IS DISTINCT FROM p_resolution_type
       OR v_row.amount_cents IS DISTINCT FROM p_amount_cents
       OR v_row.payment_method IS DISTINCT FROM (CASE WHEN p_payment_method IS NULL THEN NULL ELSE lower(btrim(p_payment_method)) END)
       OR v_row.reversed_event_id IS DISTINCT FROM p_reversed_event_id
    THEN
      RETURN jsonb_build_object('ok',false,'code','ACTION_CORRELATION_ID_CONFLICT');
    END IF;
    RETURN jsonb_build_object('ok',true,'code','ALREADY_RECORDED','created',false,'resolution',to_jsonb(v_row));
  END IF;

  IF p_related_incident_id IS NULL THEN
    RETURN jsonb_build_object('ok',false,'code','INCIDENT_LINK_REQUIRED');
  END IF;
  IF p_resolution_type IS NULL OR p_resolution_type NOT IN ('recovered_payment','write_off','reversal') THEN
    RETURN jsonb_build_object('ok',false,'code','INVALID_RESOLUTION_TYPE');
  END IF;
  IF p_amount_cents IS NULL OR p_amount_cents <= 0 THEN
    RETURN jsonb_build_object('ok',false,'code','INVALID_AMOUNT');
  END IF;
  IF p_actor IS NULL OR btrim(p_actor) = '' THEN
    RETURN jsonb_build_object('ok',false,'code','INVALID_ACTOR');
  END IF;
  IF p_reason IS NULL OR btrim(p_reason) = '' THEN
    RETURN jsonb_build_object('ok',false,'code','INVALID_REASON');
  END IF;

  IF p_resolution_type = 'recovered_payment' THEN
    v_method := lower(btrim(COALESCE(p_payment_method, '')));
    IF v_method NOT IN ('efectivo','tarjeta','bizum') THEN
      RETURN jsonb_build_object('ok',false,'code','INVALID_PAYMENT_METHOD');
    END IF;
  ELSE
    IF p_payment_method IS NOT NULL THEN
      RETURN jsonb_build_object('ok',false,'code','PAYMENT_METHOD_NOT_ALLOWED');
    END IF;
    v_method := NULL;
  END IF;

  SELECT * INTO v_session FROM public.service_sessions WHERE id = p_service_session_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok',false,'code','SERVICE_SESSION_NOT_FOUND');
  END IF;
  IF v_session.lifecycle_semantics = 'economic_period_v1' AND v_session.service_kind IS NULL THEN
    RETURN jsonb_build_object('ok',false,'code','SERVICE_SESSION_MISSING_KIND');
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.storico -- language-guard: allow-legacy storico is the existing table this RPC already queried verbatim pre-F-4C, byte-identical here, not new vocabulary
     WHERE service_session_id = p_service_session_id AND orden_id = p_archived_order_id
  ) THEN
    RETURN jsonb_build_object('ok',false,'code','ARCHIVED_ORDER_NOT_FOUND');
  END IF;

  SELECT * INTO v_incident FROM public.service_incidents WHERE id = p_related_incident_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok',false,'code','INCIDENT_NOT_FOUND');
  END IF;
  IF v_incident.service_session_id IS DISTINCT FROM p_service_session_id THEN
    RETURN jsonb_build_object('ok',false,'code','INCIDENT_SERVICE_MISMATCH');
  END IF;
  IF v_incident.category <> 'financial' THEN
    RETURN jsonb_build_object('ok',false,'code','INCIDENT_NOT_FINANCIAL');
  END IF;
  IF v_incident.order_id IS DISTINCT FROM p_archived_order_id THEN
    RETURN jsonb_build_object('ok',false,'code','INCIDENT_ORDER_MISMATCH');
  END IF;
  IF v_incident.financial_exposure_cents IS NULL THEN
    RETURN jsonb_build_object('ok',false,'code','INCIDENT_MISSING_EXPOSURE');
  END IF;

  PERFORM pg_advisory_xact_lock(hashtext(p_service_session_id::text || ':' || p_archived_order_id));

  SELECT * INTO v_prior FROM public.archived_order_financial_resolutions
   WHERE service_session_id = p_service_session_id AND archived_order_id = p_archived_order_id
   ORDER BY lineage_sequence DESC
   LIMIT 1;

  IF FOUND THEN
    v_original := v_prior.original_exposure_cents;
    v_sequence := v_prior.lineage_sequence + 1;
    IF p_related_incident_id IS DISTINCT FROM v_prior.related_incident_id THEN
      RETURN jsonb_build_object('ok',false,'code','INCIDENT_LINK_MISMATCH');
    END IF;
  ELSE
    v_original := v_incident.financial_exposure_cents;
    v_sequence := 1;
  END IF;

  IF p_resolution_type = 'reversal' THEN
    IF p_reversed_event_id IS NULL THEN
      RETURN jsonb_build_object('ok',false,'code','REVERSED_EVENT_REQUIRED');
    END IF;
    SELECT * INTO v_reversed FROM public.archived_order_financial_resolutions
     WHERE id = p_reversed_event_id
       AND service_session_id = p_service_session_id
       AND archived_order_id = p_archived_order_id;
    IF NOT FOUND THEN
      RETURN jsonb_build_object('ok',false,'code','REVERSED_EVENT_NOT_FOUND');
    END IF;
    IF v_reversed.resolution_type NOT IN ('recovered_payment','write_off') THEN
      RETURN jsonb_build_object('ok',false,'code','REVERSED_EVENT_NOT_REVERSIBLE');
    END IF;
    IF p_amount_cents IS DISTINCT FROM v_reversed.amount_cents THEN
      RETURN jsonb_build_object('ok',false,'code','REVERSAL_AMOUNT_MISMATCH');
    END IF;
    IF EXISTS (SELECT 1 FROM public.archived_order_financial_resolutions WHERE reversed_event_id = p_reversed_event_id) THEN
      RETURN jsonb_build_object('ok',false,'code','EVENT_ALREADY_REVERSED');
    END IF;
    v_remaining := COALESCE(v_prior.remaining_exposure_cents, v_original) + p_amount_cents;
    IF v_remaining > v_original THEN
      RETURN jsonb_build_object('ok',false,'code','REVERSAL_EXCEEDS_ORIGINAL');
    END IF;
  ELSE
    v_remaining := COALESCE(v_prior.remaining_exposure_cents, v_original) - p_amount_cents;
    IF v_remaining < 0 THEN
      RETURN jsonb_build_object('ok',false,'code','OVER_RESOLUTION_EXCEEDS_REMAINING');
    END IF;
  END IF;

  INSERT INTO public.archived_order_financial_resolutions(
    service_session_id, business_date, service_kind, lifecycle_semantics, archived_order_id, related_incident_id,
    action_correlation_id, resolution_type, reversed_event_id,
    original_exposure_cents, amount_cents, remaining_exposure_cents, lineage_sequence,
    payment_method, actor, role, reason, note
  ) VALUES (
    v_session.id, v_session.business_date, v_session.service_kind, v_session.lifecycle_semantics, p_archived_order_id, p_related_incident_id,
    p_action_correlation_id, p_resolution_type, p_reversed_event_id,
    v_original, p_amount_cents, v_remaining, v_sequence,
    v_method, p_actor, p_actor_role, p_reason, p_note
  )
  ON CONFLICT (action_correlation_id) DO NOTHING
  RETURNING * INTO v_row;

  IF FOUND THEN
    RETURN jsonb_build_object('ok',true,'code','RECORDED','created',true,'resolution',to_jsonb(v_row));
  END IF;

  SELECT * INTO v_row FROM public.archived_order_financial_resolutions WHERE action_correlation_id = p_action_correlation_id;
  RETURN jsonb_build_object('ok',true,'code','ALREADY_RECORDED','created',false,'resolution',to_jsonb(v_row));
END;
$function$

CREATE OR REPLACE FUNCTION public.create_service_closeout(p_service_session_id uuid, p_closeout_correlation_id uuid, p_closed_by text, p_source text, p_close_reason text, p_gross_sales_cents integer, p_net_sales_cents integer, p_total_refunds_cents integer, p_total_void_cents integer, p_paid_amount_cents integer, p_unpaid_exposure_cents integer, p_order_count integer, p_cash_amount_cents integer, p_card_amount_cents integer, p_bizum_amount_cents integer, p_other_amount_cents integer, p_open_orders_at_close integer, p_occupied_tables_at_close integer, p_kitchen_pending_count integer DEFAULT 0, p_listo_count integer DEFAULT 0, p_delivery_pending_count integer DEFAULT 0, p_incident_count integer DEFAULT 0, p_critical_incident_count integer DEFAULT 0, p_current_obligation_cents integer DEFAULT NULL::integer, p_over_collected_cents integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_session public.service_sessions%ROWTYPE;
  v_attempt public.service_closeout_attempts%ROWTYPE;
  v_row     public.service_closeouts%ROWTYPE;
BEGIN
  IF p_service_session_id IS NULL OR p_closeout_correlation_id IS NULL THEN
    RETURN jsonb_build_object('ok',false,'code','INVALID_ARGUMENTS');
  END IF;
  IF p_closed_by IS NULL OR btrim(p_closed_by) = '' THEN
    RETURN jsonb_build_object('ok',false,'code','INVALID_ACTOR');
  END IF;
  IF p_source IS NULL OR btrim(p_source) = '' THEN
    RETURN jsonb_build_object('ok',false,'code','INVALID_SOURCE');
  END IF;
  IF p_gross_sales_cents IS NULL OR p_gross_sales_cents < 0
     OR p_net_sales_cents IS NULL OR p_net_sales_cents < 0
     OR p_paid_amount_cents IS NULL OR p_paid_amount_cents < 0
     OR p_unpaid_exposure_cents IS NULL OR p_unpaid_exposure_cents < 0
     OR p_order_count IS NULL OR p_order_count < 0
  THEN
    RETURN jsonb_build_object('ok',false,'code','INVALID_FINANCIAL_FIELDS');
  END IF;
  -- FINALIZAR V3 CANONICAL CLOSEOUT V1 — the canonical-obligation pair is
  -- all-or-nothing (mirrors service_closeouts_canonical_obligation_pairing_chk)
  -- and non-negative when present.
  IF (p_current_obligation_cents IS NULL) <> (p_over_collected_cents IS NULL) THEN
    RETURN jsonb_build_object('ok',false,'code','INVALID_CANONICAL_OBLIGATION_PAIR');
  END IF;
  IF (p_current_obligation_cents IS NOT NULL AND p_current_obligation_cents < 0)
     OR (p_over_collected_cents IS NOT NULL AND p_over_collected_cents < 0)
  THEN
    RETURN jsonb_build_object('ok',false,'code','INVALID_CANONICAL_OBLIGATION_FIELDS');
  END IF;

  SELECT * INTO v_session FROM public.service_sessions WHERE id = p_service_session_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok',false,'code','SERVICE_SESSION_NOT_FOUND');
  END IF;
  IF v_session.lifecycle_semantics = 'economic_period_v1' AND v_session.service_kind IS NULL THEN
    RETURN jsonb_build_object('ok',false,'code','SERVICE_SESSION_MISSING_KIND');
  END IF;

  SELECT * INTO v_attempt FROM public.service_closeout_attempts
   WHERE closeout_correlation_id = p_closeout_correlation_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok',false,'code','ATTEMPT_NOT_FOUND');
  END IF;
  IF v_attempt.service_session_id IS DISTINCT FROM p_service_session_id THEN
    RETURN jsonb_build_object('ok',false,'code','ATTEMPT_SESSION_MISMATCH');
  END IF;
  IF v_attempt.status <> 'active' THEN
    RETURN jsonb_build_object('ok',false,'code','ATTEMPT_NOT_ACTIVE');
  END IF;

  INSERT INTO public.service_closeouts(
    service_session_id, closeout_correlation_id, business_date, service_kind, lifecycle_semantics,
    opened_at, closed_at, close_source, close_reason, closed_by,
    gross_sales_cents, net_sales_cents, total_discounts_cents, total_refunds_cents, total_void_cents,
    paid_amount_cents, unpaid_exposure_cents, order_count,
    cash_amount_cents, card_amount_cents, bizum_amount_cents, other_amount_cents,
    open_orders_at_close, occupied_tables_at_close,
    kitchen_pending_count, listo_count, delivery_pending_count,
    incident_count, critical_incident_count,
    current_obligation_cents, over_collected_cents
  ) VALUES (
    v_session.id, p_closeout_correlation_id, v_session.business_date, v_session.service_kind, v_session.lifecycle_semantics,
    v_session.opened_at, now(), p_source, p_close_reason, p_closed_by,
    p_gross_sales_cents, p_net_sales_cents, 0, COALESCE(p_total_refunds_cents, 0), COALESCE(p_total_void_cents, 0),
    p_paid_amount_cents, p_unpaid_exposure_cents, p_order_count,
    COALESCE(p_cash_amount_cents, 0), COALESCE(p_card_amount_cents, 0), COALESCE(p_bizum_amount_cents, 0), COALESCE(p_other_amount_cents, 0),
    COALESCE(p_open_orders_at_close, 0), COALESCE(p_occupied_tables_at_close, 0),
    COALESCE(p_kitchen_pending_count, 0), COALESCE(p_listo_count, 0), COALESCE(p_delivery_pending_count, 0),
    COALESCE(p_incident_count, 0), COALESCE(p_critical_incident_count, 0),
    -- Raw, never COALESCEd: NULL is the pre-canonical-contract epoch signal.
    p_current_obligation_cents, p_over_collected_cents
  )
  ON CONFLICT (closeout_correlation_id) DO NOTHING
  RETURNING * INTO v_row;

  IF FOUND THEN
    RETURN jsonb_build_object('ok',true,'code','CREATED','created',true,'closeout',to_jsonb(v_row));
  END IF;

  SELECT * INTO v_row FROM public.service_closeouts WHERE closeout_correlation_id = p_closeout_correlation_id;
  IF v_row.service_session_id IS DISTINCT FROM p_service_session_id THEN
    RETURN jsonb_build_object('ok',false,'code','CLOSEOUT_CORRELATION_ID_CONFLICT');
  END IF;
  RETURN jsonb_build_object('ok',true,'code','ALREADY_EXISTS','created',false,'closeout',to_jsonb(v_row));
END;
$function$

CREATE OR REPLACE FUNCTION public.create_service_incident(p_service_session_id uuid, p_closeout_correlation_id uuid, p_incident_type text, p_category text, p_severity text, p_detected_by text, p_entity_type text DEFAULT NULL::text, p_entity_id text DEFAULT NULL::text, p_order_id text DEFAULT NULL::text, p_table_session_id uuid DEFAULT NULL::uuid, p_giro_id text DEFAULT NULL::text, p_rider_id text DEFAULT NULL::text, p_financial_exposure_cents integer DEFAULT NULL::integer, p_snapshot_id uuid DEFAULT NULL::uuid, p_auto_resolve boolean DEFAULT false, p_auto_resolution_type text DEFAULT NULL::text, p_auto_resolution_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_session public.service_sessions%ROWTYPE;
  v_row     public.service_incidents%ROWTYPE;
BEGIN
  IF p_service_session_id IS NULL OR p_closeout_correlation_id IS NULL THEN
    RETURN jsonb_build_object('ok',false,'code','INVALID_ARGUMENTS');
  END IF;
  IF p_incident_type IS NULL OR btrim(p_incident_type) = '' THEN
    RETURN jsonb_build_object('ok',false,'code','INVALID_INCIDENT_TYPE');
  END IF;
  IF p_category NOT IN ('informational','operational','financial','integrity','security') THEN
    RETURN jsonb_build_object('ok',false,'code','INVALID_CATEGORY');
  END IF;
  IF p_severity NOT IN ('info','warning','critical') THEN
    RETURN jsonb_build_object('ok',false,'code','INVALID_SEVERITY');
  END IF;
  IF p_detected_by IS NULL OR btrim(p_detected_by) = '' THEN
    RETURN jsonb_build_object('ok',false,'code','INVALID_ACTOR');
  END IF;
  IF p_category = 'financial' AND p_financial_exposure_cents IS NULL THEN
    RETURN jsonb_build_object('ok',false,'code','FINANCIAL_EXPOSURE_REQUIRED');
  END IF;
  IF p_auto_resolve AND (p_auto_resolution_type IS NULL OR btrim(p_auto_resolution_type) = '') THEN
    RETURN jsonb_build_object('ok',false,'code','AUTO_RESOLUTION_TYPE_REQUIRED');
  END IF;

  SELECT * INTO v_session FROM public.service_sessions WHERE id = p_service_session_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok',false,'code','SERVICE_SESSION_NOT_FOUND');
  END IF;
  IF v_session.lifecycle_semantics = 'economic_period_v1' AND v_session.service_kind IS NULL THEN
    RETURN jsonb_build_object('ok',false,'code','SERVICE_SESSION_MISSING_KIND');
  END IF;

  IF p_snapshot_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.service_closeout_snapshots WHERE id = p_snapshot_id
  ) THEN
    RETURN jsonb_build_object('ok',false,'code','SNAPSHOT_NOT_FOUND');
  END IF;

  INSERT INTO public.service_incidents(
    service_session_id, business_date, service_kind, lifecycle_semantics, closeout_correlation_id, snapshot_id,
    incident_type, category, severity,
    entity_type, entity_id, order_id, table_session_id, giro_id, rider_id,
    financial_exposure_cents, detected_by,
    auto_resolved, resolution_status, resolution_type, resolved_at, resolved_by, resolution_note
  ) VALUES (
    v_session.id, v_session.business_date, v_session.service_kind, v_session.lifecycle_semantics, p_closeout_correlation_id, p_snapshot_id,
    p_incident_type, p_category, p_severity,
    p_entity_type, p_entity_id, p_order_id, p_table_session_id, p_giro_id, p_rider_id,
    p_financial_exposure_cents, p_detected_by,
    p_auto_resolve,
    CASE WHEN p_auto_resolve THEN 'resolved' ELSE 'pending' END,
    CASE WHEN p_auto_resolve THEN p_auto_resolution_type ELSE NULL END,
    CASE WHEN p_auto_resolve THEN now() ELSE NULL END,
    CASE WHEN p_auto_resolve THEN 'system' ELSE NULL END,
    CASE WHEN p_auto_resolve THEN p_auto_resolution_note ELSE NULL END
  )
  ON CONFLICT (closeout_correlation_id, incident_type, COALESCE(entity_type, ''), COALESCE(entity_id, ''))
  DO NOTHING
  RETURNING * INTO v_row;

  IF FOUND THEN
    RETURN jsonb_build_object('ok',true,'code','RECORDED','created',true,'incident',to_jsonb(v_row));
  END IF;

  SELECT * INTO v_row FROM public.service_incidents
   WHERE closeout_correlation_id = p_closeout_correlation_id
     AND incident_type = p_incident_type
     AND COALESCE(entity_type,'') = COALESCE(p_entity_type,'')
     AND COALESCE(entity_id,'')   = COALESCE(p_entity_id,'');
  RETURN jsonb_build_object('ok',true,'code','ALREADY_RECORDED','created',false,'incident',to_jsonb(v_row));
END;
$function$

CREATE OR REPLACE FUNCTION public.delete_conversation_if_not_active(p_wa_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_ds          jsonb;
  v_active      jsonb;
  v_order_ids   text[];
  v_protected   boolean;
  v_conv_del    int;
  v_msgs_del    int;
  v_orders_del  int;
BEGIN
  IF p_wa_id IS NULL OR p_wa_id !~ '\S' THEN
    RETURN jsonb_build_object('ok', false, 'code', 'INVALID_WA_ID');
  END IF;

  PERFORM pg_advisory_xact_lock(hashtext('LA_DIECI_DRIVER_STATO'));
  SELECT COALESCE(NULLIF(valore,'')::jsonb, '{}'::jsonb) INTO v_ds
  FROM public.config WHERE chiave = 'DRIVER_STATO' FOR UPDATE;
  v_active := v_ds->'active_trip';

  SELECT COALESCE(array_agg(id), ARRAY[]::text[]) INTO v_order_ids
  FROM public.ordenes
  WHERE wa_id = p_wa_id;

  IF v_active IS NOT NULL AND (v_active->>'status') = 'ACTIVE'
     AND EXISTS (
       SELECT 1
       FROM unnest(v_order_ids) AS oid(order_id)
       WHERE v_active->'order_ids' ? oid.order_id
     ) THEN
    RETURN jsonb_build_object('ok', false, 'code', 'ACTIVE_TRIP_MEMBER_CONFLICT');
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM public.ordenes o
     WHERE o.wa_id = p_wa_id
       AND public.order_has_economic_evidence_v1(o.id)
  ) INTO v_protected;

  IF v_protected THEN
    RETURN jsonb_build_object('ok', false, 'code', 'CONVERSATION_HAS_FINANCIAL_EVIDENCE');
  END IF;

  DELETE FROM public.conv WHERE wa_id = p_wa_id;
  GET DIAGNOSTICS v_conv_del = ROW_COUNT;
  DELETE FROM public.wa_msgs WHERE wa_id = p_wa_id;
  GET DIAGNOSTICS v_msgs_del = ROW_COUNT;
  DELETE FROM public.ordenes WHERE wa_id = p_wa_id;
  GET DIAGNOSTICS v_orders_del = ROW_COUNT;

  RETURN jsonb_build_object('ok', true, 'code', 'OK',
    'deleted', jsonb_build_object('conv', v_conv_del, 'wa_msgs', v_msgs_del, 'ordenes', v_orders_del));
END;
$function$

CREATE OR REPLACE FUNCTION public.delete_order_if_not_active(p_order_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_ds           jsonb;
  v_active       jsonb;
  v_deleted      int;
  v_found        boolean;
  v_has_evidence boolean;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtext('LA_DIECI_DRIVER_STATO'));
  SELECT COALESCE(NULLIF(valore,'')::jsonb, '{}'::jsonb) INTO v_ds
  FROM public.config WHERE chiave = 'DRIVER_STATO' FOR UPDATE;
  v_active := v_ds->'active_trip';

  -- Operational safety first, and independent of economics: an active-trip member is
  -- refused whether or not it carries money.
  IF v_active IS NOT NULL AND (v_active->>'status') = 'ACTIVE'
     AND (v_active->'order_ids' ? p_order_id) THEN
    RETURN jsonb_build_object('ok', false, 'code', 'ACTIVE_TRIP_MEMBER_CONFLICT');
  END IF;

  -- M-1 / EC-F2 — financial-evidence guard. v_found stays NULL/false when the order no
  -- longer exists (already deleted / never existed), which preserves the pre-existing
  -- idempotent-retry behavior below.
  SELECT true INTO v_found FROM public.ordenes WHERE id = p_order_id;

  IF v_found THEN
    v_has_evidence := public.order_has_economic_evidence_v1(p_order_id);
    IF v_has_evidence THEN
      RETURN jsonb_build_object('ok', false, 'code', 'ORDER_HAS_FINANCIAL_EVIDENCE');
    END IF;
  END IF;

  DELETE FROM public.ordenes WHERE id = p_order_id;
  GET DIAGNOSTICS v_deleted = ROW_COUNT;
  RETURN jsonb_build_object('ok', true, 'code', 'OK', 'deleted', v_deleted);
END;
$function$

CREATE OR REPLACE FUNCTION public.end_service_close(p_close_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_ds     jsonb;
  v_marker jsonb;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtext('LA_DIECI_DRIVER_STATO'));
  INSERT INTO public.config(chiave, valore) VALUES ('DRIVER_STATO', '{}') ON CONFLICT (chiave) DO NOTHING;
  SELECT COALESCE(NULLIF(valore,'')::jsonb, '{}'::jsonb) INTO v_ds
  FROM public.config WHERE chiave = 'DRIVER_STATO' FOR UPDATE;
  v_marker := NULLIF(v_ds->'service_closing', 'null'::jsonb);
  IF v_marker IS NULL THEN
    RETURN jsonb_build_object('ok', true, 'code', 'IDEMPOTENT');
  END IF;
  IF jsonb_typeof(v_marker) <> 'object'
     OR COALESCE(v_marker->>'close_id', '') <> COALESCE(p_close_id, '') THEN
    RETURN jsonb_build_object('ok', false, 'code', 'SERVICE_CLOSE_ID_MISMATCH');
  END IF;
  v_ds := v_ds - 'service_closing';
  UPDATE public.config SET valore = v_ds::text WHERE chiave = 'DRIVER_STATO';
  RETURN jsonb_build_object('ok', true, 'code', 'OK');
END;
$function$

CREATE OR REPLACE FUNCTION public.ensure_service_session(p_opened_by text, p_source text DEFAULT 'auto_entry'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_state    public.service_session_state%ROWTYPE;
  v_session  public.service_sessions%ROWTYPE;
  v_bd_state public.business_day_lifecycle_state%ROWTYPE;
  v_has_any  boolean;
  v_pointer_business_date   date;
  v_canonical_business_date date;
BEGIN
  IF p_opened_by IS NULL OR btrim(p_opened_by) = '' THEN
    RETURN jsonb_build_object('ok', false, 'code', 'INVALID_ACTOR');
  END IF;

  PERFORM pg_advisory_xact_lock(hashtext('service_session_lifecycle'));
  SELECT * INTO v_state FROM public.service_session_state WHERE singleton = true FOR UPDATE;
  IF (SELECT count(*) FROM public.service_sessions WHERE status IN ('open', 'closing')) > 1 THEN
    RETURN jsonb_build_object('ok', false, 'code', 'MULTIPLE_ACTIVE_SERVICE_SESSIONS');
  END IF;

  IF v_state.current_session_id IS NOT NULL THEN
    SELECT * INTO v_session FROM public.service_sessions WHERE id = v_state.current_session_id FOR UPDATE;
    IF NOT FOUND THEN
      RETURN jsonb_build_object('ok', false, 'code', 'SERVICE_SESSION_STATE_CORRUPT');
    END IF;
    IF v_session.status = 'closing' THEN
      RETURN jsonb_build_object('ok', false, 'code', 'SERVICE_SESSION_CLOSING', 'session', to_jsonb(v_session));
    END IF;

    -- STALE SERVICE PROTECTION V1 — the pointed-at open service is only the
    -- ordinary current service while its own business_date is still the
    -- canonical Business Day. Once a full Business Day has elapsed this must
    -- NOT short-circuit into REUSED (which is exactly how the F-11 guard in
    -- the branch below was being bypassed for a still-open stale service).
    -- Same authority F-11 uses; same typed shape. Reads only, writes
    -- nothing.
    v_canonical_business_date :=
      NULLIF(public.get_order_intake_context_v1() ->> 'businessDate', '')::date;
    IF v_session.business_date IS NOT NULL
       AND v_canonical_business_date IS NOT NULL
    THEN
      IF v_session.business_date < v_canonical_business_date THEN
        RETURN jsonb_build_object('ok', false, 'code', 'PREVIOUS_SERVICE_PENDING',
          'staleServiceSessionId', v_session.id,
          'staleBusinessDate', v_session.business_date,
          'currentBusinessDate', v_canonical_business_date,
          'staleBusinessDay', true,
          'session', to_jsonb(v_session));
      ELSIF v_session.business_date > v_canonical_business_date THEN
        -- REVIEW FIX — a FUTURE-dated current pointer is a lifecycle anomaly,
        -- never a "previous" service and never REUSED. Same canonical code as
        -- resolve_order_intake_context_v1's ELSIF above and as
        -- open_operational_service_v1's own defensive branch. Reads only.
        RETURN jsonb_build_object('ok', false, 'code', 'ACTIVE_SERVICE_BUSINESS_DAY_MISMATCH',
          'serviceSessionId', v_session.id,
          'serviceBusinessDate', v_session.business_date,
          'currentBusinessDate', v_canonical_business_date,
          'session', to_jsonb(v_session));
      END IF;
    END IF;

    RETURN jsonb_build_object('ok', true, 'code', 'REUSED', 'created', false, 'session', to_jsonb(v_session));
  END IF;

  SELECT * INTO v_bd_state FROM public.business_day_lifecycle_state WHERE singleton = true;
  IF v_bd_state.current_business_day_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'code', 'NO_OPEN_SERVICE');
  END IF;

  v_has_any := EXISTS (SELECT 1 FROM public.service_sessions WHERE business_day_id = v_bd_state.current_business_day_id);
  IF v_has_any THEN
    SELECT business_date INTO v_pointer_business_date
      FROM public.business_days WHERE id = v_bd_state.current_business_day_id;

    -- F-11 — canonical Business Day authority, reused verbatim from the
    -- order-intake path (04:00 Madrid overnight cutoff included). STABLE,
    -- writes nothing. PRESERVED UNCHANGED BY G-1.
    v_canonical_business_date :=
      NULLIF(public.get_order_intake_context_v1() ->> 'businessDate', '')::date;

    -- Downgrade ONLY on positive evidence of staleness. A missing date on
    -- either side leaves the stronger same-day protection in place.
    IF v_pointer_business_date IS NOT NULL
       AND v_canonical_business_date IS NOT NULL
       AND v_pointer_business_date <> v_canonical_business_date
    THEN
      RETURN jsonb_build_object('ok', false, 'code', 'NO_OPEN_SERVICE',
        'businessDayId', v_bd_state.current_business_day_id,
        'businessDate', v_pointer_business_date,
        'staleBusinessDay', true,
        'currentBusinessDate', v_canonical_business_date);
    END IF;

    -- G-1 — the pointer names the canonically-current Business Day and that
    -- day has already had a service, but none is active. Before G-1 this was
    -- the refusal the operational gate rendered as a blocking panel demanding
    -- a manual open (the retired code is not named here, for the same
    -- prosrc-scanning reason as above). It is simply IDLE: the next real order
    -- or the next table seating opens the next Operational Service by
    -- itself, via resolve_order_intake_context_v1 ->
    -- open_operational_service_v1('next_service_of_business_day').
    -- Same code and same shape as every other "nothing is open" answer this
    -- function already gives, plus one additive diagnostic key so the two
    -- idle shapes stay distinguishable in logs. This function still creates
    -- nothing and writes nothing -- asserted below.
    RETURN jsonb_build_object('ok', false, 'code', 'NO_OPEN_SERVICE',
      'businessDayId', v_bd_state.current_business_day_id,
      'businessDate', v_pointer_business_date,
      'hadPriorServiceToday', true);
  END IF;

  RETURN jsonb_build_object('ok', false, 'code', 'NO_OPEN_SERVICE',
    'businessDayId', v_bd_state.current_business_day_id,
    'businessDate', (SELECT business_date FROM public.business_days WHERE id = v_bd_state.current_business_day_id));
END;
$function$

CREATE OR REPLACE FUNCTION public.get_current_service_closeout_session()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_state public.service_session_state%ROWTYPE; v_session public.service_sessions%ROWTYPE;
BEGIN
  SELECT * INTO v_state FROM public.service_session_state WHERE singleton=true;
  IF (SELECT count(*) FROM public.service_sessions WHERE status IN ('open','closing')) > 1 THEN RETURN jsonb_build_object('ok',false,'code','MULTIPLE_ACTIVE_SERVICE_SESSIONS'); END IF;
  IF v_state.current_session_id IS NOT NULL THEN SELECT * INTO v_session FROM public.service_sessions WHERE id=v_state.current_session_id;
  ELSIF v_state.recent_closed_session_id IS NOT NULL THEN SELECT * INTO v_session FROM public.service_sessions WHERE id=v_state.recent_closed_session_id;
  ELSE RETURN jsonb_build_object('ok',true,'code','NO_SERVICE_SESSION'); END IF;
  IF NOT FOUND OR (v_state.current_session_id IS NOT NULL AND v_session.status NOT IN ('open','closing')) OR
     (v_state.current_session_id IS NULL AND v_session.status <> 'closed') THEN RETURN jsonb_build_object('ok',false,'code','SERVICE_SESSION_STATE_CORRUPT'); END IF;
  RETURN jsonb_build_object('ok',true,'code','OK','session',to_jsonb(v_session));
END $function$

CREATE OR REPLACE FUNCTION public.get_order_intake_context_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_madrid                    timestamp;
  v_minutes_of_day            integer;
  v_policy                    jsonb;
  v_business_date             date;
  v_service_kind               text;
  v_can_create_order           boolean;
  v_has_valid_current_service  boolean;
BEGIN
  v_madrid := clock_timestamp() AT TIME ZONE 'Europe/Madrid';
  v_minutes_of_day := extract(hour FROM v_madrid)::integer * 60 + extract(minute FROM v_madrid)::integer;
  v_policy := public.order_intake_policy_v1(v_minutes_of_day);
  v_business_date := CASE WHEN (v_policy->>'businessDateIsPreviousDay')::boolean
                          THEN (v_madrid::date - 1) ELSE v_madrid::date END;
  v_service_kind     := v_policy->>'serviceKind';
  v_can_create_order := (v_policy->>'mayCreateFirstService')::boolean;

  -- STALE SERVICE PROTECTION V1 — an open operational_service_v1 row from a
  -- PAST Business Day is not a valid current service, so this advisory-
  -- preflight fact must not report it as continuity (which would let
  -- orderIntakePolicy.js fail OPEN while the DB-canonical
  -- resolve_order_intake_context_v1 fails CLOSED). Scoped back to
  -- business_date = v_business_date — the pre-O-3 shape, for this read fact
  -- only. Same-business-day (and the O-2 overnight span, since v_business_date
  -- carries the 04:00 rollover) is unaffected.
  SELECT EXISTS (
    SELECT 1 FROM public.service_sessions
     WHERE status IN ('open','closing') AND lifecycle_semantics = 'operational_service_v1'
       AND business_date = v_business_date
  ) INTO v_has_valid_current_service;

  RETURN jsonb_build_object(
    'canCreateNewOrder', v_can_create_order,
    'businessDate', v_business_date,
    'serviceKind', v_service_kind,
    'hasValidCurrentService', v_has_valid_current_service
  );
END $function$

CREATE OR REPLACE FUNCTION public.giro_authority_attach_or_move_v1(p_giro_id text, p_order_uid uuid, p_actor text, p_operational_session_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
  v_from   text;
  v_trip   jsonb;
  v_reason text;
  d        record;
  dt       record;
  f        record;
BEGIN
  IF NOT giro_authority.actor_valid_v1(p_actor) OR p_giro_id IS NULL OR p_order_uid IS NULL THEN
    RETURN giro_authority.refusal_v1('INVALID_INPUT', NULL);
  END IF;
  IF NOT giro_authority.scope_valid_v1(p_operational_session_ids) THEN
    RETURN giro_authority.refusal_v1('SCOPE_UNAVAILABLE', NULL);
  END IF;

  SELECT gm.giro_id INTO v_from FROM giro_authority.giro_members gm WHERE gm.order_uid = p_order_uid;

  -- L0 (W6.1): the same dispatch lock start_rider_trip/rider_collect_and_complete_stop
  -- already take first -- must precede every Giro lock and trip-facts read below.
  PERFORM pg_advisory_xact_lock(hashtext('LA_DIECI_DRIVER_STATO'));

  -- L1: target giro + (if different) the order's current giro, ascending id -- same
  -- two-giro lock discipline as move_v1. A nonexistent p_giro_id simply locks zero
  -- rows here; existence is authoritatively checked below via derive_giros_v1.
  PERFORM 1 FROM public.manual_giros mg WHERE mg.id = ANY (ARRAY[p_giro_id, v_from]::text[]) ORDER BY mg.id FOR UPDATE;
  PERFORM giro_authority.lock_orders_v1(ARRAY[p_order_uid]);
  PERFORM 1 FROM public.ordenes o WHERE o.order_uid = p_order_uid FOR SHARE;

  -- Re-read membership now that locks are held (may have changed since the unlocked
  -- read above).
  SELECT gm.giro_id INTO v_from FROM giro_authority.giro_members gm WHERE gm.order_uid = p_order_uid;

  v_trip := giro_authority.trip_facts_v1();
  IF NOT (v_trip->>'available')::boolean THEN
    RETURN giro_authority.refusal_v1('UNVERIFIABLE', jsonb_build_object('reason', v_trip->>'reason'));
  END IF;

  SELECT * INTO dt FROM giro_authority.derive_giros_v1(ARRAY[p_giro_id], p_operational_session_ids, v_trip);
  IF dt.giro_id IS NULL THEN
    RETURN giro_authority.refusal_v1('GIRO_NOT_FOUND', NULL);
  END IF;

  SELECT * INTO f FROM giro_authority.order_facts_v1(ARRAY[p_order_uid], v_trip);
  v_reason := giro_authority.member_refusal_v1(f.present, f.estado, f.delivery_type, f.table_session_id,
                                               f.in_active_trip, f.service_session_id, p_operational_session_ids);
  IF v_reason = 'ORDER_NOT_FOUND' THEN
    RETURN giro_authority.refusal_v1('ORDER_NOT_FOUND', NULL);
  ELSIF v_reason IS NOT NULL THEN
    RETURN giro_authority.refusal_v1('ORDER_NOT_ELIGIBLE', jsonb_build_object('reason', v_reason));
  END IF;

  -- Already effectively in the target -> idempotent, regardless of the raw v_from row.
  IF p_order_uid = ANY (dt.effective_order_uids) THEN
    RETURN jsonb_build_object('ok', true, 'code', 'IDEMPOTENT', 'giro_id', p_giro_id);
  END IF;

  IF dt.giro_state IN ('IN_TRIP', 'DONE') THEN
    RETURN giro_authority.refusal_v1('GIRO_DEPARTED', jsonb_build_object('giro_id', p_giro_id, 'giro_state', dt.giro_state));
  END IF;
  IF dt.giro_state <> 'PLANNED' THEN
    RETURN giro_authority.refusal_v1('GIRO_NOT_PLANNED', jsonb_build_object('giro_id', p_giro_id, 'state_reason', dt.state_reason));
  END IF;
  IF f.business_date IS DISTINCT FROM dt.business_date THEN
    RETURN giro_authority.refusal_v1('SCOPE_MISMATCH', NULL);
  END IF;

  -- Effectively in ANOTHER giro right now -> safety check, then move.
  IF v_from IS NOT NULL THEN
    SELECT * INTO d FROM giro_authority.derive_giros_v1(ARRAY[v_from], p_operational_session_ids, v_trip);
    IF p_order_uid = ANY (d.effective_order_uids) AND d.giro_state IN ('IN_TRIP', 'DONE') THEN
      RETURN giro_authority.refusal_v1('GIRO_DEPARTED', jsonb_build_object('giro_id', v_from, 'giro_state', d.giro_state));
    END IF;
  END IF;

  -- put_member_v1 is itself an upsert (INSERT ... ON CONFLICT (order_uid) DO UPDATE),
  -- so the same call serves the unattached, same-target-already-handled-above, and
  -- other-giro cases uniformly -- no separate insert/update branch needed here.
  PERFORM giro_authority.put_member_v1(p_order_uid, p_giro_id, p_actor);
  PERFORM giro_authority.bump_facts_signal_v1();
  RETURN jsonb_build_object('ok', true, 'code', 'OK', 'giro_id', p_giro_id, 'order_uid', p_order_uid, 'moved_from', v_from);
END $function$

CREATE OR REPLACE FUNCTION public.giro_authority_attach_v1(p_giro_id text, p_order_uid uuid, p_actor text, p_operational_session_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
  v_trip   jsonb;
  v_reason text;
  v_other  text;
  d        record;
  f        record;
BEGIN
  IF NOT giro_authority.actor_valid_v1(p_actor) OR p_giro_id IS NULL OR p_order_uid IS NULL THEN
    RETURN giro_authority.refusal_v1('INVALID_INPUT', NULL);
  END IF;
  IF NOT giro_authority.scope_valid_v1(p_operational_session_ids) THEN
    RETURN giro_authority.refusal_v1('SCOPE_UNAVAILABLE', NULL);
  END IF;
  PERFORM 1 FROM public.manual_giros mg WHERE mg.id = p_giro_id FOR UPDATE;              -- L1
  IF NOT FOUND THEN
    RETURN giro_authority.refusal_v1('GIRO_NOT_FOUND', NULL);
  END IF;
  PERFORM giro_authority.lock_orders_v1(ARRAY[p_order_uid]);                              -- L2
  PERFORM 1 FROM public.ordenes o WHERE o.order_uid = p_order_uid FOR SHARE;              -- L4
  v_trip := giro_authority.trip_facts_v1();
  IF NOT (v_trip->>'available')::boolean THEN
    RETURN giro_authority.refusal_v1('UNVERIFIABLE', jsonb_build_object('reason', v_trip->>'reason'));
  END IF;

  SELECT * INTO d FROM giro_authority.derive_giros_v1(ARRAY[p_giro_id], p_operational_session_ids, v_trip);
  IF p_order_uid = ANY (d.effective_order_uids) THEN
    RETURN jsonb_build_object('ok', true, 'code', 'IDEMPOTENT', 'giro_id', p_giro_id);
  END IF;
  IF d.giro_state IN ('IN_TRIP', 'DONE') THEN
    RETURN giro_authority.refusal_v1('GIRO_DEPARTED', jsonb_build_object('giro_state', d.giro_state));
  END IF;
  IF d.giro_state <> 'PLANNED' THEN
    RETURN giro_authority.refusal_v1('GIRO_NOT_PLANNED', jsonb_build_object('state_reason', d.state_reason));
  END IF;
  SELECT * INTO f FROM giro_authority.order_facts_v1(ARRAY[p_order_uid], v_trip);
  v_reason := giro_authority.member_refusal_v1(f.present, f.estado, f.delivery_type, f.table_session_id,
                                               f.in_active_trip, f.service_session_id, p_operational_session_ids);
  IF v_reason = 'ORDER_NOT_FOUND' THEN
    RETURN giro_authority.refusal_v1('ORDER_NOT_FOUND', NULL);
  ELSIF v_reason IS NOT NULL THEN
    RETURN giro_authority.refusal_v1('ORDER_NOT_ELIGIBLE', jsonb_build_object('reason', v_reason));
  END IF;
  IF f.business_date IS DISTINCT FROM d.business_date THEN
    RETURN giro_authority.refusal_v1('SCOPE_MISMATCH', NULL);
  END IF;
  v_other := giro_authority.order_effective_giro_v1(p_order_uid, p_operational_session_ids, v_trip);
  IF v_other IS NOT NULL THEN
    RETURN giro_authority.refusal_v1('ORDER_ALREADY_IN_GIRO', jsonb_build_object('giro_id', v_other));
  END IF;
  PERFORM giro_authority.put_member_v1(p_order_uid, p_giro_id, p_actor);
  RETURN jsonb_build_object('ok', true, 'code', 'OK', 'giro_id', p_giro_id, 'order_uid', p_order_uid);
END $function$

CREATE OR REPLACE FUNCTION public.giro_authority_consume_intent_v1(p_order_uid uuid, p_actor text, p_operational_session_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
  v_row  giro_authority.giro_intents;
  v_trip jsonb;
  v_ctx  jsonb;
  v_cur  text;
  v_new  text;
  v_why  text;
  f      record;
  a      record;
  d      record;
BEGIN
  IF p_order_uid IS NULL OR NOT giro_authority.actor_valid_v1(p_actor) THEN
    RETURN giro_authority.refusal_v1('INVALID_INPUT', NULL);
  END IF;
  SELECT * INTO v_row FROM giro_authority.giro_intents gi WHERE gi.order_uid = p_order_uid;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', true, 'code', 'NO_INTENT');
  END IF;
  IF v_row.status <> 'PENDING' THEN
    RETURN giro_authority.intent_outcome_v1(v_row, true);
  END IF;
  -- L0 (W6.1): the same dispatch lock start_rider_trip/rider_collect_and_complete_stop
  -- already take first -- must precede every Giro lock and trip-facts read below,
  -- including the conditional L1 acquisition (GIRO target) two lines down.
  PERFORM pg_advisory_xact_lock(hashtext('LA_DIECI_DRIVER_STATO'));
  IF v_row.target_kind = 'GIRO' THEN
    PERFORM 1 FROM public.manual_giros mg WHERE mg.id = v_row.target_giro_id FOR UPDATE;   -- L1
  END IF;
  PERFORM giro_authority.lock_orders_v1(ARRAY[p_order_uid, v_row.target_order_uid]);      -- L2
  SELECT * INTO v_row FROM giro_authority.giro_intents gi WHERE gi.order_uid = p_order_uid FOR UPDATE;  -- L3
  IF v_row.status <> 'PENDING' THEN
    RETURN giro_authority.intent_outcome_v1(v_row, true);
  END IF;
  PERFORM 1 FROM public.ordenes o
   WHERE o.order_uid = ANY (ARRAY[p_order_uid, v_row.target_order_uid])
   ORDER BY o.order_uid FOR SHARE;                                                        -- L4

  IF NOT giro_authority.scope_valid_v1(p_operational_session_ids) THEN
    RETURN giro_authority.resolve_intent_v1(p_order_uid, 'REJECTED', 'CONSUME', 'SCOPE_UNAVAILABLE', NULL, p_actor, NULL);
  END IF;
  v_trip := giro_authority.trip_facts_v1();
  IF NOT (v_trip->>'available')::boolean THEN
    RETURN giro_authority.resolve_intent_v1(p_order_uid, 'REJECTED', 'CONSUME', 'UNVERIFIABLE', NULL, p_actor,
                                            jsonb_build_object('reason', v_trip->>'reason'));
  END IF;

  SELECT * INTO f FROM giro_authority.order_facts_v1(ARRAY[p_order_uid], v_trip);
  IF NOT f.present THEN
    RETURN giro_authority.resolve_intent_v1(p_order_uid, 'REJECTED', 'CONSUME', 'ORDER_NOT_ELIGIBLE', NULL, p_actor,
                                            jsonb_build_object('reason', 'ORDER_GONE'));
  END IF;
  IF NOT COALESCE(f.service_session_id = ANY (p_operational_session_ids), false) THEN
    RETURN giro_authority.resolve_intent_v1(p_order_uid, 'EXPIRED', 'EXPIRY', 'SERVICE_CLOSED', NULL, p_actor, NULL);
  END IF;
  IF f.in_active_trip OR f.estado = 'EN_ENTREGA'
     OR f.estado = ANY (giro_authority.delivered_states_v1())
     OR f.estado = ANY (giro_authority.cancelled_states_v1()) THEN
    RETURN giro_authority.resolve_intent_v1(p_order_uid, 'REJECTED', 'CONSUME', 'ORDER_NOT_ELIGIBLE', NULL, p_actor,
                                            jsonb_build_object('reason', 'ORDER_STATE', 'estado', f.estado));
  END IF;
  IF f.estado IS NULL OR f.estado NOT IN ('EN_COCINA', 'LISTO') THEN
    RETURN jsonb_build_object('ok', true, 'code', 'NOT_YET_OPERATIVE', 'status', 'PENDING', 'replay', false);
  END IF;
  v_ctx := v_row.order_context;
  IF (v_ctx->>'zona') IS DISTINCT FROM f.zona
     OR (v_ctx->>'hora') IS DISTINCT FROM f.hora
     OR (v_ctx->>'delivery_type') IS DISTINCT FROM f.delivery_type
     OR (v_ctx->>'service_session_id') IS DISTINCT FROM f.service_session_id::text THEN
    RETURN giro_authority.resolve_intent_v1(p_order_uid, 'REJECTED', 'CONSUME', 'ORDER_CHANGED', NULL, p_actor, NULL);
  END IF;
  IF f.delivery_type <> 'DOMICILIO' OR f.table_session_id IS NOT NULL THEN
    RETURN giro_authority.resolve_intent_v1(p_order_uid, 'REJECTED', 'CONSUME', 'ORDER_NOT_ELIGIBLE', NULL, p_actor,
                                            jsonb_build_object('reason', 'NOT_DELIVERY'));
  END IF;
  v_cur := giro_authority.order_effective_giro_v1(p_order_uid, p_operational_session_ids, v_trip);

  IF v_row.target_kind = 'GIRO' THEN
    IF v_cur = v_row.target_giro_id THEN
      RETURN giro_authority.resolve_intent_v1(p_order_uid, 'CONSUMED', 'CONSUME', 'ATTACHED', v_cur, p_actor,
                                              jsonb_build_object('already_member', true));
    END IF;
    IF v_cur IS NOT NULL THEN
      RETURN giro_authority.resolve_intent_v1(p_order_uid, 'REJECTED', 'CONSUME', 'ORDER_CHANGED', NULL, p_actor,
                                              jsonb_build_object('reason', 'ORDER_IN_OTHER_GIRO', 'giro_id', v_cur));
    END IF;
    SELECT * INTO d FROM giro_authority.derive_giros_v1(ARRAY[v_row.target_giro_id], p_operational_session_ids, v_trip);
    IF NOT FOUND THEN
      RETURN giro_authority.resolve_intent_v1(p_order_uid, 'REJECTED', 'CONSUME', 'TARGET_GONE', NULL, p_actor, NULL);
    END IF;
    IF d.giro_state IN ('IN_TRIP', 'DONE') THEN
      RETURN giro_authority.resolve_intent_v1(p_order_uid, 'REJECTED', 'CONSUME', 'TARGET_DEPARTED', NULL, p_actor,
                                              jsonb_build_object('giro_state', d.giro_state));
    END IF;
    IF d.giro_state <> 'PLANNED' OR d.business_date IS DISTINCT FROM f.business_date THEN
      RETURN giro_authority.resolve_intent_v1(p_order_uid, 'REJECTED', 'CONSUME', 'TARGET_GONE', NULL, p_actor,
                                              jsonb_build_object('state_reason', d.state_reason));
    END IF;
    IF giro_authority.target_fingerprint_v1('GIRO', v_row.target_giro_id, NULL) IS DISTINCT FROM v_row.target_fingerprint THEN
      RETURN giro_authority.resolve_intent_v1(p_order_uid, 'REJECTED', 'CONSUME', 'TARGET_CHANGED', NULL, p_actor, NULL);
    END IF;
    PERFORM giro_authority.put_member_v1(p_order_uid, v_row.target_giro_id, p_actor);
    PERFORM giro_authority.bump_facts_signal_v1();
    RETURN giro_authority.resolve_intent_v1(p_order_uid, 'CONSUMED', 'CONSUME', 'ATTACHED', v_row.target_giro_id, p_actor, NULL);
  END IF;

  -- ANCHOR: create {anchor, order}; the anchor must still be a free, operative single.
  IF v_cur IS NOT NULL THEN
    RETURN giro_authority.resolve_intent_v1(p_order_uid, 'REJECTED', 'CONSUME', 'ORDER_CHANGED', NULL, p_actor,
                                            jsonb_build_object('reason', 'ORDER_IN_OTHER_GIRO', 'giro_id', v_cur));
  END IF;
  SELECT * INTO a FROM giro_authority.order_facts_v1(ARRAY[v_row.target_order_uid], v_trip);
  IF NOT a.present THEN
    RETURN giro_authority.resolve_intent_v1(p_order_uid, 'REJECTED', 'CONSUME', 'TARGET_GONE', NULL, p_actor,
                                            jsonb_build_object('reason', 'ANCHOR_GONE'));
  END IF;
  IF a.in_active_trip OR a.estado = 'EN_ENTREGA' OR a.estado = ANY (giro_authority.delivered_states_v1()) THEN
    RETURN giro_authority.resolve_intent_v1(p_order_uid, 'REJECTED', 'CONSUME', 'TARGET_DEPARTED', NULL, p_actor, NULL);
  END IF;
  v_why := giro_authority.member_refusal_v1(a.present, a.estado, a.delivery_type, a.table_session_id,
                                            a.in_active_trip, a.service_session_id, p_operational_session_ids);
  IF v_why IS NOT NULL OR a.business_date IS DISTINCT FROM f.business_date THEN
    RETURN giro_authority.resolve_intent_v1(p_order_uid, 'REJECTED', 'CONSUME', 'TARGET_GONE', NULL, p_actor,
                                            jsonb_build_object('reason', COALESCE(v_why, 'BUSINESS_DATE')));
  END IF;
  IF giro_authority.order_effective_giro_v1(v_row.target_order_uid, p_operational_session_ids, v_trip) IS NOT NULL
     OR giro_authority.target_fingerprint_v1('ANCHOR', NULL, v_row.target_order_uid) IS DISTINCT FROM v_row.target_fingerprint THEN
    RETURN giro_authority.resolve_intent_v1(p_order_uid, 'REJECTED', 'CONSUME', 'TARGET_CHANGED', NULL, p_actor, NULL);
  END IF;
  v_new := giro_authority.insert_giro_v1(f.business_date, NULL, v_row.target_order_uid, p_actor);
  PERFORM giro_authority.put_member_v1(v_row.target_order_uid, v_new, p_actor);
  PERFORM giro_authority.put_member_v1(p_order_uid, v_new, p_actor);
  PERFORM giro_authority.bump_facts_signal_v1();
  RETURN giro_authority.resolve_intent_v1(p_order_uid, 'CONSUMED', 'CONSUME', 'GIRO_CREATED', v_new, p_actor, NULL);
END $function$

CREATE OR REPLACE FUNCTION public.giro_authority_create_or_move_v1(p_order_uids uuid[], p_hora_ref text, p_anchor_order_uid uuid, p_actor text, p_operational_session_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
  v_uids   uuid[];
  v_hora   text;
  v_trip   jsonb;
  v_reason text;
  v_dates  date[];
  v_id     text;
  v_effs   text[];
  v_moved  text[];
  r        record;
  d        record;
BEGIN
  IF NOT giro_authority.actor_valid_v1(p_actor) THEN
    RETURN giro_authority.refusal_v1('INVALID_INPUT', jsonb_build_object('field', 'actor'));
  END IF;
  IF NOT giro_authority.scope_valid_v1(p_operational_session_ids) THEN
    RETURN giro_authority.refusal_v1('SCOPE_UNAVAILABLE', NULL);
  END IF;
  v_uids := ARRAY(SELECT DISTINCT x FROM unnest(COALESCE(p_order_uids, '{}'::uuid[])) AS x WHERE x IS NOT NULL ORDER BY 1);
  IF cardinality(v_uids) < 2 THEN
    RETURN giro_authority.refusal_v1('INSUFFICIENT_MEMBERS', NULL);
  END IF;
  IF p_hora_ref IS NOT NULL AND btrim(p_hora_ref) <> '' THEN
    v_hora := giro_authority.hhmm_norm(p_hora_ref);
    IF v_hora IS NULL THEN
      RETURN giro_authority.refusal_v1('INVALID_INPUT', jsonb_build_object('field', 'hora_ref'));
    END IF;
  END IF;
  IF p_anchor_order_uid IS NOT NULL AND NOT (p_anchor_order_uid = ANY (v_uids)) THEN
    RETURN giro_authority.refusal_v1('INVALID_INPUT', jsonb_build_object('field', 'anchor_order_uid'));
  END IF;

  -- L0 (W6.1): the same dispatch lock start_rider_trip/rider_collect_and_complete_stop
  -- already take first -- must precede every Giro lock and trip-facts read below.
  PERFORM pg_advisory_xact_lock(hashtext('LA_DIECI_DRIVER_STATO'));

  -- Lock every giro any of these orders currently point to (L1, ascending id),
  -- then the orders themselves (L2 + L4) -- same discipline as every other command.
  PERFORM 1 FROM public.manual_giros mg
    WHERE mg.id IN (SELECT DISTINCT gm.giro_id FROM giro_authority.giro_members gm WHERE gm.order_uid = ANY (v_uids))
    ORDER BY mg.id FOR UPDATE;
  PERFORM giro_authority.lock_orders_v1(v_uids);
  PERFORM 1 FROM public.ordenes o WHERE o.order_uid = ANY (v_uids) ORDER BY o.order_uid FOR SHARE;

  v_trip := giro_authority.trip_facts_v1();
  IF NOT (v_trip->>'available')::boolean THEN
    RETURN giro_authority.refusal_v1('UNVERIFIABLE', jsonb_build_object('reason', v_trip->>'reason'));
  END IF;

  FOR r IN SELECT * FROM giro_authority.order_facts_v1(v_uids, v_trip) LOOP
    v_reason := giro_authority.member_refusal_v1(r.present, r.estado, r.delivery_type, r.table_session_id,
                                                 r.in_active_trip, r.service_session_id, p_operational_session_ids);
    IF v_reason = 'ORDER_NOT_FOUND' THEN
      RETURN giro_authority.refusal_v1('ORDER_NOT_FOUND', jsonb_build_object('order_uid', r.order_uid));
    ELSIF v_reason IS NOT NULL THEN
      RETURN giro_authority.refusal_v1('ORDER_NOT_ELIGIBLE', jsonb_build_object('order_uid', r.order_uid, 'reason', v_reason));
    END IF;
  END LOOP;
  SELECT array_agg(DISTINCT f.business_date) INTO v_dates FROM giro_authority.order_facts_v1(v_uids, v_trip) f;
  IF cardinality(v_dates) <> 1 OR v_dates[1] IS NULL THEN
    RETURN giro_authority.refusal_v1('SCOPE_MISMATCH', NULL);
  END IF;

  -- One computation of each order's current effective giro (or NULL) -- reused below,
  -- never recomputed.
  v_effs := ARRAY(SELECT giro_authority.order_effective_giro_v1(u, p_operational_session_ids, v_trip)
                    FROM unnest(v_uids) AS u);

  -- Idempotent replay: the exact requested set is already the sole effective
  -- membership of one existing giro.
  IF (SELECT count(DISTINCT e) FROM unnest(v_effs) AS e WHERE e IS NOT NULL) = 1
     AND NOT EXISTS (SELECT 1 FROM unnest(v_effs) AS e WHERE e IS NULL) THEN
    SELECT * INTO d FROM giro_authority.derive_giros_v1(ARRAY[v_effs[1]], p_operational_session_ids, v_trip);
    IF d.effective_order_uids = v_uids THEN
      RETURN jsonb_build_object('ok', true, 'code', 'IDEMPOTENT', 'giro_id', d.giro_id);
    END IF;
  END IF;

  -- Safety invariant shared with detach/move: never silently pull a member out of a
  -- giro whose rider already departed.
  FOR r IN SELECT DISTINCT e AS giro_id FROM unnest(v_effs) AS e WHERE e IS NOT NULL LOOP
    SELECT * INTO d FROM giro_authority.derive_giros_v1(ARRAY[r.giro_id], p_operational_session_ids, v_trip);
    IF d.giro_state IN ('IN_TRIP', 'DONE') THEN
      RETURN giro_authority.refusal_v1('GIRO_DEPARTED', jsonb_build_object('giro_id', r.giro_id, 'giro_state', d.giro_state));
    END IF;
  END LOOP;

  v_moved := ARRAY(SELECT DISTINCT e FROM unnest(v_effs) AS e WHERE e IS NOT NULL);
  DELETE FROM giro_authority.giro_members WHERE order_uid = ANY (v_uids);

  v_id := giro_authority.insert_giro_v1(v_dates[1], v_hora, p_anchor_order_uid, p_actor);
  PERFORM giro_authority.put_member_v1(u, v_id, p_actor) FROM unnest(v_uids) AS u;
  PERFORM giro_authority.bump_facts_signal_v1();
  RETURN jsonb_build_object('ok', true, 'code', 'OK', 'giro_id', v_id, 'business_date', v_dates[1],
                            'order_uids', to_jsonb(v_uids), 'moved_from', to_jsonb(v_moved));
END $function$

CREATE OR REPLACE FUNCTION public.giro_authority_create_v1(p_order_uids uuid[], p_hora_ref text, p_anchor_order_uid uuid, p_actor text, p_operational_session_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
  v_uids   uuid[];
  v_hora   text;
  v_trip   jsonb;
  v_reason text;
  v_dates  date[];
  v_effs   text[];
  v_id     text;
  r        record;
  d        record;
BEGIN
  IF NOT giro_authority.actor_valid_v1(p_actor) THEN
    RETURN giro_authority.refusal_v1('INVALID_INPUT', jsonb_build_object('field', 'actor'));
  END IF;
  IF NOT giro_authority.scope_valid_v1(p_operational_session_ids) THEN
    RETURN giro_authority.refusal_v1('SCOPE_UNAVAILABLE', NULL);
  END IF;
  v_uids := ARRAY(SELECT DISTINCT x FROM unnest(COALESCE(p_order_uids, '{}'::uuid[])) AS x WHERE x IS NOT NULL ORDER BY 1);
  IF cardinality(v_uids) < 2 THEN
    RETURN giro_authority.refusal_v1('INSUFFICIENT_MEMBERS', NULL);
  END IF;
  IF p_hora_ref IS NOT NULL AND btrim(p_hora_ref) <> '' THEN
    v_hora := giro_authority.hhmm_norm(p_hora_ref);
    IF v_hora IS NULL THEN
      RETURN giro_authority.refusal_v1('INVALID_INPUT', jsonb_build_object('field', 'hora_ref'));
    END IF;
  END IF;
  IF p_anchor_order_uid IS NOT NULL AND NOT (p_anchor_order_uid = ANY (v_uids)) THEN
    RETURN giro_authority.refusal_v1('INVALID_INPUT', jsonb_build_object('field', 'anchor_order_uid'));
  END IF;

  PERFORM giro_authority.lock_orders_v1(v_uids);                                         -- L2
  PERFORM 1 FROM public.ordenes o WHERE o.order_uid = ANY (v_uids) ORDER BY o.order_uid FOR SHARE;  -- L4
  v_trip := giro_authority.trip_facts_v1();
  IF NOT (v_trip->>'available')::boolean THEN
    RETURN giro_authority.refusal_v1('UNVERIFIABLE', jsonb_build_object('reason', v_trip->>'reason'));
  END IF;

  FOR r IN SELECT * FROM giro_authority.order_facts_v1(v_uids, v_trip) LOOP
    v_reason := giro_authority.member_refusal_v1(r.present, r.estado, r.delivery_type, r.table_session_id,
                                                 r.in_active_trip, r.service_session_id, p_operational_session_ids);
    IF v_reason = 'ORDER_NOT_FOUND' THEN
      RETURN giro_authority.refusal_v1('ORDER_NOT_FOUND', jsonb_build_object('order_uid', r.order_uid));
    ELSIF v_reason IS NOT NULL THEN
      RETURN giro_authority.refusal_v1('ORDER_NOT_ELIGIBLE', jsonb_build_object('order_uid', r.order_uid, 'reason', v_reason));
    END IF;
  END LOOP;
  SELECT array_agg(DISTINCT f.business_date) INTO v_dates FROM giro_authority.order_facts_v1(v_uids, v_trip) f;
  IF cardinality(v_dates) <> 1 OR v_dates[1] IS NULL THEN
    RETURN giro_authority.refusal_v1('SCOPE_MISMATCH', NULL);
  END IF;

  -- Never an implicit move: every order must be free. Exact replay -> IDEMPOTENT.
  v_effs := ARRAY(SELECT giro_authority.order_effective_giro_v1(u, p_operational_session_ids, v_trip)
                    FROM unnest(v_uids) AS u);
  IF EXISTS (SELECT 1 FROM unnest(v_effs) AS e WHERE e IS NOT NULL) THEN
    IF (SELECT count(DISTINCT e) FROM unnest(v_effs) AS e) = 1
       AND NOT EXISTS (SELECT 1 FROM unnest(v_effs) AS e WHERE e IS NULL) THEN
      SELECT * INTO d FROM giro_authority.derive_giros_v1(ARRAY[v_effs[1]], p_operational_session_ids, v_trip);
      IF d.effective_order_uids = v_uids THEN
        RETURN jsonb_build_object('ok', true, 'code', 'IDEMPOTENT', 'giro_id', d.giro_id);
      END IF;
    END IF;
    RETURN giro_authority.refusal_v1('ORDER_ALREADY_IN_GIRO',
      jsonb_build_object('giro_ids', (SELECT jsonb_agg(DISTINCT e) FROM unnest(v_effs) AS e WHERE e IS NOT NULL)));
  END IF;

  v_id := giro_authority.insert_giro_v1(v_dates[1], v_hora, p_anchor_order_uid, p_actor);
  PERFORM giro_authority.put_member_v1(u, v_id, p_actor) FROM unnest(v_uids) AS u;
  RETURN jsonb_build_object('ok', true, 'code', 'OK', 'giro_id', v_id, 'business_date', v_dates[1],
                            'order_uids', to_jsonb(v_uids));
END $function$

CREATE OR REPLACE FUNCTION public.giro_authority_detach_v1(p_order_uid uuid, p_actor text, p_operational_session_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
  v_giro  text;
  v_again text;
  v_trip  jsonb;
  d       record;
BEGIN
  IF NOT giro_authority.actor_valid_v1(p_actor) OR p_order_uid IS NULL THEN
    RETURN giro_authority.refusal_v1('INVALID_INPUT', NULL);
  END IF;
  IF NOT giro_authority.scope_valid_v1(p_operational_session_ids) THEN
    RETURN giro_authority.refusal_v1('SCOPE_UNAVAILABLE', NULL);
  END IF;
  SELECT gm.giro_id INTO v_giro FROM giro_authority.giro_members gm WHERE gm.order_uid = p_order_uid;
  IF v_giro IS NULL THEN
    RETURN jsonb_build_object('ok', true, 'code', 'IDEMPOTENT', 'reason', 'NOT_A_MEMBER');
  END IF;
  -- L0 (W6.1): the same dispatch lock start_rider_trip/rider_collect_and_complete_stop
  -- already take first -- must precede every Giro lock and trip-facts read below.
  PERFORM pg_advisory_xact_lock(hashtext('LA_DIECI_DRIVER_STATO'));
  PERFORM 1 FROM public.manual_giros mg WHERE mg.id = v_giro FOR UPDATE;                  -- L1
  PERFORM giro_authority.lock_orders_v1(ARRAY[p_order_uid]);                              -- L2
  SELECT gm.giro_id INTO v_again FROM giro_authority.giro_members gm WHERE gm.order_uid = p_order_uid;
  IF v_again IS DISTINCT FROM v_giro THEN
    RETURN giro_authority.refusal_v1('CONCURRENT_CHANGE', NULL);
  END IF;
  v_trip := giro_authority.trip_facts_v1();
  IF NOT (v_trip->>'available')::boolean THEN
    RETURN giro_authority.refusal_v1('UNVERIFIABLE', jsonb_build_object('reason', v_trip->>'reason'));
  END IF;
  SELECT * INTO d FROM giro_authority.derive_giros_v1(ARRAY[v_giro], p_operational_session_ids, v_trip);
  IF NOT (p_order_uid = ANY (d.effective_order_uids)) THEN
    RETURN jsonb_build_object('ok', true, 'code', 'IDEMPOTENT', 'reason', 'NOT_EFFECTIVE');
  END IF;
  IF d.giro_state IN ('IN_TRIP', 'DONE') THEN
    RETURN giro_authority.refusal_v1('GIRO_DEPARTED', jsonb_build_object('giro_state', d.giro_state));
  END IF;
  DELETE FROM giro_authority.giro_members gm WHERE gm.order_uid = p_order_uid AND gm.giro_id = v_giro;
  SELECT * INTO d FROM giro_authority.derive_giros_v1(ARRAY[v_giro], p_operational_session_ids, v_trip);
  PERFORM giro_authority.bump_facts_signal_v1();
  RETURN jsonb_build_object('ok', true, 'code', 'OK', 'giro_id', v_giro, 'giro_state_after', d.giro_state);
END $function$

CREATE OR REPLACE FUNCTION public.giro_authority_dissolve_v1(p_giro_id text, p_actor text, p_operational_session_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
  v_trip jsonb;
  d      record;
BEGIN
  IF NOT giro_authority.actor_valid_v1(p_actor) OR p_giro_id IS NULL THEN
    RETURN giro_authority.refusal_v1('INVALID_INPUT', NULL);
  END IF;
  IF NOT giro_authority.scope_valid_v1(p_operational_session_ids) THEN
    RETURN giro_authority.refusal_v1('SCOPE_UNAVAILABLE', NULL);
  END IF;
  -- L0 (W6.1): the same dispatch lock start_rider_trip/rider_collect_and_complete_stop
  -- already take first -- must precede every Giro lock and trip-facts read below.
  PERFORM pg_advisory_xact_lock(hashtext('LA_DIECI_DRIVER_STATO'));
  PERFORM 1 FROM public.manual_giros mg WHERE mg.id = p_giro_id FOR UPDATE;              -- L1
  IF NOT FOUND THEN
    RETURN giro_authority.refusal_v1('GIRO_NOT_FOUND', NULL);
  END IF;
  v_trip := giro_authority.trip_facts_v1();
  IF NOT (v_trip->>'available')::boolean THEN
    RETURN giro_authority.refusal_v1('UNVERIFIABLE', jsonb_build_object('reason', v_trip->>'reason'));
  END IF;
  SELECT * INTO d FROM giro_authority.derive_giros_v1(ARRAY[p_giro_id], p_operational_session_ids, v_trip);
  IF d.dissolved_at IS NOT NULL OR d.giro_state = 'DISSOLVED' THEN
    RETURN jsonb_build_object('ok', true, 'code', 'IDEMPOTENT', 'giro_id', p_giro_id, 'state_reason', d.state_reason);
  END IF;
  IF d.giro_state IN ('IN_TRIP', 'DONE') THEN
    RETURN giro_authority.refusal_v1('GIRO_DEPARTED', jsonb_build_object('giro_state', d.giro_state));
  END IF;
  UPDATE public.manual_giros mg
     SET dissolved_at = now(), dissolved_by = btrim(p_actor)
   WHERE mg.id = p_giro_id AND mg.dissolved_at IS NULL;
  PERFORM giro_authority.bump_facts_signal_v1();
  RETURN jsonb_build_object('ok', true, 'code', 'OK', 'giro_id', p_giro_id);
END $function$

CREATE OR REPLACE FUNCTION public.giro_authority_move_v1(p_order_uid uuid, p_to_giro_id text, p_actor text, p_operational_session_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
  v_from   text;
  v_again  text;
  v_trip   jsonb;
  v_locked integer;
  df       record;
  dt       record;
  f        record;
BEGIN
  IF NOT giro_authority.actor_valid_v1(p_actor) OR p_order_uid IS NULL OR p_to_giro_id IS NULL THEN
    RETURN giro_authority.refusal_v1('INVALID_INPUT', NULL);
  END IF;
  IF NOT giro_authority.scope_valid_v1(p_operational_session_ids) THEN
    RETURN giro_authority.refusal_v1('SCOPE_UNAVAILABLE', NULL);
  END IF;
  SELECT gm.giro_id INTO v_from FROM giro_authority.giro_members gm WHERE gm.order_uid = p_order_uid;
  IF v_from IS NULL THEN
    RETURN giro_authority.refusal_v1('ORDER_NOT_IN_GIRO', NULL);
  END IF;
  WITH l AS (SELECT mg.id FROM public.manual_giros mg WHERE mg.id IN (v_from, p_to_giro_id) ORDER BY mg.id FOR UPDATE)
  SELECT count(*) INTO v_locked FROM l;                                                  -- L1
  IF v_locked < (CASE WHEN v_from = p_to_giro_id THEN 1 ELSE 2 END) THEN
    RETURN giro_authority.refusal_v1('GIRO_NOT_FOUND', NULL);
  END IF;
  PERFORM giro_authority.lock_orders_v1(ARRAY[p_order_uid]);                              -- L2
  PERFORM 1 FROM public.ordenes o WHERE o.order_uid = p_order_uid FOR SHARE;              -- L4
  SELECT gm.giro_id INTO v_again FROM giro_authority.giro_members gm WHERE gm.order_uid = p_order_uid;
  IF v_again IS DISTINCT FROM v_from THEN
    RETURN giro_authority.refusal_v1('CONCURRENT_CHANGE', NULL);
  END IF;
  v_trip := giro_authority.trip_facts_v1();
  IF NOT (v_trip->>'available')::boolean THEN
    RETURN giro_authority.refusal_v1('UNVERIFIABLE', jsonb_build_object('reason', v_trip->>'reason'));
  END IF;
  SELECT * INTO df FROM giro_authority.derive_giros_v1(ARRAY[v_from], p_operational_session_ids, v_trip);
  IF NOT (p_order_uid = ANY (df.effective_order_uids)) THEN
    RETURN giro_authority.refusal_v1('ORDER_NOT_IN_GIRO', jsonb_build_object('reason', 'NOT_EFFECTIVE'));
  END IF;
  IF v_from = p_to_giro_id THEN
    RETURN jsonb_build_object('ok', true, 'code', 'IDEMPOTENT', 'giro_id', p_to_giro_id);
  END IF;
  IF df.giro_state IN ('IN_TRIP', 'DONE') THEN
    RETURN giro_authority.refusal_v1('GIRO_DEPARTED', jsonb_build_object('giro_id', v_from));
  END IF;
  SELECT * INTO dt FROM giro_authority.derive_giros_v1(ARRAY[p_to_giro_id], p_operational_session_ids, v_trip);
  IF dt.giro_state IN ('IN_TRIP', 'DONE') THEN
    RETURN giro_authority.refusal_v1('GIRO_DEPARTED', jsonb_build_object('giro_id', p_to_giro_id));
  END IF;
  IF dt.giro_state <> 'PLANNED' THEN
    RETURN giro_authority.refusal_v1('GIRO_NOT_PLANNED', jsonb_build_object('giro_id', p_to_giro_id, 'state_reason', dt.state_reason));
  END IF;
  SELECT * INTO f FROM giro_authority.order_facts_v1(ARRAY[p_order_uid], v_trip);
  IF f.business_date IS DISTINCT FROM dt.business_date THEN
    RETURN giro_authority.refusal_v1('SCOPE_MISMATCH', NULL);
  END IF;
  UPDATE giro_authority.giro_members gm
     SET giro_id = p_to_giro_id, created_at = now(), created_by = btrim(p_actor)
   WHERE gm.order_uid = p_order_uid AND gm.giro_id = v_from;
  SELECT * INTO df FROM giro_authority.derive_giros_v1(ARRAY[v_from], p_operational_session_ids, v_trip);
  RETURN jsonb_build_object('ok', true, 'code', 'OK', 'from_giro_id', v_from, 'to_giro_id', p_to_giro_id,
                            'from_giro_state_after', df.giro_state);
END $function$

